Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1750-bnei-yisrael-the-children-of-israel-1"],{story:"בסיפור המקראי, צאצאי יעקב/ישראל נודעים בשם בני ישראל. שנים־עשר השבטים מיוחסים במסורת לבניו ולמשפחתו של יעקב. אירוע זה מסביר את משמעות השם לפני שציר הזמן מגיע לעדויות החוץ־מקראיות העצמאיות על ישראל.",context:"זוהי מסגרת מסורתית של יוחסין וזהות שנשמרה בתנ״ך. אין לראות בה הוכחה ארכאולוגית למשפחה היסטורית אחת שממנה בהכרח יצאו כל בני ישראל המאוחרים.",aftermath:"המונח בני ישראל נעשה כינוי קולקטיבי חוזר בתורה ובספרות המקראית המאוחרת.",sourceStatus:"סיפור מקראי מסורתי"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1750-bnei-yisrael-the-children-of-israel-1"],{story:"في الرواية التوراتية، أصبح نسل يعقوب/إسرائيل يُعرف باسم بني إسرائيل. وتُنسب الأسباط الاثنا عشر تقليديًا إلى أبناء يعقوب وعائلته. يوضح هذا الحدث معنى الاسم قبل أن يصل الخط الزمني إلى الإشارات المستقلة الموثقة إلى إسرائيل.",context:"هذا إطار تقليدي للنسب والهوية محفوظ في الكتاب المقدس العبري. ولا ينبغي الخلط بينه وبين دليل أثري يثبت وجود عائلة تاريخية واحدة انحدر منها جميع الإسرائيليين اللاحقين.",aftermath:"أصبح تعبير بني إسرائيل تسمية جماعية متكررة في التوراة وفي الأدب الكتابي اللاحق.",sourceStatus:"رواية توراتية تقليدية"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1650-israel-s-family-goes-down-to-egypt-2"],{story:"ספר בראשית מתאר את יעקב/ישראל ובני ביתו עוברים למצרים בזמן רעב, לאחר שיוסף הגיע שם לעמדת סמכות. זהו חלק מסיפור המקור המקראי של בני ישראל; לא זוהתה עדות מצרית עצמאית ומבוססת המתעדת את יעקב או את יוסף.",context:"האירוע נכלל משום שהוא יסודי למסורת המובילה לסיפור יציאת מצרים. מיקומו בזמן משוער ואין לראות בו תאריך ארכאולוגי מבוסס.",aftermath:"בהמשך מתאר הסיפור המקראי את צאצאי ישראל מתרבים במצרים ונכפים לעבודת כפייה.",sourceStatus:"סיפור מקראי מסורתי — התאריך אינו ודאי מבחינה היסטורית"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1650-israel-s-family-goes-down-to-egypt-2"],{story:"يصف سفر التكوين انتقال يعقوب/إسرائيل وأهل بيته إلى مصر أثناء مجاعة، بعد أن وصل يوسف هناك إلى منصب ذي سلطة. وهذا جزء من رواية الأصل التوراتية لبني إسرائيل؛ ولم يُعثر على سجل مصري مستقل وموثوق يوثق يعقوب أو يوسف.",context:"أُدرج هذا الحدث لأنه أساسي في التقليد الذي يقود إلى قصة الخروج. موضعه الزمني تقريبي ولا ينبغي اعتباره تاريخًا أثريًا مثبتًا.",aftermath:"تصف الرواية التوراتية لاحقًا ازدياد نسل إسرائيل في مصر وإخضاعهم للعمل القسري.",sourceStatus:"رواية توراتية تقليدية — التاريخ غير مؤكد تاريخيًا"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1300-enslavement-of-bnei-yisrael-in-egypt-3"],{story:"ספר שמות מתאר פרעה חדש המשעבד את בני ישראל ומטיל עליהם עבודת כפייה. הסיפור הוא יסודי להיסטוריה ולזהות היהודית, אך היסטוריונים לא מצאו עדות עצמאית המבססת את השעבוד המקראי בהיקף או בצורה המתוארים.",context:"האתר מציג זאת כמסורת מקראית ולא כאירוע מצרי המתוארך בוודאות. במצרים העתיקה אכן התקיימו עבודות כפייה ועבדות, אך עובדה זו לבדה אינה מאמתת באופן עצמאי את סיפור יציאת מצרים.",aftermath:"לפי הסיפור המקראי, הדיכוי מוביל להנהגתו של משה וליציאת בני ישראל ממצרים.",sourceStatus:"סיפור מקראי מסורתי"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1300-enslavement-of-bnei-yisrael-in-egypt-3"],{story:"يصف سفر الخروج فرعونًا جديدًا يستعبد بني إسرائيل ويفرض عليهم العمل القسري. والرواية أساسية في التاريخ والهوية اليهودية، لكن المؤرخين لم يجدوا دليلًا مستقلًا يثبت الاستعباد التوراتي بالحجم أو الصورة الموصوفين.",context:"يعرض الموقع هذا بوصفه تقليدًا توراتيًا لا حدثًا مصريًا مؤرخًا بصورة مؤكدة. استخدمت مصر القديمة العمل القسري وكان فيها مستعبدون، لكن هذه الحقيقة وحدها لا تثبت بصورة مستقلة رواية الخروج.",aftermath:"في الرواية التوراتية، يؤدي الاضطهاد إلى قيادة موسى وخروج بني إسرائيل من مصر.",sourceStatus:"رواية توراتية تقليدية"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1250-the-exodus-from-egypt-4"],{story:"לפי התורה, משה מוביל את בני ישראל מעבדות במצרים אל החירות. יציאת מצרים נעשתה לאחד הסיפורים המרכזיים בזהות ובזיכרון הדתי היהודי. החוקרים ממשיכים לדון בשאלה אם הסיפור משמר זיכרונות של תנועות או אירועים היסטוריים מצומצמים יותר, אך יציאת מצרים כפי שהיא מסופרת במקרא לא הוכחה באופן עצמאי בארכאולוגיה.",context:"האירוע מפריד במכוון בין מסורת דתית ותרבותית לבין היסטוריה המאומתת באופן עצמאי. התאריך הוא מיקום משוער בתקופה המסורתית ולא תאריך מוכח.",aftermath:"הסיפור המקראי ממשיך במסע במדבר, בברית בסיני ובהתפתחות ישראל כעם המאוחד בחוק ובמסורת משותפים.",sourceStatus:"סיפור מקראי מסורתי — לא הוכח באופן עצמאי בהיקף המתואר"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1250-the-exodus-from-egypt-4"],{story:"بحسب التوراة، يقود موسى بني إسرائيل من العبودية في مصر إلى الحرية. وأصبح الخروج أحد أكثر الروايات مركزية في الهوية والذاكرة الدينية اليهودية. ويواصل الباحثون النقاش حول ما إذا كانت القصة تحفظ ذكريات لتحركات أو أحداث تاريخية أصغر، لكن الخروج التوراتي كما رُوي لم يُثبت بصورة مستقلة في علم الآثار.",context:"يفصل هذا الحدث عمدًا بين التقليد الديني والثقافي وبين التاريخ الموثق بصورة مستقلة. التاريخ المعروض تقدير ضمن الحقبة التقليدية وليس تاريخًا مثبتًا.",aftermath:"تستمر الرواية التوراتية برحلة الصحراء والعهد في سيناء وتطور إسرائيل كشعب مرتبط بشريعة وتقاليد مشتركة.",sourceStatus:"رواية توراتية تقليدية — لم تُثبت بصورة مستقلة بالحجم المروي"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1240-amalek-attacks-bnei-yisrael-5"],{story:"ספר שמות מתאר את עמלק תוקף את בני ישראל ברפידים במהלך המסע במדבר. טקסטים מקראיים מאוחרים יותר הופכים את עמלק לאויב חוזר בזיכרון הישראלי. אין עדות עצמאית בת התקופה המזהה בוודאות את הקרב המסוים הזה.",context:"מאחר שזהו סיפור על עימות מזוין שבו מעורבים בני ישראל, הוא נכלל בחלק ההיסטוריה המסורתית של הפרויקט, אך מסומן במפורש כסיפור מקראי ולא כהיסטוריה שאומתה באופן עצמאי.",aftermath:"העימות נעשה מוטיב מתמשך בזיכרון המקראי והיהודי המאוחר יותר.",sourceStatus:"סיפור מקראי מסורתי"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1240-amalek-attacks-bnei-yisrael-5"],{story:"يصف سفر الخروج هجوم عماليق على بني إسرائيل في رفيديم أثناء رحلة الصحراء. وتجعل نصوص كتابية لاحقة من عماليق عدوًا متكررًا في الذاكرة الإسرائيلية. ولا يوجد دليل مستقل معاصر يحدد هذه المعركة بعينها بصورة موثوقة.",context:"لأن هذه رواية عن صراع مسلح شارك فيه بنو إسرائيل، فهي مدرجة في قسم التاريخ التقليدي للمشروع، لكنها موسومة بوضوح كرواية توراتية لا كتاريخ موثق بصورة مستقلة.",aftermath:"أصبح الصراع موضوعًا دائمًا في الذاكرة الكتابية واليهودية اللاحقة.",sourceStatus:"رواية توراتية تقليدية"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-1230-joshua-and-warfare-in-canaan-6"],{story:"ספר יהושע מתאר מסעות מלחמה של בני ישראל נגד ערים כנעניות לאחר תקופת המדבר. הארכאולוגיה מראה שכנען עברה שינויים פוליטיים וחברתיים גדולים בסוף תקופת הברונזה המאוחרת, אך אינה תומכת בשחזור פשוט שבו כל הערים שבספר יהושע נפלו בכיבוש מאוחד אחד בדיוק כפי שמתואר.",context:"חלק מהאתרים הנזכרים בספר יהושע חוו חורבן בתקופה הכללית הרלוונטית, בעוד שבאתרים אחרים התמונה הארכאולוגית שונה. חצור, למשל, נחרבה במאה ה־13 לפנה״ס, אך זהות האחראים לכך עדיין נתונה במחלוקת.",aftermath:"המסורת המקראית מציגה את המסעות כמובילים להתיישבות שבטי ישראל; השחזור ההיסטורי מצביע במקום זאת על תהליך מורכב של צמיחת ישראל הקדומה מתוך כנען.",sourceStatus:"מסורת מקראית עם הקשר ארכאולוגי חלקי — הפרטים שנויים במחלוקת"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-1230-joshua-and-warfare-in-canaan-6"],{story:"يصف سفر يشوع حملات إسرائيلية ضد مدن كنعانية بعد فترة الصحراء. ويُظهر علم الآثار أن كنعان شهدت تغيرات سياسية واجتماعية كبيرة في نهاية العصر البرونزي المتأخر، لكنه لا يؤيد تصورًا بسيطًا سقطت فيه كل المدن المذكورة في يشوع ضمن غزو موحد واحد تمامًا كما تروي القصة.",context:"شهدت بعض المواقع المذكورة في يشوع دمارًا خلال الفترة العامة ذات الصلة، بينما تقدم مواقع أخرى تاريخًا أثريًا مختلفًا. فحاصور مثلًا دُمرت في القرن الثالث عشر قبل الميلاد، لكن هوية المسؤولين عن ذلك لا تزال موضع نقاش.",aftermath:"يعرض التقليد التوراتي الحملات باعتبارها مؤدية إلى استيطان أسباط إسرائيل؛ أما إعادة البناء التاريخية فتشير إلى نشوء معقد لإسرائيل المبكرة من داخل كنعان.",sourceStatus:"رواية تقليدية مع سياق أثري جزئي — التفاصيل موضع نقاش"});

Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-930-division-into-the-kingdoms-of-israel-and-judah-12"]||=( {} ),{"title":"חלוקה לממלכות ישראל ויהודה","location":"ישראל ויהודה","story":"לאחר שלמה מתאר הסיפור המקראי את התפצלות המלוכה לממלכת ישראל בצפון ולממלכת יהודה בדרום. עד המאה התשיעית לפנה״ס שתי הממלכות מופיעות בכתובות חיצוניות ובממצא הארכאולוגי.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; הכרונולוגיה המקראית המדויקת עדיין נתונה לדיון.","sourceStatus":"יש ראיות חזקות לקיומן של ממלכות נפרדות בתקופת הברזל; הכרונולוגיה המקראית המדויקת שנויה במחלוקת"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-930-division-into-the-kingdoms-of-israel-and-judah-12"]||=( {} ),{"title":"انقسام المملكة إلى إسرائيل ويهوذا","location":"إسرائيل ويهوذا","story":"بعد سليمان، تصف الرواية التوراتية انقسام الملكية إلى مملكة إسرائيل الشمالية ومملكة يهوذا الجنوبية. وبحلول القرن التاسع قبل الميلاد تظهر المملكتان في نقوش خارجية وفي السجل الأثري.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه في الخط الزمني على أفضل تسلسل زمني عام تدعمه الأدلة؛ ولا يزال التسلسل التوراتي الدقيق موضع نقاش.","sourceStatus":"الأدلة قوية على وجود مملكتين منفصلتين في العصر الحديدي؛ أما التسلسل الزمني التوراتي الدقيق فموضع نقاش"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-925-shoshenq-i-campaign-in-the-southern-levant-13"]||=( {} ),{"title":"מסע שישק הראשון בדרום הלבנט","location":"יהודה / ישראל / דרום הלבנט","story":"פרעה שישק הראשון יצא למסע צבאי בלבנט במאה העשירית לפנה״ס. כתובות מצריות מספקות עוגן חיצוני למלחמה שפגעה ביישובים הקשורים לישראל וליהודה הקדומות; הקשר המדויק לסיפור המקראי על שישק עדיין נתון לדיון.","context":"האירוע מבחין בין גרעין היסטורי המתועד היטב לבין פרטים סיפוריים מאוחרים יותר שבהם נדרשת זהירות.","aftermath":"ההשלכות ומספרי הנפגעים מוצגים בזהירות; מספרים מדויקים אינם ניתנים כאשר המקורות ששרדו אינם מאפשרים ביטחון.","sourceStatus":"רמת ודאות גבוהה לגבי עצם המסע; שחזור היעדים המדויקים שנוי במחלוקת"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-925-shoshenq-i-campaign-in-the-southern-levant-13"]||=( {} ),{"title":"حملة شيشنق الأول في جنوب بلاد الشام","location":"يهوذا / إسرائيل / جنوب بلاد الشام","story":"قاد الفرعون المصري شيشنق الأول حملة في بلاد الشام في القرن العاشر قبل الميلاد. وتوفر النقوش المصرية مرجعًا خارجيًا لحرب أثرت في مستوطنات مرتبطة بإسرائيل ويهوذا المبكرتين؛ أما العلاقة الدقيقة مع رواية شيشق التوراتية فما تزال موضع نقاش.","context":"يميز هذا الحدث بين جوهر الحدث الموثق جيدًا وبين التفاصيل السردية اللاحقة التي تتطلب الحذر.","aftermath":"تُعرض النتائج وأعداد الضحايا بتحفظ، وتُحذف الأرقام الدقيقة عندما لا تسمح المصادر الباقية بالثقة بها.","sourceStatus":"ثقة عالية بوقوع الحملة؛ إعادة بناء الأهداف الدقيقة موضع نقاش"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-853-battle-of-qarqar-ahab-of-israel-against-assyria-14"]||=( {} ),{"title":"קרב קרקר: אחאב מלך ישראל נגד אשור","location":"קרקר, סוריה","story":"שלמנאסר השלישי מלך אשור תיעד קרב גדול בקרקר נגד קואליציה של שליטים מן הלבנט. הכתובת שלו מזכירה את אחאב הישראלי כחבר בקואליציה ומייחסת לו כוח משמעותי של מרכבות וחיל רגלים. זוהי עדות חיצונית חשובה לממלכת ישראל הצפונית ככוח אזורי.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; המספרים הצבאיים בכתובות מלכותיות עשויים לשקף תעמולה.","sourceStatus":"כתובת מלכותית אשורית בת התקופה; המספרים הצבאיים עשויים להיות תעמולתיים"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-853-battle-of-qarqar-ahab-of-israel-against-assyria-14"]||=( {} ),{"title":"معركة قرقر: أخاب ملك إسرائيل ضد آشور","location":"قرقر، سوريا","story":"سجل الملك الآشوري شلمنصر الثالث معركة كبرى في قرقر ضد تحالف من حكام بلاد الشام. ويذكر نقشه أخاب الإسرائيلي ضمن التحالف وينسب إليه قوة كبيرة من المركبات والمشاة. وهذا دليل خارجي مهم على مكانة مملكة إسرائيل الشمالية كقوة إقليمية.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تكون الأرقام العسكرية في النقوش الملكية ذات طابع دعائي.","sourceStatus":"نقش ملكي آشوري معاصر؛ قد تكون الأرقام العسكرية دعائية"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-840-mesha-s-revolt-against-israel-15"]||=( {} ),{"title":"מרד מישע נגד ישראל","location":"מואב / ממלכת ישראל","story":"מישע מלך מואב תיעד בכתובת מלכותית את השבתם של שטחים מידי ישראל. מצבת מישע היא מקור חוץ־מקראי בן התקופה בעל חשיבות יוצאת דופן להבנת העימות בין מואב לממלכת ישראל.","context":"האירוע מבחין בין גרעין היסטורי המתועד היטב לבין פרטים מאוחרים יותר שבהם נדרשת זהירות.","aftermath":"ההשלכות ומספרי הנפגעים מוצגים בזהירות; מספרים מדויקים אינם ניתנים כאשר המקורות ששרדו אינם מאפשרים ביטחון.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי גרעין העימות"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-840-mesha-s-revolt-against-israel-15"]||=( {} ),{"title":"ثورة ميشع ضد إسرائيل","location":"موآب / مملكة إسرائيل","story":"سجل ميشع ملك موآب في نقش ملكي استعادة أراضٍ من إسرائيل. وتُعد مسلة ميشع مصدرًا معاصرًا غير توراتي بالغ الأهمية للصراع بين موآب ومملكة إسرائيل.","context":"يميز هذا الحدث بين جوهر الحدث الموثق جيدًا وبين التفاصيل اللاحقة التي تتطلب الحذر.","aftermath":"تُعرض النتائج وأعداد الضحايا بتحفظ، وتُحذف الأرقام الدقيقة عندما لا تسمح المصادر الباقية بالثقة بها.","sourceStatus":"ثقة عالية جدًا في جوهر الصراع"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-840-aramean-wars-and-the-tel-dan-stele-16"]||=( {} ),{"title":"המלחמות הארמיות ומצבת תל דן","location":"צפון ישראל / ארם־דמשק","story":"כתובת ניצחון ארמית שהתגלתה בתל דן מנציחה ניצחונות על מלכים הקשורים לישראל ול״בית דוד״. הכתובת מספקת עדות ישירה למלחמות בין ארם־דמשק לבין ממלכות ישראל ויהודה במאה התשיעית לפנה״ס.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; חלקים מן הכתובת פגומים ושחזורה דורש זהירות.","sourceStatus":"כתובת מונומנטלית בת התקופה או סמוכה לה; חלקים פגומים ולכן יש אי־ודאות בשחזור"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-840-aramean-wars-and-the-tel-dan-stele-16"]||=( {} ),{"title":"الحروب الآرامية ومسلة تل دان","location":"شمال إسرائيل / آرام دمشق","story":"يخلد نقش نصر آرامي اكتُشف في تل دان انتصارات على ملوك مرتبطين بإسرائيل و«بيت داود». ويوفر النقش دليلًا مباشرًا على الحروب بين آرام دمشق ومملكتي إسرائيل ويهوذا في القرن التاسع قبل الميلاد.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه على أفضل تسلسل زمني عام تدعمه الأدلة؛ أجزاء من النقش متضررة وتتطلب إعادة بنائها الحذر.","sourceStatus":"نقش تذكاري معاصر أو قريب من العصر؛ توجد أجزاء متضررة في إعادة البناء"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-734-tiglath-pileser-iii-invades-israel-and-the-levant-17"]||=( {} ),{"title":"תגלת־פלאסר השלישי פולש לישראל וללבנט","location":"ממלכת ישראל / הגליל / הלבנט","story":"ההתפשטות האשורית תחת תגלת־פלאסר השלישי שינתה את האזור. מסעות בשנות ה־730 לפנה״ס החלישו את ממלכת ישראל הצפונית, סיפחו שטחים והובילו להגליות, וכך הכינו את הקרקע לכיבוש האשורי הסופי של שומרון כעבור כעשור.","context":"האירוע מבחין בין הסיפור המקראי לבין העדויות הארכאולוגיות והחוץ־מקראיות במקומות שבהם המקורות שונים.","aftermath":"מיקומו בציר הזמן מבוסס על הכרונולוגיה הרחבה הנתמכת ביותר; פרטי מסעות עתיקים עשויים להישאר נתונים לדיון.","sourceStatus":"ראיות אשוריות ומקראיות חזקות"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-734-tiglath-pileser-iii-invades-israel-and-the-levant-17"]||=( {} ),{"title":"تغلث فلاسر الثالث يغزو إسرائيل وبلاد الشام","location":"مملكة إسرائيل / الجليل / بلاد الشام","story":"غير التوسع الآشوري في عهد تغلث فلاسر الثالث المنطقة. فقد أضعفت حملات ثلاثينيات القرن الثامن قبل الميلاد مملكة إسرائيل الشمالية وضمت أراضي وأدت إلى عمليات ترحيل، ممهدة للغزو الآشوري النهائي للسامرة بعد نحو عقد.","context":"يميز هذا الحدث بين الرواية التوراتية وبين الأدلة الأثرية وغير التوراتية حيث تختلف المصادر.","aftermath":"يعتمد موضعه على أفضل تسلسل زمني عام تدعمه الأدلة؛ وقد تبقى بعض تفاصيل الحملات القديمة موضع نقاش.","sourceStatus":"أدلة آشورية وتوراتية قوية"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-722-assyrian-conquest-of-samaria-18"]||=( {} ),{"title":"כיבוש שומרון בידי אשור","location":"שומרון / ממלכת ישראל","story":"אשור כבשה את שומרון והביאה לקצה את ממלכת ישראל הצפונית; לאחר מכן התרחשו הגליות ויישוב מחדש של אוכלוסיות.","context":"האירוע הוא חלק מן התיעוד הכרונולוגי של אלימות מתועדת שבה היו מעורבות קהילות ישראליות ויהודאיות. המקור המצורף מספק הקשר היסטורי רחב יותר.","aftermath":"הכיבוש סיים את ממלכת ישראל הצפונית ושינה עמוקות את האוכלוסייה והמבנה הפוליטי באזור.","sourceStatus":"רמת ודאות גבוהה"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-722-assyrian-conquest-of-samaria-18"]||=( {} ),{"title":"الغزو الآشوري للسامرة","location":"السامرة / مملكة إسرائيل","story":"غزت آشور السامرة وأنهت مملكة إسرائيل الشمالية، وتلت ذلك عمليات ترحيل وإعادة توطين للسكان.","context":"هذا الحدث جزء من السجل الزمني للعنف الموثق الذي شمل مجتمعات إسرائيلية ويهودية. ويوفر المصدر المرفق سياقًا تاريخيًا أوسع.","aftermath":"أنهى الغزو مملكة إسرائيل الشمالية وغير بصورة عميقة السكان والبنية السياسية في المنطقة.","sourceStatus":"ثقة عالية"});
