Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-587-babylonian-destruction-of-jerusalem-and-first-temple-21"]||=( {} ),{"title":"تدمير البابليين للقدس والهيكل الأول","location":"القدس / يهوذا","story":"استولت القوات البابلية على القدس ودمرت الهيكل الأول وأنهت مملكة يهوذا.","context":"هذا الحدث جزء من السجل الزمني للعنف الموثق ضد المجتمع اليهودي وانهيار المملكة تحت الإمبراطورية البابلية.","aftermath":"غير الدمار والسبي الحياة والهوية والمؤسسات اليهودية بصورة عميقة، وأصبحت بابل مركزًا مهمًا للحياة اليهودية.","sourceStatus":"ثقة عالية"});
Object.assign(window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-539-cyrus-conquers-babylon-and-permits-return-22"]||=( {} ),{"title":"כורש כובש את בבל ומתיר שיבה","location":"בבל / האימפריה הפרסית / יהודה","story":"כורש השני מלך פרס כבש את בבל בשנת 539 לפנה״ס. המדיניות הפרסית אפשרה לעמים שהוגלו, ובהם יהודאים, לשקם מקדשים וקהילות. המקרא קושר מדיניות זו לשיבה מגלות בבל ולבנייה מחדש בירושלים.","context":"האירוע ממקם את השיבה בתוך המעבר הרחב משלטון בבלי לשלטון פרסי. פרטי השיבה היהודאית נשענים בחלקם על מקורות מקראיים.","aftermath":"השיבה לא הייתה מלאה; קהילה יהודית גדולה נשארה בבבל, בעוד ירושלים ויהודה החלו תהליך של שיקום תחת שלטון פרסי.","sourceStatus":"ראיות חזקות לכיבוש הפרסי ולמדיניות שיקום; פרטי השיבה ליהודה נשענים בחלקם על מקורות מקראיים"});
Object.assign(window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-539-cyrus-conquers-babylon-and-permits-return-22"]||=( {} ),{"title":"كورش يغزو بابل ويسمح بالعودة","location":"بابل / الإمبراطورية الفارسية / يهوذا","story":"غزا كورش الثاني ملك فارس بابل سنة 539 قبل الميلاد. وسمحت السياسة الفارسية للشعوب المهجرة، ومن بينها اليهوديون، بإعادة بناء المعابد والمجتمعات. وتربط النصوص التوراتية هذه السياسة بالعودة من السبي البابلي وإعادة البناء في القدس.","context":"يضع الحدث العودة ضمن الانتقال الأوسع من الحكم البابلي إلى الحكم الفارسي. وتعتمد تفاصيل العودة اليهودية جزئيًا على المصادر التوراتية.","aftermath":"لم تكن العودة كاملة؛ بقي مجتمع يهودي كبير في بابل، بينما بدأت القدس ويهوذا عملية إعادة بناء تحت الحكم الفارسي.","sourceStatus":"أدلة قوية على الغزو الفارسي وسياسة الاستعادة؛ تفاصيل العودة إلى يهوذا تعتمد جزئيًا على المصادر التوراتية"});

window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-332-alexander-the-great-conquers-the-levant-23"]={"title":"אלכסנדר הגדול כובש את הלבנט","location":"הלבנט / יהודה","story":"כיבושיו של אלכסנדר סיימו את השליטה הפרסית בלבנט והכניסו את יהודה לעולם המדיני ההלניסטי. ירושלים עצמה אינה מתועדת בוודאות כזירת קרב גדול במסעו, אך הכיבוש שינה את הסביבה הפוליטית שבה התפתחו מאוחר יותר עימותים יהודיים.","context":"האירוע מציג שינוי אימפריאלי רחב שהשפיע על יהודה, תוך הבחנה בין הכיבוש האזורי המתועד היטב לבין מסורות מאוחרות על אלכסנדר וירושלים.","aftermath":"יהודה עברה לשלטון הלניסטי, ותהליכי הלניזציה והמאבקים בין הממלכות היורשות עיצבו את התקופה הבאה.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הכיבוש האזורי; סיפורים מאוחרים על אלכסנדר וירושלים פחות מבוססים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-200-seleucid-control-of-judea-after-the-battle-of-panium-24"]={"title":"שליטה סלאוקית ביהודה לאחר קרב פניון","location":"יהודה / קוילה־סוריה","story":"לאחר עשרות שנים של מלחמות בין בית תלמי לבית סלאוקוס, ניצחונו של אנטיוכוס השלישי העביר את יהודה לשלטון סלאוקי. בתחילה זכו המוסדות היהודיים להגנות, אך משברים פוליטיים וכלכליים מאוחרים יותר תרמו לעימות בתקופת אנטיוכוס הרביעי.","context":"המעבר לשלטון סלאוקי היה חלק ממאבק רחב בין ממלכות הלניסטיות ולא החל כרדיפה דתית של יהודים.","aftermath":"המתחים המאוחרים בתוך יהודה ובאימפריה הסלאוקית יצרו את התנאים למשבר ולמרד החשמונאים.","sourceStatus":"ראיות היסטוריות הלניסטיות חזקות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-168-antiochus-iv-captures-jerusalem-and-suppresses-jewish-practices-25"]={"title":"אנטיוכוס הרביעי כובש את ירושלים ומדכא מנהגים יהודיים","location":"ירושלים / יהודה","story":"במהלך סערה פוליטית ביהודה התערבו כוחותיו של אנטיוכוס הרביעי אפיפנס בירושלים. מקורות יהודיים עתיקים מתארים הרג, ביזת המקדש, הגבלות על מנהגים יהודיים והכנסת פולחן פגאני למקדש. צעדים אלה סייעו להצית מרד מזוין.","context":"המשבר שילב מאבקי כוח פנימיים ביהודה עם התערבות סלאוקית ומדיניות כפייה דתית; הסדר המדויק והמניעים עדיין נידונים במחקר.","aftermath":"הדיכוי והפגיעה במקדש תרמו ישירות לפרוץ מרד החשמונאים.","sourceStatus":"ראיות ספרותיות עתיקות חזקות; הרצף המדויק והמניעים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-167-maccabean-revolt-26"]={"title":"מרד החשמונאים","location":"יהודה","story":"מרד יהודי פרץ נגד השלטון הסלאוקי על רקע מדיניות הכפייה של אנטיוכוס הרביעי ועימותים פנימיים בחברה היהודאית.","context":"המרד היה גם התנגדות לשלטון ולכפייה דתית וגם חלק ממאבק פנימי על הנהגה וזהות ביהודה ההלניסטית.","aftermath":"המורדים השיגו הישגים צבאיים, השיבו את השליטה במקדש ובהמשך הניחו את היסודות לשלטון החשמונאי.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-164-maccabees-recapture-and-rededicate-the-temple-27"]={"title":"החשמונאים כובשים מחדש וחונכים את המקדש","location":"ירושלים / יהודה","story":"כוחות בהנהגת יהודה המכבי השתלטו על מתחם המקדש בירושלים וחנכו מחדש את המקדש לאחר חילולו תחת השלטון הסלאוקי. האירוע נעשה לבסיס חג החנוכה, בעוד המלחמה נגד הכוחות הסלאוקיים נמשכה.","context":"חנוכת המקדש הייתה הישג מרכזי במרד אך לא סיימה את המלחמה ולא יצרה מיד עצמאות מדינית מלאה.","aftermath":"הלחימה נמשכה, והצלחת המרד הובילה בהדרגה לעליית הנהגה חשמונאית עצמאית.","sourceStatus":"ראיות ספרותיות עתיקות חזקות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-332-alexander-the-great-conquers-the-levant-23"]={"title":"الإسكندر الأكبر يغزو بلاد الشام","location":"بلاد الشام / يهوذا","story":"أنهت فتوحات الإسكندر السيطرة الفارسية على بلاد الشام وأدخلت يهوذا في العالم السياسي الهلنستي. ولا توجد وثائق مؤكدة تجعل القدس نفسها ساحة لمعركة كبرى في حملته، لكن الفتح غير البيئة السياسية التي تطورت فيها الصراعات اليهودية اللاحقة.","context":"يعرض الحدث تحولًا إمبراطوريًا واسعًا أثر في يهوذا، مع التمييز بين الفتح الإقليمي الموثق جيدًا وبين الروايات اللاحقة عن الإسكندر والقدس.","aftermath":"انتقلت يهوذا إلى الحكم الهلنستي، وشكلت الهلننة والصراعات بين الممالك الخلف المرحلة التالية.","sourceStatus":"ثقة عالية جدًا في الفتح الإقليمي؛ الروايات اللاحقة عن الإسكندر والقدس أقل ثبوتًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-200-seleucid-control-of-judea-after-the-battle-of-panium-24"]={"title":"السيطرة السلوقية على يهوذا بعد معركة بانيوم","location":"يهوذا / جوف سوريا","story":"بعد عقود من الحروب البطلمية السلوقية، أدى انتصار أنطيوخوس الثالث إلى انتقال يهوذا إلى الحكم السلوقي. وحظيت المؤسسات اليهودية في البداية بحماية، لكن أزمات سياسية ومالية لاحقة ساهمت في المواجهة في عهد أنطيوخوس الرابع.","context":"كان الانتقال إلى الحكم السلوقي جزءًا من صراع أوسع بين الممالك الهلنستية ولم يبدأ كاضطهاد ديني لليهود.","aftermath":"هيأت التوترات اللاحقة داخل يهوذا والإمبراطورية السلوقية الظروف للأزمة ولثورة المكابيين.","sourceStatus":"أدلة تاريخية هلنستية قوية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-168-antiochus-iv-captures-jerusalem-and-suppresses-jewish-practices-25"]={"title":"أنطيوخوس الرابع يستولي على القدس ويقمع الممارسات اليهودية","location":"القدس / يهوذا","story":"خلال اضطراب سياسي في يهوذا تدخلت قوات أنطيوخوس الرابع إبيفانيس في القدس. وتصف مصادر يهودية قديمة القتل ونهب الهيكل وفرض قيود على الممارسات اليهودية وإقامة عبادة وثنية في الحرم. وساعدت هذه الإجراءات على إشعال تمرد مسلح.","context":"جمعت الأزمة بين صراعات سلطة داخلية في يهوذا والتدخل السلوقي وسياسات الإكراه الديني؛ ولا يزال التسلسل الدقيق والدوافع موضع بحث.","aftermath":"ساهم القمع وانتهاك الهيكل مباشرة في اندلاع ثورة المكابيين.","sourceStatus":"أدلة أدبية قديمة قوية؛ التسلسل الدقيق والدوافع موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-167-maccabean-revolt-26"]={"title":"ثورة المكابيين","location":"يهوذا","story":"اندلعت ثورة يهودية ضد الحكم السلوقي في ظل سياسات أنطيوخوس الرابع القسرية والصراع داخل المجتمع اليهودي.","context":"كانت الثورة مقاومة للحكم والإكراه الديني وفي الوقت نفسه جزءًا من صراع داخلي على القيادة والهوية في يهوذا الهلنستية.","aftermath":"حقق المتمردون نجاحات عسكرية واستعادوا السيطرة على الهيكل ومهدوا لاحقًا لقيام الحكم الحشموني.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-164-maccabees-recapture-and-rededicate-the-temple-27"]={"title":"المكابيون يستعيدون الهيكل ويعيدون تدشينه","location":"القدس / يهوذا","story":"سيطرت قوات بقيادة يهوذا المكابي على حرم الهيكل في القدس وأعادت تدشينه بعد تدنيسه في ظل الحكم السلوقي. وأصبح الحدث أساس عيد حانوكا، بينما استمرت الحرب ضد القوات السلوقية.","context":"كان تدشين الهيكل إنجازًا رئيسيًا للثورة لكنه لم ينه الحرب ولم يحقق فورًا استقلالًا سياسيًا كاملًا.","aftermath":"استمر القتال وأدى نجاح الثورة تدريجيًا إلى صعود قيادة حشمونية مستقلة.","sourceStatus":"أدلة أدبية قديمة قوية"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-142-hasmonean-independence-emerges-28"]={"title":"עצמאות חשמונאית מתגבשת","location":"יהודה","story":"תחת שמעון השיגה ההנהגה החשמונאית עצמאות מדינית אפקטיבית מן השליטה הסלאוקית. השושלת שצמחה מן המרד הרחיבה מאוחר יותר את שליטתה מעבר ליהודה באמצעות מלחמות וכיבושים.","context":"החשמונאים עברו מתנועת מרד לשושלת שלטונית, ולכן התקופה כוללת גם עצמאות יהודית וגם התפשטות צבאית כלפי שכנים.","aftermath":"המדינה החשמונאית נעשתה כוח אזורי והמשיכה להתרחב בדורות הבאים.","sourceStatus":"ראיות ספרותיות והיסטוריות עתיקות חזקות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-125-hasmonean-conquest-of-idumea-29"]={"title":"הכיבוש החשמונאי של אדום","location":"אדום / דרום יהודה","story":"יוחנן הורקנוס הרחיב את המדינה החשמונאית לאדום. מקורות עתיקים מספרים שהאדומים שולבו במדינה היהודאית ונדרשו לאמץ מנהגים יהודיים, ובהם ברית מילה. חוקרים מודרניים דנים במידת הכפייה ובאופן שבו נכון לתאר את התהליך.","context":"האירוע חשוב משום שהמדינה החשמונאית, שקמה מתוך מרד נגד כפייה סלאוקית, הפעילה בעצמה כוח כלפי אוכלוסיות שכנות.","aftermath":"אדום שולבה במדינה החשמונאית, ושילוב זה השפיע מאוחר יותר גם על עליית בית הורדוס.","sourceStatus":"עדויות ספרותיות עתיקות; אופיו ומידת הכפייה בתהליך הגיור שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-103-hasmonean-expansion-under-alexander-jannaeus-30"]={"title":"ההתפשטות החשמונאית תחת אלכסנדר ינאי","location":"יהודה והשטחים הסמוכים","story":"אלכסנדר ינאי הרחיב את השטח החשמונאי באמצעות מלחמות חוזרות נגד ערים ועמים שכנים. תקופתו כללה גם עימות פנימי חריף בין המלוכה לבין מתנגדים המזוהים במקורות מאוחרים עם הפרושים.","context":"האירוע מציג הן את ההתפשטות הצבאית של המדינה היהודית והן את האלימות הפנים־יהודית בתקופת החשמונאים.","aftermath":"הממלכה התרחבה, אך העימותים הפנימיים החלישו את היציבות הפוליטית והעמיקו מחלוקות.","sourceStatus":"עדויות ספרותיות עתיקות; מספרי הנפגעים ותיאורי הפלגים דורשים זהירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-88-hasmonean-civil-conflict-and-repression-31"]={"title":"עימות פנימי ודיכוי בתקופה החשמונאית","location":"יהודה","story":"מקורות עתיקים מתארים עימות פנימי מר בתקופת אלכסנדר ינאי, כולל מרד נגד המלך ופעולות תגמול אכזריות. יוסף בן מתתיהו מדווח על הוצאות להורג המוניות, אך יש להתייחס בזהירות למספרים ולפרטים הדרמטיים שלו.","context":"זהו פרק של אלימות פנים־יהודית ולא רדיפה שבוצעה בידי כוח חיצוני.","aftermath":"העימות העמיק את הקרעים הפוליטיים והדתיים בתוך יהודה והותיר מורשת של חוסר יציבות.","sourceStatus":"עדויות ספרותיות עתיקות, בעיקר יוסף בן מתתיהו; המספרים המדויקים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-67-hasmonean-civil-war-hyrcanus-ii-and-aristobulus-ii-32"]={"title":"מלחמת האזרחים החשמונאית: הורקנוס השני ואריסטובולוס השני","location":"יהודה / ירושלים","story":"סכסוך ירושה בין הורקנוס השני לאריסטובולוס השני הידרדר למלחמת אזרחים. שני הצדדים ביקשו תמיכה חיצונית, ובכך יצרו את התנאים להתערבותו של המצביא הרומי פומפיוס ביהודה.","context":"המאבק הפנים־חשמונאי החליש את העצמאות המדינית והזמין מעורבות רומית ישירה.","aftermath":"התערבות רומא הובילה למצור על ירושלים ולהכנסת יהודה לתחום ההשפעה הרומי.","sourceStatus":"ראיות ספרותיות עתיקות חזקות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-63-pompey-s-siege-and-capture-of-jerusalem-33"]={"title":"המצור של פומפיוס וכיבוש ירושלים","location":"ירושלים","story":"המצביא הרומי פומפיוס התערב במלחמת האזרחים החשמונאית, הטיל מצור על ירושלים והכניס את יהודה לתחום ההשפעה של רומא.","context":"הכיבוש נבע במידה רבה ממאבק הירושה החשמונאי ומבקשות ההתערבות של הצדדים היריבים.","aftermath":"עצמאותה של יהודה הצטמצמה באופן משמעותי, ורומא נעשתה הכוח החיצוני המרכזי בפוליטיקה המקומית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-bce-37-herod-and-roman-forces-capture-jerusalem-34"]={"title":"הורדוס והכוחות הרומיים כובשים את ירושלים","location":"ירושלים","story":"הורדוס, בגיבוי כוחות רומיים, הטיל מצור על ירושלים וכבש אותה מידי אנטיגונוס השני מתתיהו, המלך החשמונאי האחרון. הכיבוש סיים את המלוכה החשמונאית העצמאית וביסס את הורדוס כמלך חסות של רומא ביהודה.","context":"האירוע היה חלק ממאבק שושלתי ופוליטי שבו כוחות יהודיים ורומיים לחמו משני הצדדים.","aftermath":"שלטון בית הורדוס החל תחת חסות רומית, והעצמאות החשמונאית הגיעה לקצה.","sourceStatus":"ראיות ספרותיות עתיקות והיסטוריות מן התקופה הרומית חזקות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-142-hasmonean-independence-emerges-28"]={"title":"بروز الاستقلال الحشموني","location":"يهوذا","story":"في عهد سمعان حققت القيادة الحشمونية استقلالًا سياسيًا فعليًا عن السيطرة السلوقية. ثم وسعت السلالة التي خرجت من الثورة حكمها خارج يهوذا بالحروب والفتوحات.","context":"انتقل الحشمونيون من حركة تمرد إلى سلالة حاكمة، ولذلك تشمل المرحلة الاستقلال اليهودي وكذلك التوسع العسكري تجاه الجيران.","aftermath":"أصبحت الدولة الحشمونية قوة إقليمية وواصلت التوسع في الأجيال التالية.","sourceStatus":"أدلة أدبية وتاريخية قديمة قوية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-125-hasmonean-conquest-of-idumea-29"]={"title":"الفتح الحشموني لأدوم","location":"أدوم / جنوب يهوذا","story":"وسع يوحنا هيركانوس الدولة الحشمونية إلى أدوم. وتذكر مصادر قديمة أن الأدوميين أُدمجوا في الكيان اليهودي وطُلب منهم تبني ممارسات يهودية منها الختان. ويناقش المؤرخون المعاصرون درجة الإكراه وأفضل توصيف للعملية.","context":"الحدث مهم لأن الدولة الحشمونية التي نشأت من ثورة ضد الإكراه السلوقي استخدمت بدورها القوة تجاه جماعات مجاورة.","aftermath":"دُمجت أدوم في الدولة الحشمونية، وكان لهذا الاندماج أثر لاحق في صعود الأسرة الهيرودية.","sourceStatus":"أدلة أدبية قديمة؛ طبيعة ودرجة الإكراه في التحول الديني موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-103-hasmonean-expansion-under-alexander-jannaeus-30"]={"title":"التوسع الحشموني في عهد ألكسندر ينايوس","location":"يهوذا والأراضي المجاورة","story":"وسع ألكسندر ينايوس الأراضي الحشمونية عبر حروب متكررة ضد مدن وشعوب مجاورة. وشهد عهده أيضًا صراعًا يهوديًا داخليًا شديدًا بين الملكية ومعارضين تربطهم مصادر لاحقة بالفريسيين.","context":"يعرض الحدث التوسع العسكري للدولة اليهودية وكذلك العنف الداخلي اليهودي في العصر الحشموني.","aftermath":"توسعت المملكة، لكن الصراعات الداخلية أضعفت الاستقرار السياسي وعمقت الانقسامات.","sourceStatus":"أدلة أدبية قديمة؛ أعداد الضحايا ووصف الفصائل يتطلبان الحذر"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-88-hasmonean-civil-conflict-and-repression-31"]={"title":"الصراع الأهلي والقمع الحشموني","location":"يهوذا","story":"تصف روايات قديمة صراعًا داخليًا مريرًا في عهد ألكسندر ينايوس، شمل تمردًا ضد الملك وأعمال انتقام قاسية. ويذكر يوسيفوس إعدامات جماعية، لكن أرقامه وتفاصيله الدرامية يجب التعامل معها بحذر.","context":"هذه مرحلة من العنف اليهودي الداخلي وليست اضطهادًا نفذته قوة خارجية.","aftermath":"عمق الصراع الانقسامات السياسية والدينية داخل يهوذا وترك إرثًا من عدم الاستقرار.","sourceStatus":"أدلة أدبية قديمة، أساسًا يوسيفوس؛ الأرقام الدقيقة غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-67-hasmonean-civil-war-hyrcanus-ii-and-aristobulus-ii-32"]={"title":"الحرب الأهلية الحشمونية: هيركانوس الثاني وأرسطوبولوس الثاني","location":"يهوذا / القدس","story":"تحول نزاع على الخلافة بين هيركانوس الثاني وأرسطوبولوس الثاني إلى حرب أهلية. وسعى الطرفان إلى دعم خارجي، مما هيأ الظروف لتدخل القائد الروماني بومبي في يهوذا.","context":"أضعف الصراع الحشموني الداخلي الاستقلال السياسي ودعا إلى تدخل روماني مباشر.","aftermath":"أدى التدخل الروماني إلى حصار القدس ودخول يهوذا في دائرة النفوذ الروماني.","sourceStatus":"أدلة أدبية قديمة قوية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-63-pompey-s-siege-and-capture-of-jerusalem-33"]={"title":"حصار بومبي للقدس والاستيلاء عليها","location":"القدس","story":"تدخل القائد الروماني بومبي في الحرب الأهلية الحشمونية وحاصر القدس وأدخل يهوذا في دائرة النفوذ الروماني.","context":"نشأ الفتح بدرجة كبيرة من صراع الخلافة الحشموني وطلب الأطراف المتنافسة التدخل الخارجي.","aftermath":"تقلص استقلال يهوذا بصورة كبيرة وأصبحت روما القوة الخارجية الرئيسية في السياسة المحلية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-bce-37-herod-and-roman-forces-capture-jerusalem-34"]={"title":"هيرودس والقوات الرومانية يستولون على القدس","location":"القدس","story":"حاصر هيرودس، بدعم قوات رومانية، القدس واستولى عليها من أنتيغونوس الثاني متاثياس، آخر الملوك الحشمونيين. وأنهى الفتح الملكية الحشمونية المستقلة ورسخ هيرودس ملكًا تابعًا لروما في يهوذا.","context":"كان الحدث جزءًا من صراع أسري وسياسي قاتلت فيه قوات يهودية ورومانية على جانبي النزاع.","aftermath":"بدأ حكم الأسرة الهيرودية تحت الرعاية الرومانية وانتهى الاستقلال الحشموني.","sourceStatus":"أدلة أدبية قديمة وتاريخية قوية من العصر الروماني"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-6-judea-becomes-a-roman-province-and-census-resistance-35"]={"title":"יהודה נעשית פרובינקיה רומית והתנגדות למפקד","location":"יהודה","story":"רומא הדיחה את הורדוס ארכלאוס והעבירה את יהודה למינהל רומי ישיר. המפקד המזוהה עם קוויריניוס עורר התנגדות המתועדת במקורות עתיקים וסייע לעצב תנועות אנטי־רומיות מאוחרות יותר.","context":"האירוע מוצג תוך תשומת לב למגבלות ולהטיות של המקורות העתיקים ששרדו, במיוחד כאשר מקורות ספרותיים מאוחרים מספקים מניעים או מספרי נפגעים.","aftermath":"המעבר לשלטון רומי ישיר צמצם את האוטונומיה הפוליטית והעמיק מתחים שימשיכו לאורך המאה הראשונה.","sourceStatus":"עדויות ספרותיות עתיקות; ההקשר הפוליטי מבוסס היטב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-38-alexandria-anti-jewish-violence-36"]={"title":"אלימות אנטי־יהודית באלכסנדריה","location":"אלכסנדריה, מצרים הרומית","story":"אלימות קהילתית קשה פרצה באלכסנדריה בין תושבים יוונים ליהודים על רקע סכסוך פוליטי בתקופת הנציב הרומי אאולוס אביליוס פלאקוס. פילון מתאר יהודים שנדחקו לרובע מוגבל, בתים וחנויות שנבזזו ואנשים שהותקפו ונהרגו.","context":"מצרים הרומית כללה מתחים פוליטיים, אזרחיים וקהילתיים. האירוע מזהה את המשתתפים ואינו מציג את האלימות כעימות אתני רציף ופשוט.","aftermath":"האירוע העמיק את חוסר הביטחון של הקהילה היהודית באלכסנדריה והוביל למאבקים ופניות נוספות לשלטון הרומי.","sourceStatus":"עדות ספרותית חזקה בת התקופה מפילון; מספר הנפגעים המדויק אינו ידוע"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-46-roman-crucifixion-of-jacob-and-simon-sons-of-judas-the-galilean-37"]={"title":"צליבת יעקב ושמעון, בני יהודה הגלילי, בידי רומא","location":"יהודה","story":"יוסף בן מתתיהו מספר שהנציב הרומי טיבריוס יוליוס אלכסנדר הורה לצלוב את יעקב ושמעון, בני יהודה הגלילי, שתנועתו התנגדה למיסוי הרומי. האירוע ממחיש את המשך ההתנגדות ואת הדיכוי הרומי לפני המרד הגדול של שנת 66.","context":"יהודה הרומית כללה דיכוי אימפריאלי, התנגדות יהודית ועימותים פנימיים. המקור המרכזי כאן הוא יוסף בן מתתיהו.","aftermath":"המתחים בין תנועות התנגדות יהודיות לשלטון הרומי נמשכו והחריפו בעשורים הבאים.","sourceStatus":"עדות ספרותית עתיקה, בעיקר יוסף בן מתתיהו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-50-jewish-samaritan-violence-under-roman-rule-38"]={"title":"אלימות יהודית–שומרונית תחת שלטון רומא","location":"יהודה / שומרון","story":"לאחר שעולי רגל מן הגליל נהרגו בדרכם דרך שומרון, קבוצות יהודיות ביצעו פעולות תגמול נגד כפרים שומרוניים. לאחר מכן התערבה רומא. האירוע מראה שהאלימות בארץ תחת רומא לא הייתה רק עימות בין יהודים לרומאים אלא כללה גם עימותים בין־קהילתיים חמורים.","context":"האירוע מוצג כעימות בין קהילות מסוימות תחת שלטון רומי, ולא כמלחמה רציפה בין עמים שלמים.","aftermath":"ההתערבות הרומית לא פתרה את המתחים, והיחסים בין הקהילות נותרו מורכבים.","sourceStatus":"עדויות ספרותיות עתיקות; הפרטים נשענים בעיקר על יוסף בן מתתיהו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-64-gessius-florus-and-escalating-violence-in-judea-39"]={"title":"גסיוס פלורוס והחרפת האלימות ביהודה","location":"ירושלים / יהודה","story":"הנציב הרומי גסיוס פלורוס נודע במקורות יהודיים בשל מיסוי כבד ואלימות. נטילת כספים מאוצר המקדש ודיכוי אכזרי של מחאות בירושלים סייעו להפוך מתחים ממושכים למרד גלוי.","context":"המקורות העתיקים עוינים במיוחד את פלורוס, ולכן יש להבחין בין עצם המשבר המתועד לבין פרטים ומניעים שעברו דרך נקודת מבט פוליטית.","aftermath":"העימותים בירושלים היו בין הגורמים המיידיים לפרוץ המרד היהודי הגדול נגד רומא בשנת 66.","sourceStatus":"עדויות ספרותיות עתיקות חזקות; המניעים והפרטים מסוננים דרך מקורות עוינים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-66-first-jewish-roman-war-40"]={"title":"המרד הגדול — המלחמה היהודית–רומית הראשונה","location":"יהודה הרומית","story":"מרד יהודי גדול נגד השלטון הרומי החל בשנת 66 לספירה ודוכא במהלך כמה שנות מלחמה.","context":"המלחמה נבעה משילוב של מתחים פוליטיים, כלכליים, דתיים וחברתיים, וכללה גם מאבקים פנימיים בין פלגים יהודיים.","aftermath":"המלחמה הובילה לכיבוש ירושלים ולחורבן בית המקדש השני בשנת 70; מוקדי התנגדות מסוימים המשיכו לאחר מכן.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-66-defeat-of-cestius-gallus-at-beth-horon-41"]={"title":"תבוסת קסטיוס גאלוס בבית חורון","location":"יהודה","story":"בתחילת המרד התקדם מושל סוריה קסטיוס גאלוס לעבר ירושלים ולאחר מכן נסוג. כוחות יהודאיים תקפו את הצבא הנסוג ליד בית חורון והנחילו לרומאים תבוסה קשה, שחיזקה מאוד את המרד והבטיחה תגובה אימפריאלית רחבה.","context":"האירוע מתועד בעיקר במקורות ספרותיים עתיקים, ויש להיזהר במספרי נפגעים מדויקים.","aftermath":"הניצחון חיזק את ביטחון המורדים אך גם הביא את רומא לשלוח כוח גדול יותר תחת אספסיאנוס.","sourceStatus":"עדויות ספרותיות עתיקות חזקות; מספרי הנפגעים המדויקים אינם ודאיים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-6-judea-becomes-a-roman-province-and-census-resistance-35"]={"title":"تحول يهوذا إلى ولاية رومانية ومقاومة الإحصاء","location":"يهوذا","story":"عزلت روما هيرودس أرخيلاوس وأخضعت يهوذا للإدارة الرومانية المباشرة. وأثار الإحصاء المرتبط بكيرينيوس مقاومة تذكرها المصادر القديمة وساهم في تشكيل حركات لاحقة مناهضة لروما.","context":"يُعرض الحدث مع الانتباه إلى حدود وانحيازات المصادر القديمة الباقية، خاصة عندما تقدم الروايات الأدبية اللاحقة دوافع أو أعداد ضحايا.","aftermath":"قلص الانتقال إلى الحكم الروماني المباشر الاستقلال السياسي وعمق التوترات التي استمرت خلال القرن الأول.","sourceStatus":"أدلة أدبية قديمة؛ السياق السياسي ثابت جيدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-38-alexandria-anti-jewish-violence-36"]={"title":"عنف معادٍ لليهود في الإسكندرية","location":"الإسكندرية، مصر الرومانية","story":"اندلع عنف طائفي شديد في الإسكندرية بين السكان اليونانيين واليهود وسط نزاع سياسي في عهد الوالي الروماني أولوس أفيليوس فلاكوس. ويصف فيلون إجبار اليهود على منطقة محدودة ونهب المنازل والمتاجر والاعتداء على أشخاص وقتلهم.","context":"شهدت مصر الرومانية توترات سياسية ومدنية وطائفية. ويحدد الحدث المشاركين بدل تصوير العنف كصراع عرقي واحد متواصل.","aftermath":"عمق الحدث انعدام الأمن لدى المجتمع اليهودي في الإسكندرية وأدى إلى نزاعات واحتجاجات إضافية أمام السلطة الرومانية.","sourceStatus":"أدلة أدبية معاصرة قوية من فيلون؛ العدد الدقيق للضحايا غير معروف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-46-roman-crucifixion-of-jacob-and-simon-sons-of-judas-the-galilean-37"]={"title":"صلب يعقوب وسمعان ابني يهوذا الجليلي على يد الرومان","location":"يهوذا","story":"يسجل يوسيفوس أن الوالي الروماني تيبيريوس يوليوس ألكسندر أمر بصلب يعقوب وسمعان، ابني يهوذا الجليلي الذي قاومت حركته الضرائب الرومانية. ويوضح الحدث استمرار المقاومة والقمع الروماني قبل الثورة الكبرى سنة 66.","context":"ضمت يهوذا الرومانية قمعًا إمبراطوريًا ومقاومة يهودية وصراعات داخلية. والمصدر الرئيسي هنا هو يوسيفوس.","aftermath":"استمرت التوترات بين حركات المقاومة اليهودية والحكم الروماني واشتدت في العقود التالية.","sourceStatus":"أدلة أدبية قديمة، أساسًا يوسيفوس"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-50-jewish-samaritan-violence-under-roman-rule-38"]={"title":"عنف يهودي–سامري تحت الحكم الروماني","location":"يهوذا / السامرة","story":"بعد مقتل حجاج من الجليل أثناء مرورهم عبر السامرة، ردت جماعات يهودية بهجمات على قرى سامرية. ثم تدخلت روما. ويبين الحدث أن العنف في فلسطين الرومانية لم يكن مجرد صراع بين اليهود وروما، بل شمل أيضًا صراعات طائفية خطيرة.","context":"يُعرض الحدث كصراع بين مجتمعات محددة تحت الحكم الروماني، لا كحرب متواصلة بين شعوب كاملة.","aftermath":"لم ينه التدخل الروماني التوترات، وظلت العلاقات بين المجتمعات معقدة.","sourceStatus":"أدلة أدبية قديمة؛ التفاصيل تعتمد أساسًا على يوسيفوس"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-64-gessius-florus-and-escalating-violence-in-judea-39"]={"title":"غيسيوس فلوروس وتصاعد العنف في يهوذا","location":"القدس / يهوذا","story":"اشتهر الوالي الروماني غيسيوس فلوروس في المصادر اليهودية بالضرائب القاسية والعنف. وساهم استيلاؤه على أموال من خزانة الهيكل وقمعه الوحشي للاحتجاجات في القدس في تحويل التوترات الطويلة إلى تمرد مفتوح.","context":"المصادر القديمة معادية بشدة لفلوروس، ولذلك ينبغي التمييز بين الأزمة الموثقة وبين التفاصيل والدوافع التي نقلتها وجهات نظر سياسية.","aftermath":"كانت المواجهات في القدس من الأسباب المباشرة لاندلاع الثورة اليهودية الكبرى ضد روما سنة 66.","sourceStatus":"أدلة أدبية قديمة قوية؛ الدوافع والتفاصيل منقولة عبر مصادر معادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-66-first-jewish-roman-war-40"]={"title":"الثورة الكبرى — الحرب اليهودية الرومانية الأولى","location":"يهوذا الرومانية","story":"بدأ تمرد يهودي كبير ضد الحكم الروماني سنة 66م وقُمِع خلال عدة سنوات من الحرب.","context":"نشأت الحرب من مزيج من التوترات السياسية والاقتصادية والدينية والاجتماعية، وشملت أيضًا صراعات داخلية بين فصائل يهودية.","aftermath":"أدت الحرب إلى الاستيلاء على القدس وتدمير الهيكل الثاني سنة 70، بينما استمرت بعض بؤر المقاومة بعد ذلك.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-66-defeat-of-cestius-gallus-at-beth-horon-41"]={"title":"هزيمة سيستيوس غالوس عند بيت حورون","location":"يهوذا","story":"في بداية الثورة تقدم حاكم سوريا سيستيوس غالوس نحو القدس ثم انسحب. وهاجمت قوات يهودية الجيش المنسحب قرب بيت حورون وألحقت بالرومان هزيمة خطيرة عززت التمرد وضمنت ردًا إمبراطوريًا واسعًا.","context":"يوثق الحدث أساسًا في مصادر أدبية قديمة، وينبغي الحذر من أعداد الضحايا الدقيقة.","aftermath":"عزز النصر ثقة المتمردين لكنه دفع روما أيضًا إلى إرسال قوة أكبر بقيادة فسباسيان.","sourceStatus":"أدلة أدبية قديمة قوية؛ أعداد الضحايا الدقيقة غير مؤكدة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-67-roman-campaign-in-galilee-42"]={"title":"המסע הרומי בגליל","location":"הגליל","story":"כוחות רומיים בפיקוד אספסיאנוס וטיטוס כבשו מחדש באופן שיטתי את הגליל במהלך המרד הגדול. מרכזים חשובים ובהם יודפת נפלו לאחר מצורים; יוסף בן מתתיהו מתאר הרג נרחב, שעבוד ועקירה.","context":"העדויות הספרותיות והארכאולוגיות חזקות, אך מספרי הנפגעים אצל יוסף בן מתתיהו עשויים להיות מוגזמים.","aftermath":"נפילת הגליל אפשרה לרומאים לרכז את המערכה בהמשך ביהודה ובירושלים.","sourceStatus":"עדויות ספרותיות וארכאולוגיות עתיקות חזקות; מספרי הנפגעים אצל יוסף בן מתתיהו עשויים להיות מנופחים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-68-jewish-factional-fighting-inside-jerusalem-43"]={"title":"לחימה בין פלגים יהודיים בתוך ירושלים","location":"ירושלים","story":"עם גבור הלחץ הרומי נלחמו פלגים יהודיים יריבים באלימות על השליטה בירושלים. מקורות עתיקים מתארים הרג והרס בתוך העיר לפני המצור הרומי ובמהלכו. העימות הפנימי החליש את ההגנה ומראה שהמלחמה הייתה גם מאבק אזרחי יהודי, ולא רק רומאים נגד יהודים.","context":"המקור המרכזי הוא יוסף בן מתתיהו, שהיה משתתף במלחמה ובהמשך עבר לצד הרומי; נקודת מבטו הפוליטית מחייבת קריאה ביקורתית.","aftermath":"המאבק הפנימי פגע ביכולת ההתנגדות של העיר בזמן שהצבא הרומי התקרב.","sourceStatus":"עדויות ספרותיות עתיקות חזקות, במיוחד יוסף בן מתתיהו; הפרשנות מושפעת מנקודת מבטו הפוליטית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-70-destruction-of-jerusalem-and-second-temple-44"]={"title":"חורבן ירושלים ובית המקדש השני","location":"ירושלים","story":"כוחות רומיים בפיקוד טיטוס כבשו את ירושלים והחריבו את בית המקדש השני. מספרי הנפגעים העתיקים שנויים במחלוקת.","context":"החורבן התרחש לאחר כמה שנות מרד ומצור והיה נקודת מפנה מרכזית בהיסטוריה היהודית תחת רומא.","aftermath":"חורבן המקדש שינה באופן עמוק את החיים הדתיים והפוליטיים היהודיים; מוסדות ומרכזים חדשים התפתחו לאחר המלחמה, בעוד יהודים המשיכו לחיות בארץ ובתפוצות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-73-siege-and-fall-of-masada-45"]={"title":"המצור ונפילת מצדה","location":"מצדה, מדבר יהודה","story":"כוחות רומיים הטילו מצור על מבצר מצדה, שבו החזיקו מורדים יהודים לאחר נפילת ירושלים. יוסף בן מתתיהו מספר שהמגינים בחרו במוות המוני במקום בשבי. הארכאולוגיה מאשרת את מערך המצור הרומי ואת החורבן, אך חוקרים דנים בפרטים של סיפור המוות הסופי.","context":"המצור הרומי מתועד היטב מבחינה ארכאולוגית; תיאור ההחלטה והמוות ההמוני תלוי בעיקר ביוסף בן מתתיהו.","aftermath":"נפילת מצדה סימנה את סופו של אחד ממוקדי ההתנגדות האחרונים שנותרו לאחר המרד הגדול.","sourceStatus":"ראיות ארכאולוגיות חזקות מאוד למצור; סיפור המוות הסופי תלוי ביוסף בן מתתיהו"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-115-kitos-war-diaspora-revolt-46"]={"title":"מלחמת קיטוס / מרד התפוצות","location":"מזרח האימפריה הרומית","story":"מרידות יהודיות פרצו בכמה פרובינקיות מזרחיות של האימפריה הרומית בתקופת טראיאנוס ודוכאו באלימות.","context":"המרידות התרחשו בהקשר של מלחמות טראיאנוס במזרח וכללו גם אלימות בין־קהילתית קשה. המספרים העתיקים לגבי נפגעים אינם מהימנים.","aftermath":"הדיכוי גרם נזק כבד לכמה קהילות יהודיות בתפוצות ושינה את מצבן באזורים מסוימים של מזרח האימפריה.","sourceStatus":"האירועים מתועדים היטב; מספרי הנפגעים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-116-trajanic-revolt-spreads-through-jewish-diaspora-47"]={"title":"המרד בימי טראיאנוס מתפשט בתפוצות היהודיות","location":"מצרים, קירנאיקה, קפריסין ומסופוטמיה","story":"במהלך מלחמות טראיאנוס במזרח פרצו מרידות יהודיות גדולות ואלימות בין־קהילתית בכמה אזורים בעולם הרומי. מורדים יהודים, כוחות רומיים ואוכלוסיות מקומיות ספגו אבדות כבדות. מספרי הנפגעים העצומים במקורות העתיקים נחשבים בדרך כלל לבלתי אמינים.","context":"האירוע מוצג תוך תשומת לב למגבלות ולהטיות של המקורות העתיקים, במיוחד לגבי מספרי נפגעים ומניעים.","aftermath":"המרידות התפשטו על פני כמה פרובינקיות והביאו לתגובה צבאית רומית חריפה.","sourceStatus":"מקורות עתיקים מרובים; היקף האירועים ברור אך מספרי הנפגעים אינם מהימנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-117-roman-suppression-of-the-diaspora-revolt-48"]={"title":"הדיכוי הרומי של מרד התפוצות","location":"קירנאיקה / מצרים / קפריסין / מסופוטמיה","story":"מלחמת קיטוס, או מרד התפוצות, התפשטה בכמה פרובינקיות מזרחיות של רומא. מקורות עתיקים מתארים הרג נרחב שבוצע בידי מורדים יהודים ובידי יריביהם. הכוחות הרומיים דיכאו לבסוף את המרידות, עם השלכות קשות על כמה קהילות יהודיות.","context":"האירוע מזהה אלימות מצד כמה צדדים ואינו מקבל את מספרי הנפגעים הדרמטיים של המקורות העתיקים כפשוטם.","aftermath":"קהילות יהודיות מסוימות, במיוחד באזורים שנפגעו קשות, הצטמצמו או איבדו ממעמדן לאחר הדיכוי.","sourceStatus":"המרד מתועד היטב; מספרי הנפגעים העתיקים בלתי מהימנים במידה רבה"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-67-roman-campaign-in-galilee-42"]={"title":"الحملة الرومانية في الجليل","location":"الجليل","story":"استعادت القوات الرومانية بقيادة فسباسيان وتيطس الجليل بصورة منهجية خلال الثورة اليهودية الأولى. وسقطت مراكز مهمة منها يودفات بعد حصارات، ويصف يوسيفوس قتلًا واسعًا واستعبادًا وتهجيرًا.","context":"الأدلة الأدبية والأثرية قوية، لكن أعداد الضحايا لدى يوسيفوس قد تكون مبالغًا فيها.","aftermath":"سمح سقوط الجليل للرومان بتركيز الحملة لاحقًا على يهوذا والقدس.","sourceStatus":"أدلة أدبية وأثرية قديمة قوية؛ قد تكون أعداد الضحايا لدى يوسيفوس مبالغًا فيها"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-68-jewish-factional-fighting-inside-jerusalem-43"]={"title":"اقتتال الفصائل اليهودية داخل القدس","location":"القدس","story":"مع ازدياد الضغط الروماني، قاتلت فصائل يهودية متنافسة بعنف للسيطرة على القدس. وتصف مصادر قديمة عمليات قتل ودمار داخل المدينة قبل الحصار الروماني وأثناءه. وأضعف الصراع الداخلي الدفاع ويبين أن الحرب كانت أيضًا صراعًا أهليًا يهوديًا لا مجرد رومان ضد يهود.","context":"المصدر الرئيسي هو يوسيفوس، الذي شارك في الحرب ثم انتقل إلى الجانب الروماني؛ ولذلك تتطلب وجهة نظره السياسية قراءة نقدية.","aftermath":"أضر الصراع الداخلي بقدرة المدينة على المقاومة بينما كان الجيش الروماني يقترب.","sourceStatus":"أدلة أدبية قديمة قوية، خاصة يوسيفوس؛ التفسير متأثر بمنظوره السياسي"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-70-destruction-of-jerusalem-and-second-temple-44"]={"title":"تدمير القدس والهيكل الثاني","location":"القدس","story":"استولت القوات الرومانية بقيادة تيطس على القدس ودمرت الهيكل الثاني. وأعداد الضحايا الواردة في المصادر القديمة موضع خلاف.","context":"جاء الدمار بعد عدة سنوات من الثورة والحصار وشكل نقطة تحول كبرى في التاريخ اليهودي تحت الحكم الروماني.","aftermath":"غير تدمير الهيكل الحياة الدينية والسياسية اليهودية بصورة عميقة؛ ونشأت مؤسسات ومراكز جديدة بعد الحرب، بينما استمر اليهود في العيش في البلاد والشتات.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-73-siege-and-fall-of-masada-45"]={"title":"حصار وسقوط مسادا","location":"مسادا، صحراء يهوذا","story":"حاصرت القوات الرومانية قلعة مسادا التي احتفظ بها متمردون يهود بعد سقوط القدس. ويروي يوسيفوس أن المدافعين اختاروا الموت الجماعي بدل الأسر. وتؤكد الآثار أعمال الحصار الروماني والدمار، بينما يناقش المؤرخون تفاصيل رواية الوفيات الأخيرة.","context":"الحصار الروماني موثق أثريًا بقوة؛ أما وصف القرار والموت الجماعي فيعتمد أساسًا على يوسيفوس.","aftermath":"شكل سقوط مسادا نهاية أحد آخر مراكز المقاومة المتبقية بعد الثورة الكبرى.","sourceStatus":"أدلة أثرية قوية جدًا على الحصار؛ رواية الموت النهائي تعتمد على يوسيفوس"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-115-kitos-war-diaspora-revolt-46"]={"title":"حرب كيتوس / ثورة الشتات","location":"شرق الإمبراطورية الرومانية","story":"اندلعت ثورات يهودية في عدة ولايات رومانية شرقية في عهد تراجان وقُمعت بعنف.","context":"وقعت الثورات في سياق حروب تراجان الشرقية وشملت أيضًا عنفًا طائفيًا شديدًا. وأعداد الضحايا القديمة غير موثوقة.","aftermath":"ألحق القمع أضرارًا جسيمة بعدة مجتمعات يهودية في الشتات وغير وضعها في بعض مناطق شرق الإمبراطورية.","sourceStatus":"الأحداث موثقة جيدًا؛ أعداد الضحايا غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-116-trajanic-revolt-spreads-through-jewish-diaspora-47"]={"title":"انتشار الثورة في عهد تراجان عبر الشتات اليهودي","location":"مصر وبرقة وقبرص وبلاد الرافدين","story":"خلال حروب تراجان الشرقية اندلعت انتفاضات يهودية كبيرة وعنف طائفي في عدة مناطق من العالم الروماني. وتكبد المتمردون اليهود والقوات الرومانية والسكان المحليون خسائر كبيرة. وتُعامل أعداد الضحايا الهائلة في المصادر القديمة بحذر شديد.","context":"يُعرض الحدث مع الانتباه إلى حدود وانحيازات المصادر القديمة، خاصة فيما يتعلق بأعداد الضحايا والدوافع.","aftermath":"انتشرت الانتفاضات عبر عدة ولايات وأدت إلى رد عسكري روماني قاسٍ.","sourceStatus":"مصادر قديمة متعددة؛ حجم الأحداث واضح لكن أعداد الضحايا غير موثوقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-117-roman-suppression-of-the-diaspora-revolt-48"]={"title":"القمع الروماني لثورة الشتات","location":"برقة / مصر / قبرص / بلاد الرافدين","story":"امتدت حرب كيتوس، أو ثورة الشتات، عبر عدة ولايات رومانية شرقية. وتصف المصادر القديمة قتلًا واسعًا نفذه المتمردون اليهود وخصومهم. وفي النهاية قمعت القوات الرومانية الثورات، مع عواقب مدمرة على عدة مجتمعات يهودية.","context":"يحدد الحدث العنف من أطراف متعددة ولا يقبل أرقام الضحايا الدرامية في المصادر القديمة على ظاهرها.","aftermath":"تقلصت بعض المجتمعات اليهودية، خاصة في المناطق الأكثر تضررًا، أو فقدت مكانتها بعد القمع.","sourceStatus":"الثورة موثقة جيدًا؛ أعداد الضحايا القديمة غير موثوقة إلى حد كبير"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-132-bar-kokhba-revolt-49"]={"title":"מרד בר כוכבא","location":"יהודה","story":"בר כוכבא הנהיג מרד יהודי גדול נגד רומא. הדיכוי הרומי החריב חלקים נרחבים מיהודה; יש להתייחס בזהירות למספרי הנפגעים במקורות העתיקים.","context":"המרד היה ניסיון גדול נוסף להתנגד לשלטון הרומי לאחר חורבן בית המקדש השני. הסיבות המדויקות והקשר למדיניות הרומית נידונים במחקר.","aftermath":"הדיכוי גרם אבדות, עקירה ושינויים עמוקים במרכזי החיים היהודיים ביהודה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-135-roman-suppression-after-the-bar-kokhba-revolt-50"]={"title":"הדיכוי הרומי לאחר מרד בר כוכבא","location":"יהודה","story":"לאחר דיכוי מרד בר כוכבא החריבה רומא חלקים נרחבים מיהודה. מקורות עתיקים מתארים אבדות עצומות, שעבוד והרס. ירושלים נוסדה מחדש כמושבה הרומית איליה קפיטולינה, והגישה היהודית לעיר הוגבלה מאוד.","context":"היקף ההרס נתמך במקורות ספרותיים, אפיגרפיים וארכאולוגיים, אך מספרי הנפגעים העתיקים שנויים במחלוקת.","aftermath":"מרכז הכובד של החיים היהודיים בארץ השתנה, והגליל נעשה מרכז חשוב יותר בתקופה שלאחר המרד.","sourceStatus":"ראיות ספרותיות, אפיגרפיות וארכאולוגיות חזקות; מספרי הנפגעים העתיקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-351-jewish-revolt-against-constantius-gallus-51"]={"title":"מרד יהודי נגד קונסטנטיוס גאלוס","location":"הגליל / ציפורי","story":"מרד יהודי פרץ בארץ ישראל הרומית בתקופת קונסטנטיוס השני ובן דודו גאלוס. המורדים השתלטו או תקפו כמה מרכזים, ובהם ציפורי. כוחות רומיים דיכאו את המרד, ומקורות עתיקים מדווחים על הרס משמעותי.","context":"המרד מתועד היסטורית, אך המקורות הספרותיים ששרדו קצרים ולעיתים סותרים זה את זה.","aftermath":"הדיכוי פגע בכמה מרכזים בגליל והמחיש את המשך המתחים בין קהילות יהודיות לשלטון האימפריאלי.","sourceStatus":"האירוע מתועד היסטורית, אך המקורות הספרותיים קצרים ולעיתים סותרים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-415-expulsion-of-jews-from-alexandria-under-cyril-52"]={"title":"גירוש יהודים מאלכסנדריה תחת קירילוס","location":"אלכסנדריה, מצרים הביזנטית","story":"במהלך עימות אלים בין פלגים נוצרים, יהודים ושלטוניים באלכסנדריה, הוביל הפטריארך קירילוס פעולה נגד הקהילה היהודית לאחר פרוץ אלימות בין־קהילתית. סוקרטס סכולסטיקוס מספר שבתי כנסת נתפסו ויהודים רבים גורשו. היקף הגירוש ומשך השפעתו שנויים במחלוקת.","context":"האירוע התרחש בתוך מאבק עירוני מורכב שכלל כמה קבוצות ומוקדי כוח, ולא כפעולה מבודדת ללא הקשר.","aftermath":"הקהילה היהודית באלכסנדריה נפגעה, אך שאלת היקף הגירוש וקביעותו נותרה שנויה במחלוקת.","sourceStatus":"עדויות ספרותיות מן העת העתיקה המאוחרת; היקף האירוע ורצף ההתרחשויות שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-529-samaritan-revolts-and-jewish-communities-in-byzantine-palestine-53"]={"title":"המרידות השומרוניות והקהילות היהודיות בארץ ישראל הביזנטית","location":"ארץ ישראל","story":"מרידות שומרוניות חוזרות נגד השלטון הביזנטי הביאו למלחמה קשה באזור במאה השישית. קהילות יהודיות חיו באותו מרחב מסוכסך ומופיעות בחלק מן המקורות כמשתתפות או כנפגעות, בהתאם למקום ולאירוע. העימותים החריבו חלקים מן הארץ.","context":"יש להבחין בין המרידות השומרוניות המתועדות היטב לבין טענות נקודתיות על השתתפות יהודית, המשתנות לפי המקור והאירוע.","aftermath":"המלחמות החלישו קהילות ואזורים שונים בארץ ישראל הביזנטית ושינו את המאזן הדמוגרפי והפוליטי.","sourceStatus":"המרידות מתועדות היטב; מידת ההשתתפות היהודית משתנה לפי המקור והאירוע"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-614-sasanian-capture-of-jerusalem-54"]={"title":"כיבוש ירושלים בידי הסאסאנים","location":"ירושלים, ארץ ישראל הביזנטית","story":"כוחות פרסיים סאסאניים כבשו את ירושלים במהלך המלחמה הביזנטית–סאסאנית. קבוצות יהודיות השתתפו בצד הפרסי; תושבים נוצרים סבלו מאלימות נרחבת. מקורות מאוחרים חלוקים מאוד לגבי מספרי הנפגעים ותפקידי המשתתפים.","context":"האירוע מבחין בין עצם הכיבוש, המתועד היטב, לבין פרטי מעשי הטבח ומספרי הנפגעים שבהם נדרשת זהירות.","aftermath":"השלטון הפרסי בירושלים היה קצר יחסית, וביזנטיון שב וכבש את האזור בהמשך.","sourceStatus":"עצם הכיבוש מתועד ברמת ודאות גבוהה; פרטי מעשי הטבח והמספרים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-132-bar-kokhba-revolt-49"]={"title":"ثورة بار كوخبا","location":"يهوذا","story":"قاد بار كوخبا ثورة يهودية كبرى ضد روما. وأدى القمع الروماني إلى دمار واسع في يهوذا؛ وينبغي التعامل بحذر مع أعداد الضحايا في المصادر القديمة.","context":"كانت الثورة محاولة كبرى أخرى لمقاومة الحكم الروماني بعد تدمير الهيكل الثاني. ولا تزال الأسباب الدقيقة وعلاقتها بالسياسة الرومانية موضع بحث.","aftermath":"سبب القمع خسائر وتهجيرًا وتغييرات عميقة في مراكز الحياة اليهودية في يهوذا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-135-roman-suppression-after-the-bar-kokhba-revolt-50"]={"title":"القمع الروماني بعد ثورة بار كوخبا","location":"يهوذا","story":"بعد هزيمة ثورة بار كوخبا دمرت روما أجزاء واسعة من يهوذا. وتصف المصادر القديمة خسائر هائلة واستعبادًا ودمارًا. وأعيد تأسيس القدس كمستعمرة رومانية باسم إيليا كابيتولينا، وفُرضت قيود شديدة على دخول اليهود إليها.","context":"تدعم المصادر الأدبية والنقوش والآثار حجم الدمار، لكن أعداد الضحايا القديمة موضع نقاش.","aftermath":"تحول مركز ثقل الحياة اليهودية في البلاد، وأصبح الجليل أكثر أهمية في الفترة التالية للثورة.","sourceStatus":"أدلة أدبية ونقشية وأثرية قوية؛ أعداد الضحايا القديمة موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-351-jewish-revolt-against-constantius-gallus-51"]={"title":"ثورة يهودية ضد قسطنطيوس غالوس","location":"الجليل / صفورية","story":"اندلعت ثورة يهودية في فلسطين الرومانية في عهد قسطنطيوس الثاني وابن عمه غالوس. وسيطر المتمردون على عدة مراكز أو هاجموها، ومنها صفورية. وقمعت القوات الرومانية الانتفاضة، وتذكر المصادر القديمة دمارًا كبيرًا.","context":"الثورة مثبتة تاريخيًا، لكن الروايات الأدبية الباقية موجزة وأحيانًا متناقضة.","aftermath":"أضر القمع بعدة مراكز في الجليل وأظهر استمرار التوتر بين المجتمعات اليهودية والسلطة الإمبراطورية.","sourceStatus":"الحدث مثبت تاريخيًا لكن الروايات الأدبية الباقية موجزة وأحيانًا متناقضة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-415-expulsion-of-jews-from-alexandria-under-cyril-52"]={"title":"طرد اليهود من الإسكندرية في عهد كيرلس","location":"الإسكندرية، مصر البيزنطية","story":"خلال صراع عنيف بين فصائل مسيحية ويهودية وإمبراطورية في الإسكندرية، قاد البطريرك كيرلس إجراءً ضد المجتمع اليهودي بعد اندلاع عنف طائفي. ويذكر سقراط السكولاستيكي أن المعابد اليهودية صودرت وأن كثيرًا من اليهود طُردوا. وحجم الطرد واستمراره موضع نقاش.","context":"وقع الحدث ضمن صراع حضري معقد ضم جماعات ومراكز قوة متعددة، لا كعمل معزول بلا سياق.","aftermath":"تضرر المجتمع اليهودي في الإسكندرية، لكن مدى الطرد ودوامه ما يزالان موضع نقاش.","sourceStatus":"أدلة أدبية من أواخر العصور القديمة؛ حجم الحدث وتسلسله موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-529-samaritan-revolts-and-jewish-communities-in-byzantine-palestine-53"]={"title":"الثورات السامرية والمجتمعات اليهودية في فلسطين البيزنطية","location":"فلسطين","story":"أدت الثورات السامرية المتكررة ضد الحكم البيزنطي إلى حروب شديدة في فلسطين في القرن السادس. وعاشت المجتمعات اليهودية في المشهد المتنازع عليه نفسه، وتظهر في بعض الروايات كمشاركة أو متضررة بحسب المكان والحادثة. ودمرت الصراعات أجزاء من المنطقة.","context":"ينبغي التمييز بين الثورات السامرية الموثقة جيدًا وبين الادعاءات الخاصة بالمشاركة اليهودية التي تختلف حسب المصدر والحادثة.","aftermath":"أضعفت الحروب مجتمعات ومناطق مختلفة في فلسطين البيزنطية وغيرت التوازن السكاني والسياسي.","sourceStatus":"الثورات موثقة جيدًا؛ المشاركة اليهودية المحددة تختلف بحسب المصدر والحادثة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-614-sasanian-capture-of-jerusalem-54"]={"title":"الاستيلاء الساساني على القدس","location":"القدس، فلسطين البيزنطية","story":"استولت القوات الفارسية الساسانية على القدس خلال الحرب البيزنطية الساسانية. وشاركت جماعات يهودية إلى جانب الفرس، بينما تعرض سكان مسيحيون لعنف واسع. وتختلف الروايات اللاحقة كثيرًا بشأن أعداد الضحايا وأدوار المشاركين.","context":"يميز الحدث بين حقيقة الفتح الموثقة جيدًا وبين تفاصيل المذابح وأعداد الضحايا التي تتطلب الحذر.","aftermath":"كان الحكم الفارسي للقدس قصيرًا نسبيًا، واستعادت بيزنطة المنطقة لاحقًا.","sourceStatus":"الفتح الأساسي ثابت بدرجة عالية؛ تفاصيل المذابح والأعداد موضع خلاف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-622-muhammad-s-hijra-to-medina-55"]={"title":"ההיג'רה של מוחמד למדינה","location":"מדינה, חצי האי ערב","story":"מוחמד (בערך 570–632 לספירה) היגר ממכה למדינה בשנת 622. במדינה חיו שבטים יהודיים לצד קבוצות ערביות. אירוע זה יוצר את המסגרת הפוליטית לעימותים מאוחרים יותר המתועדים בציר הזמן.","context":"סמן זה מבחין בין שינוי פוליטי ומעמד קהילתי לבין אירועים ישירים של אלימות.","aftermath":"היחסים בין הקהילה המוסלמית החדשה לבין הקבוצות השונות במדינה השתנו בשנים הבאות וכללו בריתות, מחלוקות ועימותים.","sourceStatus":"ההיג'רה היא אירוע היסטורי מבוסס; פרטים רבים על ההסכמים הקהילתיים שרדו במקורות ספרותיים אסלאמיים מאוחרים יותר"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-624-banu-qaynuqa-conflict-56"]={"title":"העימות עם בני קינוקאע","location":"מדינה","story":"מסורות ספרותיות אסלאמיות מוקדמות מתארות עימות בין קהילתו של מוחמד במדינה לבין בני קינוקאע, ולאחריו גירוש הקבוצה.","context":"האירוע מוכר בעיקר ממקורות אסלאמיים ספרותיים שנכתבו מאוחר יותר, ולכן פרטים, מניעים ורצף האירועים נידונים במחקר.","aftermath":"בני קינוקאע גורשו ממדינה, והמאזן הפוליטי בין הקבוצות בעיר השתנה.","sourceStatus":"מקורות ספרותיים מאוחרים יותר; הפרטים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-625-banu-nadir-conflict-57"]={"title":"העימות עם בני נדיר","location":"מדינה","story":"מקורות אסלאמיים מוקדמים מתארים עימות בין מוחמד לבין בני נדיר ואת גירושם ממדינה.","context":"האירוע מוכר בעיקר ממסורת ספרותית אסלאמית מאוחרת יותר, ולכן יש להבחין בין גרעין האירוע לבין פרטים סיפוריים.","aftermath":"בני נדיר עזבו את מדינה ורבים מהם עברו למרכזים אחרים, ובהם ח'ייבר.","sourceStatus":"מקורות ספרותיים מאוחרים יותר; הפרטים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-627-banu-qurayza-episode-58"]={"title":"פרשת בני קוריט'ה","location":"מדינה","story":"המסורת האסלאמית מתארת את כניעת בני קוריט'ה לאחר קרב השוחה ואת הוצאתם להורג של רבים מן הגברים הבוגרים; הפרטים ומספר ההרוגים שנויים במחלוקת.","context":"האירוע נשען בעיקר על מקורות ספרותיים אסלאמיים מאוחרים. עצם העימות מקובל באופן רחב, אך היקף ההוצאות להורג והפרטים המדויקים נידונים במחקר.","aftermath":"הקהילה חדלה להתקיים כקבוצה פוליטית עצמאית במדינה, והשליטה של קהילתו של מוחמד בעיר התחזקה.","sourceStatus":"מקורות ספרותיים מאוחרים יותר; המספרים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-628-khaybar-campaign-59"]={"title":"מסע ח'ייבר","location":"ח'ייבר, חצי האי ערב","story":"כוחותיו של מוחמד הביסו את קהילות נווה המדבר היהודיות בח'ייבר; הסכמים אפשרו לרבים מן התושבים להישאר תחת תנאים פוליטיים וכלכליים חדשים.","context":"האירוע הצבאי הרחב מבוסס, בעוד פרטים רבים של הסיפור נשענים על מקורות אסלאמיים ספרותיים.","aftermath":"קהילות יהודיות המשיכו להתקיים בח'ייבר לתקופה תחת הסדרי שלטון חדשים.","sourceStatus":"האירוע הרחב מבוסס; פרטי הסיפור נגזרים ממקורות אסלאמיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-629-byzantine-restoration-and-reported-anti-jewish-reprisals-60"]={"title":"השבת השלטון הביזנטי ודיווחים על פעולות תגמול נגד יהודים","location":"ירושלים / ארץ ישראל הביזנטית","story":"לאחר שהקיסר הרקליוס השיב את השליטה הביזנטית, מסורות מאוחרות מתארות רדיפות והרג של יהודים שהואשמו בשיתוף פעולה עם הפרסים. קיומן של הגבלות מחודשות סביר, אך סיפורים על טבח שיטתי ברחבי האימפריה או על שבועה מסוימת של הרקליוס הם מאוחרים ושנויים במחלוקת.","context":"האירוע מבחין בין ראיות חזקות יחסית להגבלות מחודשות לבין סיפורי טבח מאוחרים וחלשים יותר מבחינה היסטורית.","aftermath":"התקופה הביזנטית המחודשת הייתה קצרה; בתוך שנים ספורות השתלטו כוחות מוסלמיים על ירושלים והאזור.","sourceStatus":"הראיות להגבלות חזקות יותר מן המסורות המאוחרות על טבח"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-622-muhammad-s-hijra-to-medina-55"]={"title":"هجرة محمد إلى المدينة","location":"المدينة، شبه الجزيرة العربية","story":"هاجر محمد (نحو 570–632م) من مكة إلى المدينة سنة 622. وضمت المدينة قبائل يهودية إلى جانب جماعات عربية. ويؤسس هذا الحدث للسياق السياسي للصراعات اللاحقة الموثقة في الخط الزمني.","context":"يفصل هذا المؤشر بين التغيير السياسي والوضع الجماعي وبين أحداث العنف المباشرة.","aftermath":"تغيرت العلاقات بين المجتمع المسلم الجديد والجماعات المختلفة في المدينة خلال السنوات التالية وشملت تحالفات وخلافات وصراعات.","sourceStatus":"الهجرة حدث تاريخي ثابت؛ كثير من تفاصيل الاتفاقات المجتمعية بقيت في مصادر أدبية إسلامية لاحقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-624-banu-qaynuqa-conflict-56"]={"title":"الصراع مع بني قينقاع","location":"المدينة","story":"تصف التقاليد الأدبية الإسلامية المبكرة صراعًا بين مجتمع محمد في المدينة وبني قينقاع، أعقبه طرد الجماعة.","context":"يُعرف الحدث أساسًا من مصادر أدبية إسلامية دُوّنت لاحقًا، ولذلك تبقى التفاصيل والدوافع وتسلسل الأحداث موضع بحث.","aftermath":"طُرد بنو قينقاع من المدينة وتغير ميزان القوى السياسي بين جماعاتها.","sourceStatus":"مصادر أدبية لاحقة؛ التفاصيل موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-625-banu-nadir-conflict-57"]={"title":"الصراع مع بني النضير","location":"المدينة","story":"تصف المصادر الإسلامية المبكرة صراع محمد مع بني النضير وطردهم من المدينة.","context":"يُعرف الحدث أساسًا من تقاليد أدبية إسلامية لاحقة، ولذلك ينبغي التمييز بين جوهر الحدث والتفاصيل السردية.","aftermath":"غادر بنو النضير المدينة وانتقل كثير منهم إلى مراكز أخرى منها خيبر.","sourceStatus":"مصادر أدبية لاحقة؛ التفاصيل موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-627-banu-qurayza-episode-58"]={"title":"حادثة بني قريظة","location":"المدينة","story":"تصف التقاليد الإسلامية استسلام بني قريظة بعد معركة الخندق وإعدام عدد كبير من الرجال البالغين؛ والتفاصيل والأعداد موضع نقاش.","context":"يعتمد الحدث أساسًا على مصادر أدبية إسلامية لاحقة. ويُقبل جوهر الصراع على نطاق واسع، لكن حجم الإعدامات والتفاصيل الدقيقة موضع بحث.","aftermath":"انتهى وجود الجماعة كقوة سياسية مستقلة في المدينة وتعززت سيطرة مجتمع محمد على المدينة.","sourceStatus":"مصادر أدبية لاحقة؛ الأعداد موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-628-khaybar-campaign-59"]={"title":"حملة خيبر","location":"خيبر، شبه الجزيرة العربية","story":"هزمت قوات محمد مجتمعات الواحات اليهودية في خيبر، وسمحت اتفاقات لكثير من السكان بالبقاء في ظل شروط سياسية واقتصادية جديدة.","context":"الحدث العسكري العام ثابت، بينما تعتمد تفاصيل كثيرة من الرواية على مصادر أدبية إسلامية.","aftermath":"استمرت مجتمعات يهودية في خيبر فترة من الزمن في ظل ترتيبات حكم جديدة.","sourceStatus":"الحدث العام ثابت؛ التفاصيل السردية مستمدة من مصادر إسلامية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-629-byzantine-restoration-and-reported-anti-jewish-reprisals-60"]={"title":"استعادة الحكم البيزنطي وتقارير الانتقام من اليهود","location":"القدس / فلسطين البيزنطية","story":"بعد أن استعاد الإمبراطور هرقل السيطرة البيزنطية، تصف تقاليد لاحقة اضطهادًا وقتلًا لليهود المتهمين بالتعاون مع الفرس. ووجود قيود متجددة أمر مرجح، لكن روايات مذبحة منهجية على مستوى الإمبراطورية أو قسم محدد لهرقل متأخرة ومتنازع عليها.","context":"يميز الحدث بين الأدلة الأقوى نسبيًا على تجدد القيود وبين روايات المذابح اللاحقة والأضعف تاريخيًا.","aftermath":"كانت استعادة الحكم البيزنطي قصيرة؛ ففي غضون سنوات سيطرت قوات مسلمة على القدس والمنطقة.","sourceStatus":"الأدلة على القيود أقوى من روايات المذابح اللاحقة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"הכיבוש המוסלמי של ירושלים","location":"ירושלים","story":"ירושלים עברה מן השלטון הביזנטי לשלטון מוסלמי מוקדם במהלך הכיבושים הערביים. מסורות מאוחרות קושרות את הממשל החדש לחידוש גישה או התיישבות יהודית לאחר ההגבלות הביזנטיות, אך הפרטים משתנים בין המקורות.","context":"סמן זה מבחין בין שינוי שלטוני ומעמד משפטי לבין אירוע ישיר של אלימות.","aftermath":"החיים היהודיים תחת השלטון המוסלמי השתנו לפי תקופה ושליט; ירושלים שבה להיות נגישה יותר ליהודים לפי חלק מן המקורות.","sourceStatus":"הכיבוש הוא אירוע היסטורי מבוסס; סיפורי הכניעה המפורטים והמדיניות הקהילתית המוקדמת משתנים בין מקורות מאוחרים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"החיים היהודיים תחת השלטון האסלאמי המוקדם ומעמד הד'ימי","location":"השטחים האסלאמיים המוקדמים","story":"במהלך המאות הראשונות של השלטון האסלאמי חיו בדרך כלל קהילות יהודיות ונוצריות כאוכלוסיות לא־מוסלמיות מוגנות אך כפופות מבחינה משפטית. מיסים, הגבלות והיישום המקומי השתנו מאוד בין שליטים, מקומות ותקופות.","context":"סמן זה מתאר מסגרת משפטית ופוליטית רחבה ואינו מציג אותה כאירוע יחיד של אלימות או כמצב אחיד בכל העולם המוסלמי.","aftermath":"קהילות יהודיות התקיימו ואף שגשגו בחלק מן המרכזים, בעוד שבמקומות ובתקופות אחרות הוטלו עליהן מגבלות חמורות יותר.","sourceStatus":"המסגרת המשפטית־היסטורית הרחבה מבוססת; האכיפה והכללים הספציפיים השתנו במידה רבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"רדיפות תחת אל־חאכם","location":"הח'ליפות הפאטמית","story":"בתקופת הח'ליף הפאטמי אל־חאכם הוטלו על נוצרים ויהודים צעדים מפלים וכופים, ובהם הגבלות ופגיעה בבתי תפילה. עוצמת המדיניות והכרונולוגיה שלה השתנו במהלך שלטונו.","context":"האירוע מבחין בין הרדיפה המתועדת היטב לבין סיפורים מאוחרים או הכללות שאינן נתמכות באותה מידה.","aftermath":"ההגבלות השתנו לאורך שלטונו של אל־חאכם וחלקן בוטלו או התרככו בהמשך.","sourceStatus":"רמת ודאות גבוהה לגבי הרדיפה; לא מדובר בטבח יחיד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1066-granada-massacre-64"]={"title":"טבח גרנדה","location":"גרנדה, אל־אנדלוס","story":"המון תקף את הקהילה היהודית בגרנדה והרג את הווזיר היהודי יוסף אבן נגרלה; מקורות מימי הביניים מתארים הרג נרחב בקרב יהודי העיר.","context":"האירוע מתועד כפרץ אלימות אנטי־יהודית משמעותי, אך יש להתייחס בזהירות להערכות מספריות מימי הביניים.","aftermath":"הקהילה היהודית בגרנדה נפגעה קשות, והאירוע נעשה לאחת הדוגמאות הבולטות לאלימות נגד יהודים באל־אנדלוס.","sourceStatus":"האירוע מבוסס; ההערכות המספריות מימי הביניים אינן ודאיות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"האפיפיור אורבנוס השני קורא למסע הצלב הראשון","location":"קלרמון, צרפת","story":"האפיפיור אורבנוס השני קרא למסע צבאי לעבר מזרח הים התיכון. הקריאה לא הופנתה באופן רשמי נגד יהודי אירופה, אך גיוס הצלבנים לווה בשנה שלאחר מכן בהתקפות קשות נגד קהילות יהודיות בחבל הריין.","context":"סמן זה מפריד בין הקריאה הפוליטית־דתית למסע הצלב לבין האלימות נגד יהודים שהתרחשה לאחר מכן.","aftermath":"ההתגייסות למסע הצלב יצרה תנועות חמושות שחלקן תקפו קהילות יהודיות באירופה עוד לפני יציאתן למזרח.","sourceStatus":"הקריאה למסע הצלב מתועדת היטב; הגרסאות ששרדו לנאומו של אורבנוס נכתבו לאחר האירוע"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"الفتح الإسلامي للقدس","location":"القدس","story":"انتقلت القدس من الحكم البيزنطي إلى الحكم الإسلامي المبكر خلال الفتوحات العربية. وتربط تقاليد لاحقة الإدارة الجديدة بتجدد وصول اليهود أو استيطانهم بعد القيود البيزنطية، لكن التفاصيل تختلف بين المصادر.","context":"يفصل هذا المؤشر بين تغير الحكم والوضع القانوني وبين حدث مباشر من العنف.","aftermath":"اختلفت الحياة اليهودية تحت الحكم الإسلامي بحسب الفترة والحاكم؛ وتشير بعض المصادر إلى أن القدس أصبحت أكثر إتاحة لليهود.","sourceStatus":"الفتح حدث تاريخي ثابت؛ روايات الاستسلام التفصيلية والسياسات المجتمعية المبكرة تختلف بين المصادر اللاحقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"الحياة اليهودية تحت الحكم الإسلامي المبكر ووضع أهل الذمة","location":"الأراضي الإسلامية المبكرة","story":"خلال القرون الإسلامية الأولى عاش اليهود والمسيحيون عمومًا كسكان غير مسلمين محميين لكنهم أدنى قانونيًا. واختلفت الضرائب والقيود والممارسة المحلية كثيرًا بين الحكام والأماكن والفترات.","context":"يصف هذا المؤشر إطارًا قانونيًا وسياسيًا واسعًا ولا يقدمه كحادثة عنف واحدة أو كحالة موحدة في جميع أنحاء العالم الإسلامي.","aftermath":"استمرت مجتمعات يهودية وازدهرت في بعض المراكز، بينما واجهت في أماكن وفترات أخرى قيودًا أشد.","sourceStatus":"الإطار القانوني التاريخي العام ثابت؛ التطبيق والقواعد المحددة اختلفت بدرجة كبيرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"الاضطهاد في عهد الحاكم بأمر الله","location":"الخلافة الفاطمية","story":"في عهد الخليفة الفاطمي الحاكم بأمر الله فُرضت إجراءات تمييزية وقسرية على المسيحيين واليهود، شملت قيودًا وإضرارًا بدور العبادة. واختلفت شدة السياسات وتسلسلها الزمني خلال حكمه.","context":"يميز الحدث بين الاضطهاد الموثق جيدًا وبين الروايات اللاحقة أو التعميمات التي لا تدعمها الأدلة بالقدر نفسه.","aftermath":"تغيرت القيود خلال عهد الحاكم وأُلغي أو خُفف بعضها لاحقًا.","sourceStatus":"ثقة عالية في وقوع الاضطهاد؛ لم يكن مذبحة واحدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1066-granada-massacre-64"]={"title":"مذبحة غرناطة","location":"غرناطة، الأندلس","story":"هاجم حشد المجتمع اليهودي في غرناطة وقتل الوزير اليهودي يوسف بن نغريلة؛ وتصف مصادر العصور الوسطى قتلًا واسعًا بين يهود المدينة.","context":"الحدث موثق بوصفه انفجارًا كبيرًا للعنف المعادي لليهود، لكن التقديرات العددية في مصادر العصور الوسطى تتطلب الحذر.","aftermath":"تضرر المجتمع اليهودي في غرناطة بشدة وأصبح الحدث من أبرز أمثلة العنف ضد اليهود في الأندلس.","sourceStatus":"الحدث ثابت؛ التقديرات العددية في العصور الوسطى غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"البابا أوربان الثاني يدعو إلى الحملة الصليبية الأولى","location":"كليرمون، فرنسا","story":"دعا البابا أوربان الثاني إلى حملة مسلحة نحو شرق البحر المتوسط. ولم تكن الدعوة موجهة رسميًا ضد يهود أوروبا، لكن تعبئة الصليبيين أعقبها في العام التالي هجمات شديدة على المجتمعات اليهودية في الراين.","context":"يفصل هذا المؤشر بين الدعوة السياسية والدينية للحملة الصليبية وبين العنف ضد اليهود الذي وقع بعدها.","aftermath":"أنتجت التعبئة الصليبية جماعات مسلحة هاجم بعضها المجتمعات اليهودية في أوروبا قبل توجهها شرقًا.","sourceStatus":"الدعوة إلى الحملة موثقة جيدًا؛ النسخ الباقية من خطاب أوربان كُتبت بعد الحدث"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-speyer-massacre-66"]={"title":"טבח שפייר","location":"שפייר, האימפריה הרומית הקדושה","story":"כאשר אלימות מסע הצלב הראשון התפשטה בחבל הריין, תוקפים פגעו בקהילה היהודית בשפייר. הבישוף הגן על יהודים רבים, אך מספר יהודים נרצחו.","context":"האירוע מתועד היטב בכרוניקות מימי הביניים; פרטים ומספרים מדויקים דורשים זהירות.","aftermath":"ההתקפה בשפייר הייתה חלק מגל רחב יותר שפגע בקהילות יהודיות לאורך הריין.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-worms-massacre-67"]={"title":"טבח וורמס","location":"וורמס, האימפריה הרומית הקדושה","story":"צלבנים ומשתתפים מקומיים תקפו יהודים בוורמס במהלך מסע הצלב הראשון. יהודים רבים נהרגו למרות ניסיונות למצוא מחסה תחת הגנת הבישוף.","context":"האירוע הוא חלק מגל האלימות האנטי־יהודית בחבל הריין בזמן גיוס מסע הצלב הראשון.","aftermath":"הקהילה בוורמס ספגה אבדות כבדות, וגל ההתקפות המשיך לקהילות אחרות באזור.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-mainz-massacre-68"]={"title":"טבח מיינץ","location":"מיינץ, האימפריה הרומית הקדושה","story":"הקהילה היהודית במיינץ הותקפה במהלך מסע הצלב הראשון למרות שחבריה ביקשו מקלט אצל הארכיבישוף. מקורות מימי הביניים מתארים הרג המוני והתאבדויות תחת איום של המרה בכפייה.","context":"גרעין האירוע מתועד היטב, אך מספרי ההרוגים המדויקים משתנים בין הכרוניקות.","aftermath":"הקהילה במיינץ נהרסה במידה רבה והאירוע נעשה סמל מרכזי בזיכרון היהודי של גזירות תתנ״ו.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים; המספרים המדויקים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"טבחי חבל הריין במהלך מסע הצלב הראשון","location":"וורמס, מיינץ, קלן וחבל הריין","story":"קבוצות צלבנים והמונים מקומיים תקפו קהילות יהודיות כאשר מסע הצלב הראשון נע מזרחה.","context":"ההתקפות לא היו יעד רשמי של מסע הצלב שעליו הכריז האפיפיור, אך הן צמחו מתוך גיוס צלבני, קנאות דתית, אינטרסים מקומיים ועוינות אנטי־יהודית.","aftermath":"קהילות רבות נפגעו קשות, והאירועים הותירו חותם עמוק בזיכרון ובכתיבה היהודית האשכנזית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"כיבוש ירושלים בידי הצלבנים","location":"ירושלים","story":"כוחות מסע הצלב הראשון כבשו את ירושלים ביולי 1099 וביצעו טבח בתושבים מוסלמים ויהודים. תושבים יהודים היו בין ההרוגים במהלך הכיבוש.","context":"עצם הכיבוש והטבח מתועדים היטב ממקורות שונים, אך מספרי הנפגעים המדויקים שנמסרו בכרוניקות שנויים במחלוקת.","aftermath":"ירושלים הפכה לבירת ממלכת ירושלים הצלבנית, והאוכלוסיות המוסלמית והיהודית בעיר נפגעו קשות.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הכיבוש והטבח; המספרים המדויקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-speyer-massacre-66"]={"title":"مذبحة شباير","location":"شباير، الإمبراطورية الرومانية المقدسة","story":"مع انتشار عنف الحملة الصليبية الأولى في الراين استهدف مهاجمون المجتمع اليهودي في شباير. وحمى الأسقف كثيرًا من اليهود، لكن عددًا منهم قُتل.","context":"الحدث موثق جيدًا في سجلات العصور الوسطى؛ وتتطلب التفاصيل والأعداد الدقيقة الحذر.","aftermath":"كان الهجوم في شباير جزءًا من موجة أوسع استهدفت المجتمعات اليهودية على طول الراين.","sourceStatus":"ثقة عالية؛ سجلات العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-worms-massacre-67"]={"title":"مذبحة فورمس","location":"فورمس، الإمبراطورية الرومانية المقدسة","story":"هاجم صليبيون ومشاركون محليون اليهود في فورمس خلال الحملة الصليبية الأولى. وقُتل كثير من اليهود رغم محاولات الاحتماء بحماية الأسقف.","context":"الحدث جزء من موجة العنف المعادي لليهود في الراين أثناء تعبئة الحملة الصليبية الأولى.","aftermath":"تكبد مجتمع فورمس خسائر فادحة واستمرت موجة الهجمات إلى مجتمعات أخرى في المنطقة.","sourceStatus":"ثقة عالية؛ سجلات العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-mainz-massacre-68"]={"title":"مذبحة ماينتس","location":"ماينتس، الإمبراطورية الرومانية المقدسة","story":"تعرض المجتمع اليهودي في ماينتس للهجوم خلال الحملة الصليبية الأولى رغم لجوئه إلى رئيس الأساقفة. وتصف مصادر العصور الوسطى قتلًا جماعيًا وانتحارًا تحت تهديد التحول القسري.","context":"جوهر الحدث موثق جيدًا، لكن الأعداد الدقيقة للقتلى تختلف بين السجلات.","aftermath":"دُمر مجتمع ماينتس إلى حد كبير وأصبح الحدث من أبرز رموز ذكرى اضطهادات سنة 1096 في التاريخ اليهودي الأشكنازي.","sourceStatus":"ثقة عالية؛ سجلات العصور الوسطى؛ الأعداد الدقيقة تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"مذابح الراين خلال الحملة الصليبية الأولى","location":"فورمس وماينتس وكولونيا ومنطقة الراين","story":"هاجمت جماعات صليبية وحشود محلية المجتمعات اليهودية مع تحرك الحملة الصليبية الأولى شرقًا.","context":"لم تكن الهجمات هدفًا رسميًا للحملة التي دعا إليها البابا، لكنها نشأت وسط التعبئة الصليبية والحماسة الدينية والمصالح المحلية والعداء لليهود.","aftermath":"تضررت مجتمعات كثيرة بشدة وتركت الأحداث أثرًا عميقًا في الذاكرة والكتابة اليهودية الأشكنازية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"استيلاء الصليبيين على القدس","location":"القدس","story":"استولت قوات الحملة الصليبية الأولى على القدس في يوليو 1099 وذبحت سكانًا مسلمين ويهودًا. وكان سكان يهود بين الذين قُتلوا أثناء الفتح.","context":"الفتح والمذبحة موثقان جيدًا في مصادر متعددة، لكن الأعداد الدقيقة للضحايا الواردة في السجلات موضع خلاف.","aftermath":"أصبحت القدس عاصمة مملكة القدس الصليبية وتضرر سكانها المسلمون واليهود بشدة.","sourceStatus":"ثقة عالية جدًا في الفتح والمذبحة؛ الأعداد الدقيقة موضع خلاف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"הכיבוש המוסלמי של ירושלים","location":"ירושלים","story":"ירושלים עברה משלטון ביזנטי לשלטון מוסלמי מוקדם במהלך הכיבושים הערביים. מסורות מאוחרות מקשרות את הממשל החדש לחידוש גישה או התיישבות יהודית לאחר ההגבלות הביזנטיות, אך הפרטים שונים בין המקורות.","context":"סמן זה מבחין בין שינוי שלטוני ומעמד משפטי לבין אירוע ישיר של אלימות.","aftermath":"החיים היהודיים תחת השלטון המוסלמי השתנו לפי תקופה ושליט וכללו הן אפשרויות מחודשות להתיישבות והן מגבלות משפטיות.","sourceStatus":"הכיבוש מבוסס היטב היסטורית; סיפורי הכניעה המפורטים והמדיניות הקהילתית המוקדמת משתנים במקורות מאוחרים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"חיים יהודיים תחת השלטון המוסלמי המוקדם ומעמד הד'ימי","location":"שטחי האסלאם המוקדם","story":"במהלך המאות הראשונות לשלטון האסלאמי חיו בדרך כלל קהילות יהודיות ונוצריות כאוכלוסיות לא־מוסלמיות מוגנות אך כפופות מבחינה משפטית. מיסים, הגבלות ואופן האכיפה השתנו מאוד בין שליטים, מקומות ותקופות.","context":"זהו תיאור של מסגרת משפטית־פוליטית רחבה, ולא של מצב אחיד בכל העולם המוסלמי או של אירוע אלים יחיד.","aftermath":"קהילות יהודיות המשיכו להתפתח במרכזים רבים תחת שלטון מוסלמי, כאשר רמת הביטחון, האוטונומיה והמגבלות השתנתה ממקום למקום.","sourceStatus":"המסגרת המשפטית־היסטורית הרחבה מבוססת; האכיפה והכללים המסוימים השתנו במידה רבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"רדיפות תחת אל־חאכם","location":"הח'ליפות הפאטמית","story":"תחת הח'ליף הפאטמי אל־חאכם הוטלו צעדים מפלים וכופים על נוצרים ויהודים, ובהם הגבלות והרס בתי תפילה. עוצמת המדיניות והכרונולוגיה שלה השתנו במהלך שלטונו.","context":"האירוע מתאר תקופת רדיפה ומדיניות מפלה, ולא טבח יחיד. יש להבחין בין הצעדים המתועדים לבין סיפורים מאוחרים יותר.","aftermath":"המדיניות השתנתה בהמשך, וחלק מן ההגבלות בוטלו או התרככו לאחר תקופתו.","sourceStatus":"רמת ודאות גבוהה לגבי הרדיפות; לא מדובר בטבח יחיד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1066-granada-massacre-64"]={"title":"טבח גרנדה","location":"גרנדה, אל־אנדלוס","story":"המון תקף את הקהילה היהודית בגרנדה והרג את הווזיר היהודי יוסף אבן נגרילה; מקורות מימי הביניים מתארים הרג נרחב.","context":"האירוע התרחש בתוך מתחים פוליטיים וחברתיים בגרנדה. עצם הטבח מבוסס, אך מספרי ההרוגים במקורות מימי הביניים אינם ודאיים.","aftermath":"הקהילה היהודית בגרנדה נפגעה קשות והאירוע נעשה אחת הדוגמאות הבולטות לאלימות אנטי־יהודית באל־אנדלוס.","sourceStatus":"האירוע מבוסס; האומדנים המספריים מימי הביניים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"האפיפיור אורבנוס השני קורא למסע הצלב הראשון","location":"קלרמון, צרפת","story":"האפיפיור אורבנוס השני קרא למסע מזוין לעבר מזרח הים התיכון. הקריאה לא הופנתה רשמית נגד יהודי אירופה, אך גיוס הצלבנים לווה זמן קצר לאחר מכן בהתקפות אנטי־יהודיות קשות בחבל הריין בשנת 1096.","context":"סמן זה מפריד בין הקריאה הפוליטית־דתית למסע הצלב לבין האלימות נגד יהודים שבאה בעקבות גיוס קבוצות צלבניות מסוימות.","aftermath":"בשנת 1096 תקפו קבוצות צלבנים וקהלים מקומיים קהילות יהודיות במספר ערים בחבל הריין.","sourceStatus":"הקריאה למסע הצלב מתועדת היטב; הגרסאות ששרדו לנאומו של אורבנוס נכתבו לאחר האירוע"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-638-muslim-conquest-of-jerusalem-61"]={"title":"الفتح الإسلامي للقدس","location":"القدس","story":"انتقلت القدس من الحكم البيزنطي إلى الحكم الإسلامي المبكر خلال الفتوحات العربية. وتربط تقاليد لاحقة الإدارة الجديدة بتجدد دخول اليهود أو استيطانهم بعد القيود البيزنطية، لكن التفاصيل تختلف بين المصادر.","context":"يفصل هذا المؤشر بين تغير الحكم والوضع القانوني وبين أحداث العنف المباشرة.","aftermath":"تباينت الحياة اليهودية تحت الحكم الإسلامي بحسب الفترة والحاكم، وشملت فرصًا متجددة للاستيطان إلى جانب قيود قانونية.","sourceStatus":"الفتح ثابت تاريخيًا؛ روايات الاستسلام التفصيلية والسياسات الجماعية المبكرة تختلف في المصادر اللاحقة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-717-jewish-life-under-early-islamic-rule-and-dhimmi-status-62"]={"title":"الحياة اليهودية تحت الحكم الإسلامي المبكر ووضع أهل الذمة","location":"الأراضي الإسلامية المبكرة","story":"خلال القرون الإسلامية الأولى عاشت المجتمعات اليهودية والمسيحية عمومًا كسكان غير مسلمين محميين لكن في وضع قانوني أدنى. وتفاوتت الضرائب والقيود والممارسة المحلية كثيرًا باختلاف الحكام والأماكن والفترات.","context":"هذا وصف لإطار قانوني وسياسي واسع، وليس لحالة موحدة في كل العالم الإسلامي أو لحادثة عنف واحدة.","aftermath":"استمرت المجتمعات اليهودية في التطور في مراكز عديدة تحت الحكم الإسلامي، مع اختلاف الأمن والاستقلال والقيود من مكان إلى آخر.","sourceStatus":"الإطار القانوني التاريخي العام ثابت؛ التطبيق والقواعد المحددة اختلفت بدرجة كبيرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1011-persecution-under-al-hakim-63"]={"title":"الاضطهاد في عهد الحاكم بأمر الله","location":"الخلافة الفاطمية","story":"فرض الخليفة الفاطمي الحاكم بأمر الله إجراءات تمييزية وقسرية على المسيحيين واليهود، شملت قيودًا وتدمير دور عبادة. وتفاوتت شدة السياسات وتسلسلها خلال عهده.","context":"يصف الحدث فترة اضطهاد وسياسات تمييزية، وليس مذبحة واحدة. وينبغي التمييز بين الإجراءات الموثقة والروايات اللاحقة.","aftermath":"تغيرت السياسات لاحقًا، وأُلغيت أو خُففت بعض القيود بعد عهده.","sourceStatus":"ثقة عالية في وقوع الاضطهاد؛ لم يكن مذبحة واحدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1066-granada-massacre-64"]={"title":"مذبحة غرناطة","location":"غرناطة، الأندلس","story":"هاجم حشد المجتمع اليهودي في غرناطة وقتل الوزير اليهودي يوسف بن نغريلة؛ وتصف مصادر العصور الوسطى قتلًا واسعًا.","context":"وقع الحدث وسط توترات سياسية واجتماعية في غرناطة. والمذبحة نفسها ثابتة، لكن أعداد القتلى في مصادر العصور الوسطى غير مؤكدة.","aftermath":"تضرر المجتمع اليهودي في غرناطة بشدة وأصبح الحدث من أبرز أمثلة العنف المعادي لليهود في الأندلس.","sourceStatus":"الحدث ثابت؛ التقديرات العددية في العصور الوسطى غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1095-pope-urban-ii-calls-the-first-crusade-65"]={"title":"البابا أوربان الثاني يدعو إلى الحملة الصليبية الأولى","location":"كليرمون، فرنسا","story":"دعا البابا أوربان الثاني إلى حملة مسلحة نحو شرق البحر المتوسط. ولم تكن الدعوة موجهة رسميًا ضد يهود أوروبا، لكن التعبئة الصليبية أعقبها سريعًا عنف شديد ضد اليهود في الراين سنة 1096.","context":"يفصل هذا المؤشر بين الدعوة السياسية والدينية للحملة الصليبية وبين العنف ضد اليهود الذي رافق تعبئة بعض الجماعات الصليبية.","aftermath":"في سنة 1096 هاجمت جماعات صليبية وحشود محلية مجتمعات يهودية في عدة مدن على نهر الراين.","sourceStatus":"الدعوة إلى الحملة موثقة جيدًا؛ النسخ الباقية من خطاب أوربان كُتبت بعد الحدث"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-speyer-massacre-66"]={"title":"טבח שפייר","location":"שפייר, האימפריה הרומית הקדושה","story":"כאשר האלימות סביב מסע הצלב הראשון התפשטה בחבל הריין, תוקפים פגעו בקהילה היהודית בשפייר. הבישוף הגן על יהודים רבים, אך מספר יהודים נרצחו.","context":"האירוע הוא חלק מגל האלימות האנטי־יהודית של 1096. עצם ההתקפה מתועדת היטב, אך יש לנקוט זהירות בפרטים ובמספרים שבכרוניקות מימי הביניים.","aftermath":"הגנת הבישוף הצילה רבים מבני הקהילה, אך ההתקפה סימנה את תחילת גל הרדיפות בחבל הריין.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-worms-massacre-67"]={"title":"טבח וורמס","location":"וורמס, האימפריה הרומית הקדושה","story":"צלבנים ומשתתפים מקומיים תקפו יהודים בוורמס במהלך מסע הצלב הראשון. יהודים רבים נהרגו למרות ניסיונות למצוא מחסה תחת הגנת הבישוף.","context":"האירוע מתועד בכרוניקות יהודיות ונוצריות מימי הביניים כחלק מגל האלימות בחבל הריין.","aftermath":"הקהילה ספגה אבדות כבדות והאלימות המשיכה במהרה לקהילות נוספות באזור.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-mainz-massacre-68"]={"title":"טבח מיינץ","location":"מיינץ, האימפריה הרומית הקדושה","story":"הקהילה היהודית במיינץ הותקפה במהלך מסע הצלב הראשון אף שחבריה ביקשו מחסה אצל הארכיבישוף. מקורות מימי הביניים מתארים הרג המוני והתאבדויות תחת איום של המרה בכפייה.","context":"עצם הטבח מתועד היטב; המספרים המדויקים ופרטים מסוימים משתנים בין הכרוניקות.","aftermath":"מיינץ, אחד המרכזים היהודיים החשובים בחבל הריין, נפגע קשות והאירוע נחרת בזיכרון היהודי של גזירות תתנ״ו.","sourceStatus":"רמת ודאות גבוהה; כרוניקות מימי הביניים; המספרים המדויקים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"טבחי חבל הריין במהלך מסע הצלב הראשון","location":"וורמס, מיינץ, קלן וחבל הריין","story":"קבוצות צלבנים והמונים מקומיים תקפו קהילות יהודיות כאשר מסע הצלב הראשון נע מזרחה.","context":"האלימות לא הייתה יעד רשמי של מסע הצלב שהוכרז בקלרמון, אך קבוצות צלבנים מסוימות הפנו את הלהט הדתי והאלימות נגד יהודים מקומיים.","aftermath":"קהילות רבות נפגעו, נהרסו או התפזרו, והאירועים נעשו נקודת ציון מרכזית בהיסטוריה של רדיפות יהודי אירופה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"כיבוש ירושלים בידי הצלבנים","location":"ירושלים","story":"כוחות מסע הצלב הראשון כבשו את ירושלים ביולי 1099 וטבחו בתושבים מוסלמים ויהודים. תושבים יהודים היו בין ההרוגים במהלך הכיבוש.","context":"הכיבוש והטבח מתועדים היטב במקורות מכמה מסורות; המספרים המדויקים של ההרוגים שנויים במחלוקת.","aftermath":"הצלבנים הקימו את ממלכת ירושלים הלטינית, והאוכלוסיות המוסלמיות והיהודיות בעיר נפגעו קשות מן הכיבוש.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הכיבוש והטבח; המספרים המדויקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-speyer-massacre-66"]={"title":"مذبحة شباير","location":"شباير، الإمبراطورية الرومانية المقدسة","story":"مع انتشار عنف الحملة الصليبية الأولى في الراين، استهدف مهاجمون المجتمع اليهودي في شباير. وحمى الأسقف كثيرًا من اليهود، لكن عددًا منهم قُتل.","context":"الحادثة جزء من موجة العنف المعادي لليهود سنة 1096. والهجوم نفسه موثق جيدًا، مع ضرورة الحذر في التفاصيل والأرقام الواردة في سجلات العصور الوسطى.","aftermath":"أنقذت حماية الأسقف كثيرًا من أفراد المجتمع، لكن الهجوم كان بداية موجة الاضطهاد في الراين.","sourceStatus":"ثقة عالية؛ سجلات من العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-worms-massacre-67"]={"title":"مذبحة فورمس","location":"فورمس، الإمبراطورية الرومانية المقدسة","story":"هاجم صليبيون ومشاركون محليون اليهود في فورمس خلال الحملة الصليبية الأولى. وقُتل كثير من اليهود رغم محاولات الاحتماء بحماية الأسقف.","context":"توثق سجلات يهودية ومسيحية من العصور الوسطى الحدث ضمن موجة العنف في الراين.","aftermath":"تكبد المجتمع خسائر كبيرة وانتقل العنف سريعًا إلى مجتمعات أخرى في المنطقة.","sourceStatus":"ثقة عالية؛ سجلات من العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-mainz-massacre-68"]={"title":"مذبحة ماينتس","location":"ماينتس، الإمبراطورية الرومانية المقدسة","story":"تعرض المجتمع اليهودي في ماينتس للهجوم خلال الحملة الصليبية الأولى رغم لجوئه إلى رئيس الأساقفة. وتصف مصادر العصور الوسطى قتلًا جماعيًا وانتحارًا تحت تهديد التحول الديني القسري.","context":"المذبحة نفسها موثقة جيدًا؛ وتختلف الأعداد الدقيقة وبعض التفاصيل بين السجلات.","aftermath":"تضررت ماينتس، وهي من أهم المراكز اليهودية في الراين، بشدة وأصبح الحدث جزءًا مركزيًا من ذاكرة اضطهادات سنة 1096.","sourceStatus":"ثقة عالية؛ سجلات من العصور الوسطى؛ الأعداد الدقيقة تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1096-rhineland-massacres-during-the-first-crusade-69"]={"title":"مذابح الراين خلال الحملة الصليبية الأولى","location":"فورمس وماينتس وكولونيا ومنطقة الراين","story":"هاجمت جماعات صليبية وحشود محلية مجتمعات يهودية بينما كانت الحملة الصليبية الأولى تتجه شرقًا.","context":"لم يكن العنف ضد اليهود هدفًا رسميًا للحملة التي أُعلنت في كليرمون، لكن بعض الجماعات الصليبية وجهت الحماسة الدينية والعنف نحو اليهود المحليين.","aftermath":"تضررت أو دُمرت أو تشتتت مجتمعات عديدة، وأصبحت الأحداث محطة كبرى في تاريخ اضطهاد يهود أوروبا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1099-crusader-capture-of-jerusalem-70"]={"title":"استيلاء الصليبيين على القدس","location":"القدس","story":"استولت قوات الحملة الصليبية الأولى على القدس في يوليو 1099 وقتلت سكانًا مسلمين ويهودًا. وكان سكان يهود بين الذين قُتلوا أثناء الفتح.","context":"الفتح والمذبحة موثقان جيدًا في مصادر من تقاليد متعددة؛ أما الأعداد الدقيقة للقتلى فموضع خلاف.","aftermath":"أسس الصليبيون مملكة القدس اللاتينية، وتضرر السكان المسلمون واليهود في المدينة بشدة من الفتح.","sourceStatus":"ثقة عالية جدًا في الفتح والمذبحة؛ الأعداد الدقيقة موضع خلاف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1144-norwich-accusation-and-the-emergence-of-the-blood-libel-71"]={"title":"האשמת נוריץ' והופעת עלילת הדם","location":"נוריץ', אנגליה","story":"לאחר מותו של ויליאם מנוריץ' הואשמו יהודים באופן כוזב ברצח פולחני. ההאשמה נעשתה דגם משפיע לעלילת הדם בימי הביניים — הטענה המפוברקת שיהודים רוצחים ילדים נוצרים לצרכים דתיים. האשמות דומות הובילו בהמשך לרדיפות ולאלימות ברחבי אירופה.","context":"סמן זה מבחין בין הרדיפה ההיסטורית המתועדת לבין ההאשמה הכוזבת ששימשה להצדקתה.","aftermath":"האירוע תרם להתפשטות עלילת הדם ולגלים מאוחרים יותר של רדיפות, הגבלות ואלימות נגד קהילות יהודיות.","sourceStatus":"הופעת ההאשמה מתועדת היטב; טענת הרצח הפולחני עצמה הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1146-second-crusade-violence-and-almohad-persecution-72"]={"title":"אלימות מסע הצלב השני ורדיפות האלמוואחידון","location":"מערב אירופה / צפון אפריקה / איבריה","story":"אמצע המאה ה־12 הביא אלימות אנטי־יהודית הקשורה למסע הצלב השני באירופה, ובמקביל מדיניות כפייה של שלטון האלמוואחידון בצפון אפריקה ובאיבריה.","context":"מדובר בשני הקשרים אזוריים שונים שהתרחשו בתקופה דומה: אלימות צלבנית באירופה ומדיניות דתית כופה תחת האלמוואחידון.","aftermath":"קהילות יהודיות באזורים שונים חוו הרג, לחץ להמרת דת, עקירה והגירה.","sourceStatus":"רמת ודאות גבוהה לגבי הדפוס הרחב"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1171-blois-blood-libel-executions-73"]={"title":"הוצאות להורג בעקבות עלילת הדם בבלואה","location":"בלואה, צרפת","story":"עשרות יהודים נשרפו למוות לאחר האשמת שווא ברצח פולחני, באחד המקרים המוקדמים והבולטים של רדיפה המבוססת על עלילת דם.","context":"ההליך וההוצאות להורג מתועדים היסטורית; ההאשמה שיהודים ביצעו רצח פולחני הייתה כוזבת.","aftermath":"האירוע חיזק את התפשטות עלילות הדם והפחד מפני רדיפות דומות בקהילות יהודיות אחרות.","sourceStatus":"רמת ודאות גבוהה; פרטים מדויקים נשענים על מקורות מימי הביניים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1189-london-coronation-riots-74"]={"title":"מהומות ההכתרה בלונדון","location":"לונדון, אנגליה","story":"אלימות נגד יהודים פרצה סביב הכתרת ריצ'רד הראשון בשנת 1189. בחודשים שלאחר מכן התפשטו התקפות מעבר ללונדון וסייעו ליצור את הרקע לטבח ביורק.","context":"המהומות התרחשו בתוך אווירה של עוינות דתית, חובות ומתחים חברתיים; אין לייחס את פעולות ההמון לכלל האוכלוסייה הנוצרית.","aftermath":"האלימות התפשטה לערים נוספות באנגליה והגיעה לשיאה ביורק בשנת 1190.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1190-york-massacre-at-clifford-s-tower-75"]={"title":"טבח יורק במגדל קליפורד","location":"יורק, אנגליה","story":"כ־150 מבני הקהילה היהודית ביורק נצורו בטירה המלכותית. רבים הרגו את בני משפחותיהם ואת עצמם במקום לעמוד בפני המרה בכפייה או רצח; ניצולים שיצאו מן המבצר נהרגו בידי התוקפים.","context":"האירוע מתועד בכמה כרוניקות וברשומות מנהליות, אם כי יש לנקוט זהירות בפרטי הסיפור ובמספר המדויק.","aftermath":"הקהילה היהודית ביורק הושמדה למעשה באירוע, והוא נעשה אחד מסמלי האלימות האנטי־יהודית באנגליה של ימי הביניים.","sourceStatus":"רמת ודאות גבוהה מאוד; כרוניקות מרובות ורשומות מנהליות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1235-fulda-blood-libel-accusations-76"]={"title":"עלילת הדם בפולדה","location":"פולדה, האימפריה הרומית הקדושה","story":"לאחר מותם של ילדים נוצרים בפולדה הואשמו יהודים מקומיים ברצח פולחני. ההאשמה תרמה לאלימות ונעשתה אחד ממקרי עלילת הדם הבולטים שחזרו מאוחר יותר ברחבי אירופה.","context":"ההאשמה והרדיפה מתועדות היסטורית; הטענה לרצח פולחני הייתה כוזבת.","aftermath":"המקרה תרם להמשך הפצת עלילות הדם ולהגברת הסיכון לקהילות יהודיות באירופה.","sourceStatus":"ההאשמה והרדיפה מתועדות; טענת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1236-anjou-and-poitou-attacks-on-jewish-communities-77"]={"title":"התקפות על קהילות יהודיות באנז'ו ובפואטו","location":"מערב צרפת","story":"אלימות בעלת אופי צלבני במערב צרפת פגעה בקהילות יהודיות באנז'ו ובפואטו. מקורות מימי הביניים מתארים הרג ולחצים להמרת דת בכפייה.","context":"האירועים מוכרים ממקורות ומחקר של ימי הביניים, אך המספרים המדויקים משתנים.","aftermath":"הקהילות שנפגעו חוו אבדות, המרות בכפייה ועקירה.","sourceStatus":"מתועד במחקר ימי הביניים; המספרים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1255-lincoln-blood-libel-case-78"]={"title":"פרשת עלילת הדם בלינקולן","location":"לינקולן, אנגליה","story":"לאחר מותו של ילד נוצרי שנודע כ'יו הקטן מלינקולן', הואשמו יהודים באופן כוזב ברצח פולחני. שמונה־עשר יהודים הוצאו להורג לאחר הליכים שקיבלו תמיכה מן הכתר.","context":"ההליך המשפטי והרדיפה מתועדים; ההאשמה ברצח פולחני הייתה כוזבת.","aftermath":"המקרה חיזק את עלילת הדם באנגליה והוסיף ללחץ המשפטי והחברתי על יהודי הממלכה.","sourceStatus":"רמת ודאות גבוהה; ההאשמה עצמה הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1286-munich-blood-libel-persecution-79"]={"title":"רדיפת עלילת הדם במינכן","location":"מינכן, בוואריה","story":"עלילת דם במינכן נעשתה חלק מן הדפוס המתרחב של ימי הביניים שבו טענות כוזבות על רצח פולחני חשפו קהילות יהודיות לרדיפה ולאלימות.","context":"סמן זה מבחין בין הרדיפה המתועדת לבין טענת הרצח הפולחני הכוזבת ששימשה נגדה.","aftermath":"המקרה הצטרף למסורת מתרחבת של האשמות שווא שסיכנה קהילות יהודיות באירופה.","sourceStatus":"ההאשמה מימי הביניים מתועדת; טענת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1290-expulsion-of-jews-from-england-80"]={"title":"גירוש יהודי אנגליה","location":"אנגליה","story":"אדוארד הראשון הורה בשנת 1290 על גירוש היהודים מאנגליה לאחר עשרות שנים של מיסוי מפלה, הגבלות ואלימות. החיים הקהילתיים היהודיים באנגליה הופסקו רשמית למשך מאות שנים.","context":"הגירוש היה מדיניות מדינה ולא אירוע טבח יחיד, והוא הגיע לאחר תקופה ממושכת של הגבלות ולחץ כלכלי ומשפטי.","aftermath":"הנוכחות היהודית החוקית באנגליה הסתיימה עד להתיישבות מחודשת הדרגתית במאה ה־17.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1298-rintfleisch-massacres-81"]={"title":"טבחי רינטפלייש","location":"פרנקוניה ובוואריה","story":"גל טבח אנטי־יהודי התפשט בקהילות רבות בגרמניה תחת תנועת רינטפלייש.","context":"האלימות התפשטה בין ערים ויישובים רבים; מספרי ההרוגים הכוללים משתנים בין המקורות.","aftermath":"קהילות יהודיות רבות נהרסו או נפגעו קשות והניצולים נעקרו בחלק מן המקומות.","sourceStatus":"רמת ודאות גבוהה; המספרים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1320-shepherds-crusade-attacks-82"]={"title":"התקפות מסע הצלב של הרועים","location":"צרפת וצפון איבריה","story":"קבוצות הקשורות למסע הצלב של הרועים תקפו קהילות יהודיות בחלקים מצרפת ומצפון חצי האי האיברי.","context":"האלימות הייתה גל אזורי של התקפות מצד קבוצות נעות, ולא מדיניות אחידה של כל שלטונות האזור.","aftermath":"קהילות רבות ספגו הרג, המרות כפויות ועקירה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1336-armleder-massacres-83"]={"title":"טבחי ארמלדר","location":"ארצות גרמניה","story":"כנופיות חמושות תקפו קהילות יהודיות בחלקים מארצות גרמניה במהלך שנות ה־1330.","context":"האירועים היו חלק מגלי אלימות מקומיים ואזוריים נגד יהודים בימי הביניים המאוחרים.","aftermath":"מספר קהילות נפגעו או נהרסו והאלימות תרמה לחוסר הביטחון המתמשך של יהודי האזור.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1348-black-death-massacres-84"]={"title":"טבחי המוות השחור","location":"מרכז ומערב אירופה","story":"יהודים הואשמו באופן כוזב בגרימת המגפה באמצעות הרעלת בארות, והאשמות אלה הציתו טבח והרס של קהילות ברחבי אירופה.","context":"המגפה נגרמה ממחלה, לא מהרעלת בארות בידי יהודים. ההאשמה הייתה תאוריית קשר ששימשה להצדקת רדיפה.","aftermath":"קהילות יהודיות רבות הושמדו, גורשו או נעקרו, גם במקומות שבהם הרשויות ניסו להגן עליהן.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1349-strasbourg-massacre-during-the-black-death-85"]={"title":"טבח שטרסבורג בזמן המוות השחור","location":"שטרסבורג, האימפריה הרומית הקדושה","story":"במהלך רדיפות המוות השחור שרפו שלטונות ותושבים בשטרסבורג מספר גדול של יהודים לאחר האשמות שווא שיהודים הרעילו בארות וגרמו למגפה.","context":"הטבח מתועד היטב; האשמת הרעלת הבארות הייתה כוזבת ומספר ההרוגים המדויק משתנה בין המקורות.","aftermath":"הקהילה היהודית בעיר נפגעה אנושות והאירוע נעשה אחד הטבחים הידועים של תקופת המוות השחור.","sourceStatus":"רמת ודאות גבוהה מאוד לגבי הטבח; המספר המדויק משתנה"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1144-norwich-accusation-and-the-emergence-of-the-blood-libel-71"]={"title":"اتهام نورويتش وظهور فرية الدم","location":"نورويتش، إنجلترا","story":"بعد وفاة وليام من نورويتش اتُهم اليهود زورًا بالقتل الطقسي. وأصبح الاتهام نموذجًا مؤثرًا لفرية الدم في العصور الوسطى، وهي الادعاء الملفق بأن اليهود يقتلون أطفالًا مسيحيين لأغراض دينية. وأدت اتهامات مماثلة لاحقًا إلى اضطهاد وعنف في أنحاء أوروبا.","context":"يميز هذا المؤشر بين الاضطهاد التاريخي الموثق وبين الاتهام الكاذب المستخدم لتبريره.","aftermath":"ساهم الحدث في انتشار فرية الدم وفي موجات لاحقة من الاضطهاد والقيود والعنف ضد المجتمعات اليهودية.","sourceStatus":"ظهور الاتهام موثق جيدًا؛ ادعاء القتل الطقسي نفسه كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1146-second-crusade-violence-and-almohad-persecution-72"]={"title":"عنف الحملة الصليبية الثانية واضطهاد الموحدين","location":"أوروبا الغربية / شمال أفريقيا / أيبيريا","story":"شهد منتصف القرن الثاني عشر عنفًا معاديًا لليهود مرتبطًا بالحملة الصليبية الثانية في أوروبا، وبالتوازي سياسات قسرية للموحدين في شمال أفريقيا وأيبيريا.","context":"هذان سياقان إقليميان مختلفان وقعا في فترة متقاربة: عنف صليبي في أوروبا وسياسة دينية قسرية تحت حكم الموحدين.","aftermath":"واجهت مجتمعات يهودية في مناطق مختلفة القتل والضغط للتحول الديني والتهجير والهجرة.","sourceStatus":"ثقة عالية في النمط العام"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1171-blois-blood-libel-executions-73"]={"title":"إعدامات بلوا بسبب فرية الدم","location":"بلوا، فرنسا","story":"أُحرق عشرات اليهود بعد اتهام كاذب بالقتل الطقسي، في إحدى القضايا المبكرة البارزة للاضطهاد القائم على فرية الدم.","context":"الإجراءات والإعدامات موثقة تاريخيًا؛ أما الادعاء بأن اليهود ارتكبوا قتلًا طقسيًا فكان كاذبًا.","aftermath":"عزز الحدث انتشار فرية الدم والخوف من اضطهادات مشابهة في مجتمعات يهودية أخرى.","sourceStatus":"ثقة عالية؛ التفاصيل الدقيقة من مصادر العصور الوسطى"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1189-london-coronation-riots-74"]={"title":"أعمال شغب تتويج لندن","location":"لندن، إنجلترا","story":"اندلع عنف ضد اليهود حول تتويج ريتشارد الأول سنة 1189. وانتشرت الهجمات خارج لندن خلال الأشهر التالية ومهدت للمذبحة في يورك.","context":"وقعت الاضطرابات وسط عداء ديني وديون وتوترات اجتماعية؛ ولا ينبغي نسب أعمال الحشود إلى المجتمع المسيحي بأكمله.","aftermath":"انتشر العنف إلى مدن إنجليزية أخرى وبلغ ذروته في يورك سنة 1190.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1190-york-massacre-at-clifford-s-tower-75"]={"title":"مذبحة يورك في برج كليفورد","location":"يورك، إنجلترا","story":"حُوصر نحو 150 من أفراد المجتمع اليهودي في يورك داخل القلعة الملكية. وقتل كثيرون أسرهم وأنفسهم بدل مواجهة التحول القسري أو القتل؛ وقُتل ناجون خرجوا من القلعة على يد المهاجمين.","context":"توثق الحادثة عدة سجلات ووثائق إدارية، مع ضرورة الحذر في بعض التفاصيل والعدد الدقيق.","aftermath":"دُمر المجتمع اليهودي في يورك فعليًا في الحادثة وأصبحت من أبرز رموز العنف المعادي لليهود في إنجلترا الوسيطة.","sourceStatus":"ثقة عالية جدًا؛ سجلات متعددة ووثائق إدارية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1235-fulda-blood-libel-accusations-76"]={"title":"اتهامات فرية الدم في فولدا","location":"فولدا، الإمبراطورية الرومانية المقدسة","story":"بعد وفاة أطفال مسيحيين في فولدا اتُهم اليهود المحليون بالقتل الطقسي. وساهم الاتهام في العنف وأصبح من أبرز قضايا فرية الدم التي تكررت لاحقًا في أوروبا.","context":"الاتهام والاضطهاد موثقان تاريخيًا؛ أما ادعاء القتل الطقسي فكان كاذبًا.","aftermath":"ساهمت القضية في استمرار نشر فرية الدم وزيادة الخطر على المجتمعات اليهودية في أوروبا.","sourceStatus":"الاتهام والاضطهاد موثقان؛ ادعاء القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1236-anjou-and-poitou-attacks-on-jewish-communities-77"]={"title":"هجمات أنجو وبواتو على المجتمعات اليهودية","location":"غرب فرنسا","story":"استهدف عنف ذو طابع صليبي في غرب فرنسا مجتمعات يهودية في أنجو وبواتو. وتصف مصادر العصور الوسطى عمليات قتل وضغوطًا للتحول الديني القسري.","context":"الأحداث معروفة من مصادر ودراسات العصور الوسطى، لكن الأعداد الدقيقة تختلف.","aftermath":"واجهت المجتمعات المتضررة خسائر وتحولات قسرية وتهجيرًا.","sourceStatus":"موثق في دراسات العصور الوسطى؛ الأعداد تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1255-lincoln-blood-libel-case-78"]={"title":"قضية فرية الدم في لنكولن","location":"لنكولن، إنجلترا","story":"بعد وفاة طفل مسيحي عُرف باسم هيو الصغير من لنكولن، اتُهم اليهود زورًا بالقتل الطقسي. وأُعدم ثمانية عشر يهوديًا بعد إجراءات شجعها التاج.","context":"الإجراءات القضائية والاضطهاد موثقان؛ اتهام القتل الطقسي كان كاذبًا.","aftermath":"عززت القضية فرية الدم في إنجلترا وأضافت إلى الضغط القانوني والاجتماعي على يهود المملكة.","sourceStatus":"ثقة عالية؛ الاتهام نفسه كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1286-munich-blood-libel-persecution-79"]={"title":"اضطهاد فرية الدم في ميونيخ","location":"ميونيخ، بافاريا","story":"أصبحت فرية دم في ميونيخ جزءًا من نمط متوسع في العصور الوسطى عرّضت فيه ادعاءات القتل الطقسي الكاذبة المجتمعات اليهودية للاضطهاد والعنف.","context":"يميز هذا المؤشر بين الاضطهاد الموثق وبين ادعاء القتل الطقسي الكاذب المستخدم ضده.","aftermath":"انضمت القضية إلى تقليد متوسع من الاتهامات الكاذبة التي عرضت المجتمعات اليهودية الأوروبية للخطر.","sourceStatus":"الاتهام الوسيط موثق؛ ادعاء القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1290-expulsion-of-jews-from-england-80"]={"title":"طرد اليهود من إنجلترا","location":"إنجلترا","story":"أمر إدوارد الأول بطرد اليهود من إنجلترا سنة 1290 بعد عقود من الضرائب التمييزية والقيود والعنف. وانتهت الحياة الجماعية اليهودية الرسمية في إنجلترا لقرون.","context":"كان الطرد سياسة دولة لا مذبحة منفردة، وجاء بعد فترة طويلة من القيود والضغط الاقتصادي والقانوني.","aftermath":"انتهى الوجود اليهودي القانوني في إنجلترا حتى عودة الاستيطان تدريجيًا في القرن السابع عشر.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1298-rintfleisch-massacres-81"]={"title":"مذابح رينتفلايش","location":"فرانكونيا وبافاريا","story":"انتشرت موجة من المذابح المعادية لليهود عبر مجتمعات ألمانية عديدة تحت حركة رينتفلايش.","context":"امتد العنف بين مدن وبلدات كثيرة؛ وتختلف أعداد القتلى الإجمالية بين المصادر.","aftermath":"دُمرت أو تضررت بشدة مجتمعات يهودية عديدة وهُجر الناجون في بعض المناطق.","sourceStatus":"ثقة عالية؛ الأعداد تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1320-shepherds-crusade-attacks-82"]={"title":"هجمات حملة الرعاة الصليبية","location":"فرنسا وشمال أيبيريا","story":"هاجمت جماعات مرتبطة بحملة الرعاة الصليبية مجتمعات يهودية في أجزاء من فرنسا وشمال شبه الجزيرة الأيبيرية.","context":"كان العنف موجة إقليمية من هجمات جماعات متنقلة، لا سياسة موحدة لجميع سلطات المنطقة.","aftermath":"تعرضت مجتمعات عديدة للقتل والتحول القسري والتهجير.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1336-armleder-massacres-83"]={"title":"مذابح أرملدر","location":"الأراضي الألمانية","story":"هاجمت جماعات مسلحة مجتمعات يهودية في أجزاء من الأراضي الألمانية خلال ثلاثينيات القرن الرابع عشر.","context":"كانت الأحداث جزءًا من موجات عنف محلية وإقليمية ضد اليهود في أواخر العصور الوسطى.","aftermath":"تضررت أو دُمرت عدة مجتمعات وساهم العنف في استمرار انعدام الأمن لدى يهود المنطقة.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1348-black-death-massacres-84"]={"title":"مذابح الموت الأسود","location":"وسط وغرب أوروبا","story":"اتُهم اليهود زورًا بالتسبب في الطاعون عبر تسميم الآبار، فأشعلت هذه الاتهامات مذابح وتدمير مجتمعات في أنحاء أوروبا.","context":"كان الطاعون مرضًا ولم ينتج عن تسميم اليهود للآبار. وكان الاتهام نظرية مؤامرة استُخدمت لتبرير الاضطهاد.","aftermath":"دُمرت أو طُردت أو هُجرت مجتمعات يهودية كثيرة، حتى في أماكن حاولت فيها السلطات حمايتها.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1349-strasbourg-massacre-during-the-black-death-85"]={"title":"مذبحة ستراسبورغ أثناء الموت الأسود","location":"ستراسبورغ، الإمبراطورية الرومانية المقدسة","story":"خلال اضطهادات الموت الأسود أحرق مسؤولو وسكان ستراسبورغ عددًا كبيرًا من اليهود بعد اتهامات كاذبة بأن اليهود سمموا الآبار وتسببوا في الطاعون.","context":"المذبحة موثقة جيدًا؛ اتهام تسميم الآبار كان كاذبًا ويختلف العدد الدقيق للقتلى بين المصادر.","aftermath":"تضرر المجتمع اليهودي في المدينة بصورة كارثية وأصبحت الحادثة من أشهر مذابح فترة الموت الأسود.","sourceStatus":"ثقة عالية جدًا في المذبحة؛ العدد الدقيق يختلف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1391-anti-jewish-massacres-in-iberia-86"]={"title":"טבחי יהודים בחצי האי האיברי","location":"קסטיליה ואראגון","story":"גל אלימות עירונית שטף קהילות יהודיות בספרד, הרג יהודים ודחף רבים אחרים להמרת דת בכפייה.","context":"האירועים היו גל רחב של אלימות קהילתית ולא תקרית יחידה, והתרחשו בתוך מתחים דתיים, חברתיים ופוליטיים.","aftermath":"הקהילות היהודיות נפגעו קשות, ומספר גדול של יהודים נעשו נוצרים חדשים בעקבות כפייה ולחץ.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1421-vienna-gesera-87"]={"title":"גזירת וינה","location":"דוכסות אוסטריה","story":"יהודי אוסטריה נעצרו, רכושם הוחרם, ורבים גורשו או הוצאו להורג במהלך גזירת וינה.","context":"האירוע היה רדיפה בחסות השלטון שכללה החרמת רכוש, גירוש והוצאות להורג.","aftermath":"הקהילה היהודית בווינה ובאזורים נוספים באוסטריה נהרסה או גורשה במידה רבה.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1475-trent-blood-libel-persecution-88"]={"title":"רדיפת עלילת הדם בטרנטו","location":"טרנטו, נסיכות־הבישופות של טרנטו","story":"לאחר היעלמות ילד נוצרי הואשמו יהודים מקומיים ברצח פולחני, עונו והוצאו להורג. טענת הרצח הפולחני הייתה כוזבת ונעשתה אחת מעלילות הדם המשפיעות באירופה.","context":"האירוע מבחין בין הרדיפה וההוצאות להורג המתועדות היטב לבין עלילת הרצח הפולחני הכוזבת.","aftermath":"הפרשה חיזקה את הפצת עלילת הדם והובילה לרדיפות נוספות נגד יהודים.","sourceStatus":"רמת ודאות גבוהה; טענת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1478-spanish-inquisition-begins-89"]={"title":"תחילת האינקוויזיציה הספרדית","location":"ספרד","story":"האינקוויזיציה הספרדית רדפה חשודים בכפירה, ובהם יהודים מומרים שנחשדו בקיום יהדות בסתר; נעשה שימוש בחקירות, עינויים והוצאות להורג.","context":"האינקוויזיציה כוונה רשמית לנוצרים ולנוצרים חדשים שנחשדו בכפירה, ולא ליהודים שנותרו יהודים, אך היא השפיעה עמוקות על משפחות ממוצא יהודי.","aftermath":"הרדיפה הגבירה פחד, פיקוח והגירה בקרב נוצרים חדשים וסייעה ליצור את הרקע לגירוש היהודים מספרד.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1492-expulsion-of-jews-from-spain-90"]={"title":"גירוש יהודי ספרד","location":"ספרד","story":"צו אלהמברה הורה ליהודים שנותרו יהודים להתנצר או לעזוב את ספרד, וגרם לעקירה המונית ולמצוקה קשה.","context":"הגירוש היה מדיניות מדינה של המלוכה הספרדית, ולא אירוע טבח יחיד.","aftermath":"יהודים רבים עברו לפורטוגל, לצפון אפריקה, לאימפריה העות'מאנית ולמקומות אחרים, והשפיעו על התפתחות התפוצה הספרדית.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1497-forced-conversion-of-jews-in-portugal-91"]={"title":"המרת דת בכפייה של יהודי פורטוגל","location":"ממלכת פורטוגל","story":"לאחר שיהודים רבים שגורשו מספרד נכנסו לפורטוגל, הורה המלך מנואל הראשון ליהודים לעזוב את ממלכתו. בפועל מנעו השלטונות מרובם לצאת וכפו הטבלה המונית בשנת 1497, וכך נוצרה אוכלוסייה גדולה של נוצרים חדשים.","context":"האירוע היה מדיניות מדינה של המרה בכפייה ולא בחירה דתית חופשית.","aftermath":"קהילות יהודיות גלויות בפורטוגל נעלמו כמעט לחלוטין, בעוד נוצרים חדשים רבים המשיכו להתמודד עם חשד ורדיפה.","sourceStatus":"מדיניות המדינה וההמרה בכפייה מתועדות היטב; אומדני מספר הנפגעים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1510-brandenburg-host-desecration-persecution-92"]={"title":"רדיפת חילול לחם הקודש בברנדנבורג","location":"ברנדנבורג, האימפריה הרומית הקדושה","story":"יהודים בברנדנבורג הואשמו בפרשת חילול לחם הקודש, והדבר הוביל להוצאות להורג ולגירוש. האשמות כאלה טענו באופן כוזב שיהודים פגעו בלחם הקודש הנוצרי ושימשו שוב ושוב עילה לרדיפה.","context":"ההליך והעונשים היו היסטוריים; הטענה העל־טבעית על חילול לחם הקודש הייתה עלילה דתית.","aftermath":"הקהילה נפגעה מהוצאות להורג וגירוש, והאירוע הצטרף לדפוס אירופי של רדיפות המבוססות על האשמות דתיות כוזבות.","sourceStatus":"ההליך וההוצאות להורג היסטוריים; האשמת חילול לחם הקודש הייתה עלילה דתית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1648-khmelnytsky-uprising-massacres-93"]={"title":"טבחי מרד חמלניצקי","location":"האיחוד הפולני–ליטאי / אוקראינה","story":"במהלך מרד חמלניצקי היו קהילות יהודיות בין האוכלוסיות שסבלו מהרג והרס נרחבים. אומדני ההרוגים ההיסטוריים משתנים מאוד.","context":"האלימות התרחשה בתוך מלחמה רחבה שכללה קוזאקים, האיחוד הפולני–ליטאי וקבוצות נוספות. אין להתייחס לאומדני נפגעים מסורתיים כאל מספרים ודאיים.","aftermath":"קהילות יהודיות רבות נהרסו או נעקרו והאירועים הותירו חותם עמוק בזיכרון היהודי של מזרח אירופה.","sourceStatus":"רמת ודאות גבוהה לגבי גל הטבח; המספרים הכוללים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1648-nemyriv-massacre-during-the-khmelnytsky-uprising-94"]={"title":"טבח נמירוב במהלך מרד חמלניצקי","location":"נמירוב, האיחוד הפולני–ליטאי","story":"במהלך מרד חמלניצקי כבשו כוחות קוזאקים ובעלי ברית את נמירוב והרגו תושבים יהודים רבים וכן יריבים אחרים. כרוניקות יהודיות זכרו את האירוע כאחד האסונות הגדולים של 1648.","context":"הטבח מתועד בכרוניקות בנות התקופה וסמוכות לה; מספרי הנפגעים המדויקים שנויים במחלוקת.","aftermath":"הקהילה היהודית בנמירוב נפגעה באופן קטסטרופלי והאירוע נעשה חלק מרכזי מזיכרון גזירות ת״ח–ת״ט.","sourceStatus":"הטבח מתועד היטב; מספרי הנפגעים המדויקים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1648-tulchyn-massacre-during-the-khmelnytsky-uprising-95"]={"title":"טבח טולצ'ין במהלך מרד חמלניצקי","location":"טולצ'ין, האיחוד הפולני–ליטאי","story":"בטולצ'ין התנגדו בתחילה יהודים ומגינים פולנים לכוחות הצרים. מקורות יהודיים בני התקופה מתארים בגידה ולאחריה הרג המוני. האירוע הוא חלק מן החורבן הרחב של קהילות יהודיות בשנים 1648–1649.","context":"האירוע מתועד בכרוניקות יהודיות; מספרים מדויקים וחלק מפרטי הסיפור נותרים בלתי ודאיים.","aftermath":"הקהילה נפגעה קשות והטבח הצטרף לגל החורבן הרחב של המרד.","sourceStatus":"האירוע מתועד בכרוניקות יהודיות; מספרים מדויקים וחלק מן הפרטים אינם ודאיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1768-uman-massacre-during-the-koliivshchyna-uprising-96"]={"title":"טבח אומן במהלך מרד הקולייבשצ'ינה","location":"אומן, האיחוד הפולני–ליטאי","story":"מורדי ההיידמקים כבשו את אומן במהלך מרד הקולייבשצ'ינה והרגו מספר גדול של יהודים, אצילים פולנים, אנשי כמורה ותושבים אחרים. מקורות מאוחרים נותנים אומדנים שונים מאוד, ולכן אין להציג מספר מסורתי אחד כוודאי.","context":"הטבח התרחש כחלק ממרד חברתי, פוליטי ודתי רחב יותר שפגע בכמה אוכלוסיות.","aftermath":"האירוע הותיר הרס כבד באומן ונעשה חלק מן הזיכרון ההיסטורי של הקהילות שנפגעו.","sourceStatus":"הטבח היסטורי; אומדני הנפגעים משתנים מאוד במקורות מאוחרים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1391-anti-jewish-massacres-in-iberia-86"]={"title":"مذابح معادية لليهود في أيبيريا","location":"قشتالة وأراغون","story":"اجتاحت موجة من العنف الحضري المجتمعات اليهودية في إسبانيا، فقتلت يهودًا ودفعت كثيرين آخرين إلى التحول الديني القسري.","context":"كانت الأحداث موجة واسعة من العنف المجتمعي وليست حادثة واحدة، ووقعت وسط توترات دينية واجتماعية وسياسية.","aftermath":"تضررت المجتمعات اليهودية بشدة وأصبح عدد كبير من اليهود مسيحيين جددًا نتيجة الإكراه والضغط.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1421-vienna-gesera-87"]={"title":"اضطهاد فيينا","location":"دوقية النمسا","story":"اعتُقل يهود النمسا وصودرت ممتلكاتهم وطُرد أو أُعدم كثيرون خلال اضطهاد فيينا.","context":"كان الحدث اضطهادًا برعاية السلطة شمل مصادرة الممتلكات والطرد والإعدامات.","aftermath":"دُمر أو طُرد جزء كبير من المجتمع اليهودي في فيينا ومناطق أخرى من النمسا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1475-trent-blood-libel-persecution-88"]={"title":"اضطهاد فرية الدم في ترينت","location":"ترينت، أسقفية ترينت","story":"بعد اختفاء طفل مسيحي اتُهم اليهود المحليون بالقتل الطقسي وعُذبوا وأُعدموا. وكان ادعاء القتل الطقسي كاذبًا وأصبح من أكثر فريات الدم تأثيرًا في أوروبا.","context":"يميز الحدث بين الاضطهاد والإعدامات الموثقة جيدًا وبين فرية القتل الطقسي الكاذبة.","aftermath":"عززت القضية انتشار فرية الدم وأدت إلى مزيد من الاضطهاد ضد اليهود.","sourceStatus":"ثقة عالية؛ ادعاء القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1478-spanish-inquisition-begins-89"]={"title":"بداية محاكم التفتيش الإسبانية","location":"إسبانيا","story":"استهدفت محاكم التفتيش الإسبانية المشتبه بهم بالهرطقة، ومنهم يهود تحولوا إلى المسيحية واتُهموا بممارسة اليهودية سرًا؛ واستخدمت التحقيق والتعذيب والإعدام.","context":"استهدفت المحاكم رسميًا المسيحيين والمسيحيين الجدد المشتبه في هرطقتهم، لا اليهود الذين ظلوا يهودًا، لكنها أثرت بعمق في عائلات من أصول يهودية.","aftermath":"زاد الاضطهاد الخوف والمراقبة والهجرة بين المسيحيين الجدد وساهم في خلق السياق لطرد اليهود من إسبانيا.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1492-expulsion-of-jews-from-spain-90"]={"title":"طرد اليهود من إسبانيا","location":"إسبانيا","story":"أمر مرسوم الحمراء اليهود المتمسكين باليهودية بالتحول إلى المسيحية أو مغادرة إسبانيا، مما أدى إلى تهجير جماعي ومعاناة شديدة.","context":"كان الطرد سياسة دولة من الملكية الإسبانية وليس مذبحة منفردة.","aftermath":"انتقل كثير من اليهود إلى البرتغال وشمال أفريقيا والإمبراطورية العثمانية ومناطق أخرى، وأسهموا في نشوء الشتات السفاردي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1497-forced-conversion-of-jews-in-portugal-91"]={"title":"التحول القسري ليهود البرتغال","location":"مملكة البرتغال","story":"بعد دخول كثير من اليهود المطرودين من إسبانيا إلى البرتغال أمر الملك مانويل الأول اليهود بمغادرة المملكة. لكن السلطات منعت معظمهم عمليًا من الرحيل وفرضت تعميدًا جماعيًا سنة 1497، مما أنشأ عددًا كبيرًا من المسيحيين الجدد.","context":"كان الحدث سياسة دولة للتحول القسري لا اختيارًا دينيًا حرًا.","aftermath":"اختفت تقريبًا المجتمعات اليهودية العلنية في البرتغال، بينما ظل كثير من المسيحيين الجدد عرضة للشك والاضطهاد.","sourceStatus":"سياسة الدولة والتحول القسري موثقان جيدًا؛ تقديرات عدد المتضررين تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1510-brandenburg-host-desecration-persecution-92"]={"title":"اضطهاد تدنيس القربان في براندنبورغ","location":"براندنبورغ، الإمبراطورية الرومانية المقدسة","story":"اتُهم يهود في براندنبورغ في قضية تدنيس القربان، مما أدى إلى إعدامات وطرد. وكانت مثل هذه الاتهامات تزعم كذبًا أن اليهود يسيئون إلى خبز القربان المسيحي واستُخدمت مرارًا ذريعة للاضطهاد.","context":"كانت المحاكمة والعقوبات تاريخية؛ أما الادعاء الخارق بشأن تدنيس القربان فكان فرية دينية.","aftermath":"تضرر المجتمع بالإعدامات والطرد وانضمت الحادثة إلى نمط أوروبي من الاضطهاد المبني على اتهامات دينية كاذبة.","sourceStatus":"المحاكمة والإعدامات تاريخية؛ اتهام تدنيس القربان كان فرية دينية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1648-khmelnytsky-uprising-massacres-93"]={"title":"مذابح انتفاضة خميلنيتسكي","location":"الكومنولث البولندي الليتواني / أوكرانيا","story":"خلال انتفاضة خميلنيتسكي كانت المجتمعات اليهودية من بين السكان الذين تعرضوا لقتل ودمار واسع. وتختلف تقديرات الوفيات التاريخية بدرجة كبيرة.","context":"وقع العنف داخل حرب أوسع ضمت القوزاق والكومنولث البولندي الليتواني وجماعات أخرى. ولا ينبغي التعامل مع تقديرات الضحايا التقليدية كأرقام مؤكدة.","aftermath":"دُمرت أو هُجرت مجتمعات يهودية كثيرة وتركت الأحداث أثرًا عميقًا في الذاكرة اليهودية لشرق أوروبا.","sourceStatus":"ثقة عالية في موجة المذابح؛ الأعداد الإجمالية موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1648-nemyriv-massacre-during-the-khmelnytsky-uprising-94"]={"title":"مذبحة نميروف خلال انتفاضة خميلنيتسكي","location":"نميروف، الكومنولث البولندي الليتواني","story":"خلال انتفاضة خميلنيتسكي استولت قوات قوزاق وحلفاؤها على نميروف وقتلت كثيرًا من السكان اليهود وغيرهم من الخصوم. وذكرت السجلات اليهودية الحادثة بوصفها من كوارث سنة 1648 الكبرى.","context":"المذبحة موثقة في سجلات معاصرة وقريبة من العصر؛ الأعداد الدقيقة للضحايا موضع خلاف.","aftermath":"تعرض المجتمع اليهودي في نميروف لدمار كارثي وأصبحت الحادثة جزءًا مركزيًا من ذاكرة أحداث 1648–1649.","sourceStatus":"المذبحة موثقة جيدًا؛ الأعداد الدقيقة للضحايا موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1648-tulchyn-massacre-during-the-khmelnytsky-uprising-95"]={"title":"مذبحة تولتشين خلال انتفاضة خميلنيتسكي","location":"تولتشين، الكومنولث البولندي الليتواني","story":"في تولتشين قاوم اليهود والمدافعون البولنديون في البداية القوات المحاصرة. وتصف روايات يهودية معاصرة خيانة أعقبها قتل جماعي. والحادثة جزء من الدمار الأوسع للمجتمعات اليهودية في 1648–1649.","context":"الحادثة موثقة في سجلات يهودية؛ وتبقى الأعداد الدقيقة وبعض التفاصيل السردية غير مؤكدة.","aftermath":"تضرر المجتمع بشدة وانضمت المذبحة إلى موجة الدمار الأوسع للانتفاضة.","sourceStatus":"الحادثة موثقة في سجلات يهودية؛ الأعداد الدقيقة وبعض التفاصيل غير مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1768-uman-massacre-during-the-koliivshchyna-uprising-96"]={"title":"مذبحة أومان خلال انتفاضة كولييفشتشينا","location":"أومان، الكومنولث البولندي الليتواني","story":"استولى متمردو الهايداماك على أومان خلال انتفاضة كولييفشتشينا وقتلوا أعدادًا كبيرة من اليهود والنبلاء البولنديين ورجال الدين وسكان آخرين. وتعطي الروايات اللاحقة تقديرات متفاوتة جدًا، لذلك لا ينبغي تقديم رقم تقليدي واحد على أنه مؤكد.","context":"وقعت المذبحة ضمن انتفاضة اجتماعية وسياسية ودينية أوسع أضرت بعدة جماعات سكانية.","aftermath":"تركت الحادثة دمارًا كبيرًا في أومان وأصبحت جزءًا من الذاكرة التاريخية للمجتمعات المتضررة.","sourceStatus":"المذبحة تاريخية؛ تقديرات الضحايا تختلف كثيرًا في المصادر اللاحقة"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1819-hep-hep-riots-97"]={"title":"מהומות הֶפּ־הֶפּ","location":"המדינות הגרמניות","story":"מהומות אנטי־יהודיות שהחלו בווירצבורג התפשטו לערים גרמניות אחדות בתקופה של ויכוח על אמנציפציה ליהודים. המונים תקפו בתים, עסקים ויחידים יהודים תוך קריאת הסיסמה שממנה קיבלו המהומות את שמן.","context":"האירוע התרחש בתוך מתחים פוליטיים, כלכליים וחברתיים סביב מעמדם האזרחי של יהודים.","aftermath":"המהומות ערערו את ביטחון הקהילות והמחישו את ההתנגדות הציבורית לאמנציפציה יהודית בחלק מן המדינות הגרמניות.","sourceStatus":"מתועד היטב ברשומות בנות התקופה; המניעים שילבו דעות קדומות אנטי־יהודיות עם מתחים פוליטיים וכלכליים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1821-odessa-anti-jewish-riot-98"]={"title":"מהומה אנטי־יהודית באודסה","location":"אודסה, האימפריה הרוסית","story":"מהומה אנטי־יהודית באודסה בשנת 1821 מזוהה לעיתים כאחד האירועים הראשונים שכונו לימים פוגרום.","context":"האירוע היה מקומי ויש להבחין בינו לבין גלי הפוגרומים הרחבים יותר של סוף המאה ה־19.","aftermath":"האלימות קדמה לגלים מאוחרים יותר של פוגרומים באודסה וברחבי האימפריה הרוסית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1834-safed-looting-and-attacks-on-the-jewish-community-99"]={"title":"ביזה והתקפות על הקהילה היהודית בצפת","location":"צפת, ארץ ישראל העות'מאנית","story":"במהלך המהומות האזוריות הקשורות למרד 1834 בארץ ישראל הותקפה הקהילה היהודית בצפת ונבזזה בהיקף נרחב. בתים ובתי כנסת ניזוקו ותושבים הותקפו ונעקרו.","context":"האירוע התרחש בתוך מרד אזורי רחב יותר; המקורות מסכימים על ההתקפות והביזה אך שונים בפרטים ובמספרי הנפגעים.","aftermath":"הקהילה סבלה אובדן רכוש, פציעות ועקירה ונדרשה לתהליך שיקום.","sourceStatus":"ההתקפות והביזה מתועדות; המקורות שונים בפרטים ובמספרי הנפגעים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1840-damascus-affair-100"]={"title":"עלילת דמשק","location":"דמשק, סוריה העות'מאנית","story":"לאחר היעלמות נזיר קתולי ומשרתו הואשמו יהודים מדמשק באופן כוזב ברצח פולחני. כמה מהם נכלאו ועונו. פעילות יהודית בינלאומית סייעה להביא לשחרורם והפכה את הפרשה לנקודת מפנה בהתארגנות הפוליטית היהודית המודרנית.","context":"המעצרים והעינויים מתועדים היטב; האשמת הרצח הפולחני הייתה עלילת דם כוזבת.","aftermath":"הפרשה עוררה התערבות יהודית ודיפלומטית בינלאומית וחיזקה רשתות של סולידריות יהודית חוצת גבולות.","sourceStatus":"המעצרים והעינויים מתועדים היטב; האשמת הרצח הפולחני הייתה כוזבת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1859-odessa-anti-jewish-riot-of-1859-101"]={"title":"המהומה האנטי־יהודית באודסה בשנת 1859","location":"אודסה, האימפריה הרוסית","story":"אלימות אנטי־יהודית פרצה באודסה סביב חג הפסחא. מלחים יוונים ויוונים מקומיים בלטו בין התוקפים. עוינות דתית השתלבה בתחרות כלכלית גוברת בנמל הים השחור.","context":"סמן זה מבחין בין ההקשר המקומי לבין פוגרומים מאוחרים יותר ואינו מניח שלכל מקרי האלימות היו אותם מבצעים או גורמים.","aftermath":"האלימות תרמה לשינוי עמדות יהודיות כלפי ביטחון, ארגון קהילתי ואמנציפציה.","sourceStatus":"מתועד היטב; חוקרים מדגישים מתחים יווניים־יהודיים מקומיים ותחרות כלכלית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1871-odessa-pogrom-of-1871-102"]={"title":"פוגרום אודסה של 1871","location":"אודסה, האימפריה הרוסית","story":"כמה ימים של אלימות אנטי־יהודית באודסה גרמו נזק לבתים ולעסקים יהודיים. יוונים השתתפו באופן בולט, וגם רוסים הצטרפו להתקפות. חוקרים רואים ב־1871 מבשר חשוב לעידן הפוגרומים הרחב שבא לאחר מכן.","context":"האירוע שילב מתחים דתיים, אתניים וכלכליים מקומיים ואינו זהה בהכרח לגלי הפוגרומים המאוחרים יותר.","aftermath":"האלימות תרמה להתארגנות, להגנה עצמית ולשינוי עמדות כלפי ביטחון ואמנציפציה.","sourceStatus":"מתועד היטב בדוחות רשמיים ובמחקר היסטורי; המניעים כללו מתחים דתיים, אתניים וכלכליים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1881-russian-empire-pogrom-wave-103"]={"title":"גל הפוגרומים באימפריה הרוסית","location":"האימפריה הרוסית","story":"לאחר רצח הצאר אלכסנדר השני שטף גל נרחב של מהומות אנטי־יהודיות אזורים בדרום ובמערב האימפריה הרוסית בשנים 1881–1884.","context":"האלימות התרחשה בתוך משבר פוליטי וחברתי רחב; מידת האחריות והתגובה של הרשויות השתנתה בין מקומות.","aftermath":"הפוגרומים תרמו להגירה יהודית המונית, להתארגנות פוליטית ולהתפתחות תנועות הגנה עצמית.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1882-may-laws-intensify-restrictions-on-russian-jews-104"]={"title":"חוקי מאי מחמירים את ההגבלות על יהודי רוסיה","location":"האימפריה הרוסית","story":"בעקבות גל הפוגרומים של 1881 הטילה הממשלה הקיסרית תקנות זמניות שנודעו כחוקי מאי, שהגבילו את המקומות שבהם יהודים רבים יכלו להתיישב ולעסוק במסחר. אלה היו צעדי מדינה מפלים ולא התקפה אלימה.","context":"סמן זה מפריד בין רדיפה משפטית של המדינה לבין אלימות פוגרומית ישירה.","aftermath":"ההגבלות העמיקו לחץ כלכלי וחברתי ותרמו להגירה ולשינוי פוליטי בקרב יהודי האימפריה.","sourceStatus":"החקיקה הקיסרית מתועדת בוודאות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1903-kishinev-pogrom-105"]={"title":"פוגרום קישינב","location":"קישינב, האימפריה הרוסית","story":"שלושה ימים של אלימות אנטי־יהודית הרגו קרוב לחמישים יהודים, פצעו מאות והביאו להרס או ביזה של מאות בתים ועסקים.","context":"הפוגרום עורר תשומת לב בינלאומית והמחיש את הסכנה של הסתה אנטישמית ותגובה שלטונית בלתי מספקת.","aftermath":"האירוע האיץ הגירה, פעילות פוליטית והקמת קבוצות הגנה עצמית יהודיות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1905-odessa-pogrom-106"]={"title":"פוגרום אודסה","location":"אודסה, האימפריה הרוסית","story":"במהלך המהפכה של 1905 חוותה אודסה אחד הפוגרומים הקטלניים של אותה שנה, עם הרג, פציעות והרס נרחבים.","context":"האלימות התרחשה בתוך אי־יציבות מהפכנית ופוליטית רחבה; אומדני הנפגעים משתנים.","aftermath":"הפוגרום העמיק את תחושת חוסר הביטחון והגביר הגירה, ארגון פוליטי והגנה עצמית.","sourceStatus":"רמת ודאות גבוהה; אומדני הנפגעים משתנים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1918-civil-war-pogroms-in-ukraine-and-neighboring-regions-107"]={"title":"פוגרומי מלחמת האזרחים באוקראינה ובאזורים סמוכים","location":"אוקראינה / בלארוס / גליציה","story":"במהלך מלחמות האזרחים שלאחר 1917 ביצעו כוחות ממספר מחנות פוליטיים וצבאיים פוגרומים שבהם נהרגו עשרות אלפי יהודים.","context":"האלימות בוצעה בידי כוחות שונים ולא ניתן לייחס אותה למחנה יחיד; האומדנים המצטברים משתנים במחקר.","aftermath":"הפוגרומים גרמו להרג המוני, עקירה וטראומה והאיצו שינויים פוליטיים והגירה בקרב יהודי האזור.","sourceStatus":"רמת ודאות גבוהה מאוד; האומדנים המצטברים משתנים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1819-hep-hep-riots-97"]={"title":"أعمال شغب هِب-هِب","location":"الولايات الألمانية","story":"بدأت أعمال شغب معادية لليهود في فورتسبورغ وانتشرت إلى عدة مدن ألمانية خلال نقاش حول تحرير اليهود مدنيًا. وهاجمت الحشود منازل ومتاجر وأفرادًا يهودًا وهي تردد الهتاف الذي أخذت منه الاضطرابات اسمها.","context":"وقعت الأحداث وسط توترات سياسية واقتصادية واجتماعية بشأن الوضع المدني لليهود.","aftermath":"زعزعت الاضطرابات أمن المجتمعات وأظهرت المعارضة الشعبية لتحرير اليهود في أجزاء من الولايات الألمانية.","sourceStatus":"موثق جيدًا في سجلات معاصرة؛ جمعت الدوافع بين التحامل المعادي لليهود والتوترات السياسية والاقتصادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1821-odessa-anti-jewish-riot-98"]={"title":"أعمال شغب معادية لليهود في أوديسا","location":"أوديسا، الإمبراطورية الروسية","story":"تُعرّف أعمال الشغب المعادية لليهود في أوديسا سنة 1821 أحيانًا بأنها من أوائل الحوادث التي سُمّيت لاحقًا بوغروم.","context":"كانت الحادثة محلية وينبغي تمييزها عن موجات البوغروم الأوسع في أواخر القرن التاسع عشر.","aftermath":"سبقت هذه الأعمال موجات لاحقة من البوغروم في أوديسا وعبر الإمبراطورية الروسية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1834-safed-looting-and-attacks-on-the-jewish-community-99"]={"title":"نهب وهجمات على المجتمع اليهودي في صفد","location":"صفد، فلسطين العثمانية","story":"خلال الاضطرابات الإقليمية المرتبطة بثورة 1834 في فلسطين تعرض المجتمع اليهودي في صفد للهجوم والنهب على نطاق واسع. وتضررت المنازل والمعابد واعتُدي على السكان وهُجروا.","context":"وقع الحدث ضمن تمرد إقليمي أوسع؛ تتفق المصادر على الهجمات والنهب لكنها تختلف في التفاصيل وأعداد الضحايا.","aftermath":"عانى المجتمع خسارة الممتلكات والإصابات والتهجير واضطر إلى إعادة البناء.","sourceStatus":"الهجمات والنهب موثقان؛ تختلف الروايات في التفاصيل وأعداد الضحايا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1840-damascus-affair-100"]={"title":"قضية دمشق","location":"دمشق، سوريا العثمانية","story":"بعد اختفاء راهب كاثوليكي وخادمه اتُهم أفراد من المجتمع اليهودي في دمشق زورًا بالقتل الطقسي. وسُجن عدد منهم وعُذب. وساعد التحرك اليهودي الدولي في إطلاق سراحهم وجعل القضية نقطة تحول في التنظيم السياسي اليهودي الحديث.","context":"الاعتقالات والتعذيب موثقان جيدًا؛ اتهام القتل الطقسي كان فرية دم كاذبة.","aftermath":"أثارت القضية تدخلًا يهوديًا ودبلوماسيًا دوليًا وعززت شبكات التضامن اليهودي عبر الحدود.","sourceStatus":"الاعتقالات والتعذيب موثقان جيدًا؛ اتهام القتل الطقسي كان كاذبًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1859-odessa-anti-jewish-riot-of-1859-101"]={"title":"أعمال الشغب المعادية لليهود في أوديسا سنة 1859","location":"أوديسا، الإمبراطورية الروسية","story":"اندلع عنف معادٍ لليهود في أوديسا حول عيد الفصح. وكان البحارة اليونانيون واليونانيون المحليون بارزين بين المهاجمين. وامتزج العداء الديني بالمنافسة الاقتصادية المتزايدة في ميناء البحر الأسود.","context":"يميز هذا المؤشر السياق المحلي عن البوغرومات اللاحقة ولا يفترض أن جميع أعمال العنف كان لها المنفذون أو الأسباب نفسها.","aftermath":"ساهم العنف في تغير المواقف اليهودية تجاه الأمن والتنظيم المجتمعي والتحرر المدني.","sourceStatus":"موثق جيدًا؛ يؤكد المؤرخون التوترات اليونانية اليهودية المحلية والمنافسة الاقتصادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1871-odessa-pogrom-of-1871-102"]={"title":"بوغروم أوديسا سنة 1871","location":"أوديسا، الإمبراطورية الروسية","story":"ألحقت عدة أيام من العنف المعادي لليهود في أوديسا أضرارًا بمنازل ومتاجر يهودية. وشارك اليونانيون بصورة بارزة، وانضم روس أيضًا إلى الهجمات. ويعد المؤرخون سنة 1871 مقدمة مهمة لعصر البوغرومات الأوسع الذي تلاها.","context":"جمعت الحادثة توترات دينية وعرقية واقتصادية محلية ولا تتطابق بالضرورة مع موجات البوغروم اللاحقة.","aftermath":"ساهم العنف في التنظيم والدفاع الذاتي وتغير المواقف تجاه الأمن والتحرر المدني.","sourceStatus":"موثق جيدًا في تقارير رسمية ودراسات تاريخية؛ شملت الدوافع توترات دينية وعرقية واقتصادية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1881-russian-empire-pogrom-wave-103"]={"title":"موجة البوغرومات في الإمبراطورية الروسية","location":"الإمبراطورية الروسية","story":"بعد اغتيال القيصر ألكسندر الثاني اجتاحت أعمال شغب واسعة معادية لليهود مناطق جنوبية وغربية من الإمبراطورية الروسية بين 1881 و1884.","context":"وقعت أعمال العنف وسط أزمة سياسية واجتماعية واسعة؛ واختلف دور السلطات واستجابتها بحسب المكان.","aftermath":"ساهمت البوغرومات في هجرة يهودية واسعة وتنظيم سياسي وتطور حركات الدفاع الذاتي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1882-may-laws-intensify-restrictions-on-russian-jews-104"]={"title":"قوانين مايو تشدد القيود على يهود روسيا","location":"الإمبراطورية الروسية","story":"في أعقاب موجة بوغرومات 1881 فرضت الحكومة الإمبراطورية لوائح مؤقتة عُرفت بقوانين مايو، قيدت الأماكن التي يستطيع كثير من اليهود السكن والعمل التجاري فيها. وكانت إجراءات دولة تمييزية لا هجومًا عنيفًا.","context":"يفصل هذا المؤشر بين الاضطهاد القانوني للدولة وبين عنف البوغروم المباشر.","aftermath":"عمقت القيود الضغط الاقتصادي والاجتماعي وساهمت في الهجرة والتغير السياسي بين يهود الإمبراطورية.","sourceStatus":"التشريع الإمبراطوري موثق بصورة مؤكدة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1903-kishinev-pogrom-105"]={"title":"بوغروم كيشيناو","location":"كيشيناو، الإمبراطورية الروسية","story":"قتلت ثلاثة أيام من العنف المعادي لليهود قرابة خمسين يهوديًا وجرحت المئات ودمرت أو نهبت مئات المنازل والمتاجر.","context":"جذب البوغروم اهتمامًا دوليًا وأظهر خطر التحريض المعادي للسامية والاستجابة الحكومية غير الكافية.","aftermath":"سرّعت الحادثة الهجرة والنشاط السياسي وتأسيس مجموعات الدفاع الذاتي اليهودية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1905-odessa-pogrom-106"]={"title":"بوغروم أوديسا","location":"أوديسا، الإمبراطورية الروسية","story":"خلال اضطرابات ثورة 1905 شهدت أوديسا أحد أكثر بوغرومات تلك السنة دموية، مع قتل وإصابات ودمار واسع.","context":"وقع العنف وسط عدم استقرار ثوري وسياسي واسع؛ وتختلف تقديرات الضحايا.","aftermath":"عمق البوغروم الشعور بانعدام الأمن وزاد الهجرة والتنظيم السياسي والدفاع الذاتي.","sourceStatus":"ثقة عالية؛ تقديرات الضحايا تختلف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1918-civil-war-pogroms-in-ukraine-and-neighboring-regions-107"]={"title":"بوغرومات الحرب الأهلية في أوكرانيا والمناطق المجاورة","location":"أوكرانيا / بيلاروس / غاليسيا","story":"خلال الحروب الأهلية التي أعقبت 1917 نفذت قوات من عدة معسكرات سياسية وعسكرية بوغرومات قتلت عشرات الآلاف من اليهود.","context":"نفذت أعمال العنف قوات مختلفة ولا يمكن نسبها إلى معسكر واحد؛ وتختلف التقديرات الإجمالية في الدراسات.","aftermath":"سببت البوغرومات قتلًا جماعيًا وتهجيرًا وصدمة وسرعت التحولات السياسية والهجرة بين يهود المنطقة.","sourceStatus":"ثقة عالية جدًا؛ التقديرات الإجمالية تختلف"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1920-nebi-musa-riots-108"]={"title":"מהומות נבי מוסא","location":"ירושלים","story":"אלימות במהלך חגיגות נבי מוסא כללה התקפות על הקהילה היהודית בירושלים על רקע החרפת המתחים הפוליטיים הערביים–יהודיים בתקופת המנדט הבריטי.","context":"האירוע היה חלק מן העימות הפוליטי והקהילתי המתפתח בארץ בתקופת המנדט.","aftermath":"המהומות העמיקו את חוסר האמון והובילו לשינויים בהתארגנות הביטחונית היהודית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1921-jaffa-riots-109"]={"title":"מהומות יפו","location":"יפו והסביבה","story":"אלימות ערבית–יהודית ביפו ובאזורים סמוכים גרמה להרוגים ולפצועים בשתי הקהילות והעמיקה את המתחים בתקופת המנדט.","context":"האלימות התרחשה בתוך מתחים לאומיים, פוליטיים וחברתיים גוברים בין ערבים ליהודים.","aftermath":"האירועים החריפו את ההפרדה והחששות הביטחוניים והובילו לתגובות מצד שלטונות המנדט.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1929-hebron-massacre-and-1929-palestine-riots-110"]={"title":"טבח חברון ומהומות תרפ״ט","location":"חברון וארץ ישראל המנדטורית","story":"במהלך אלימות נרחבת ב־1929 הרגו תוקפים ערבים 67 יהודים בחברון. יהודים הותקפו גם במקומות אחרים, בעוד ערבים נהרגו בעימותים ובידי כוחות בריטיים.","context":"הטבח בחברון היה חלק מגל אלימות רחב יותר, ולכן יש להבחין בין האירוע המקומי לבין כלל נפגעי מהומות 1929.","aftermath":"הקהילה היהודית העתיקה בחברון פונתה לאחר הטבח והאלימות העמיקה את הסכסוך בתקופת המנדט.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1929-safed-massacre-during-the-1929-riots-111"]={"title":"טבח צפת במהלך מהומות תרפ״ט","location":"צפת, ארץ ישראל המנדטורית","story":"במהלך מהומות 1929 תקפו ערבים תושבים יהודים בצפת, הרגו יהודים ושרפו ובזזו בתים יהודיים.","context":"זהו אירוע מזוהה בתוך גל האלימות הרחב של 1929, המיוצג גם באירועים אחרים בציר הזמן.","aftermath":"הקהילה היהודית בצפת ספגה הרוגים, פציעות ונזק לרכוש והמתחים באזור החריפו.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-nazi-seizure-of-power-begins-systematic-persecution-of-german-jews-112"]={"title":"עליית הנאצים לשלטון מתחילה רדיפה שיטתית של יהודי גרמניה","location":"גרמניה","story":"לאחר שאדולף היטלר נעשה קנצלר ב־30 בינואר 1933, המשטר הנאצי הפך במהירות אידאולוגיה אנטישמית למדיניות ממשלתית. יהודים סבלו מאיומים, תקיפות, הדרה ממוסדות ציבור ומערכת מתרחבת של חוקים מפלים.","context":"סמן זה עוקב אחר ההסלמה מאידאולוגיה אנטישמית למדיניות מדינה, הדרה משפטית, נישול כלכלי ואלימות גלויה יותר ויותר.","aftermath":"הצעדים בידדו, רוששו וסיכנו בהדרגה את הקהילות היהודיות וסייעו ליצור את המסגרת המוסדית לרדיפה הקיצונית ולרצח ההמוני שבאו בהמשך.","sourceStatus":"מתועד בהרחבה ברשומות גרמניות, בדיווחים בני התקופה ובארכיוני השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-nationwide-nazi-boycott-of-jewish-businesses-113"]={"title":"חרם נאצי ארצי על עסקים יהודיים","location":"גרמניה","story":"ב־1 באפריל 1933 ארגנה המפלגה הנאצית חרם ארצי על עסקים בבעלות יהודית ועל בעלי מקצוע יהודים. אנשי SA עמדו מחוץ לחנויות ולמשרדים כדי להפחיד לקוחות. אף שהחרם הרשמי נמשך יום אחד, הוא סימן תחילת מסע לאומי להוצאת יהודים מן החיים הכלכליים בגרמניה.","context":"החרם היה שלב מוקדם בהפיכת האנטישמיות למדיניות ממוסדת של הדרה כלכלית.","aftermath":"הצעדים הכלכליים נגד יהודים התרחבו בשנים הבאות והובילו לנישול שיטתי יותר.","sourceStatus":"מתועד בהרחבה; החרם אורגן בידי רשויות המפלגה הנאצית"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1933-civil-service-law-excludes-jews-from-government-employment-114"]={"title":"חוק שירות המדינה מדיר יהודים ממשרות ממשלתיות","location":"גרמניה","story":"החוק לשיקום שירות המדינה המקצועי מ־7 באפריל סילק יהודים רבים ומתנגדים פוליטיים ממשרות ממשלתיות. זה היה אחד הצעדים המשפטיים הגדולים הראשונים להדרה שיטתית של יהודים מן החיים הציבוריים בגרמניה.","context":"החקיקה ממחישה את המעבר המהיר מאפליה פוליטית לחוק מדינה מחייב.","aftermath":"ההדרה התרחבה בהמשך למקצועות ולמוסדות נוספים וסייעה לבודד את יהודי גרמניה.","sourceStatus":"החקיקה ויישומה מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1935-nuremberg-laws-strip-jews-of-rights-and-impose-racial-definitions-115"]={"title":"חוקי נירנברג שוללים זכויות מיהודים ומטילים הגדרות גזעיות","location":"נירנברג / גרמניה הנאצית","story":"חוקי נירנברג שללו מיהודי גרמניה אזרחות מלאה ואסרו נישואין ויחסי מין בין יהודים לבין מי שסווגו כבעלי דם גרמני או קרוב לו. הרשויות הנאציות הגדירו זהות יהודית לפי מוצא גזעי ולא לפי אמונה אישית.","context":"החוקים הפכו את האפליה הגזעית לעיקרון משפטי מרכזי של המדינה הנאצית.","aftermath":"הם העמיקו את בידוד היהודים והכשירו צעדי נישול, גירוש ורדיפה נוספים.","sourceStatus":"חקיקה נאצית ופרקטיקה מנהלית מתועדות בהרחבה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1936-1936-1939-arab-revolt-attacks-on-jewish-civilians-116"]={"title":"המרד הערבי 1936–1939: התקפות על אזרחים יהודים","location":"ארץ ישראל המנדטורית","story":"המרד הערבי נגד השלטון הבריטי וההגירה היהודית ההמונית כלל התקפות על אזרחים ויישובים יהודיים, לצד דיכוי בריטי ותגובות חמושות יהודיות.","context":"האירוע היה חלק ממרד רחב נגד הבריטים ומסכסוך לאומי מתעצם; אלימות בוצעה במסגרות שונות בידי כמה צדדים.","aftermath":"המרד שינה את מדיניות בריטניה, את ההתארגנות הצבאית היהודית ואת היחסים בין הקהילות לקראת סוף המנדט.","sourceStatus":"רמת ודאות גבוהה מאוד; אירועים בודדים דורשים מקורות נפרדים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1937-escalating-exclusion-and-aryanization-of-jewish-economic-life-117"]={"title":"החרפת ההדרה וה״אריזציה״ של החיים הכלכליים היהודיים","location":"גרמניה","story":"מ־1937 ועד 1939 אילצה המדיניות הנאצית יותר ויותר יהודים לצאת ממקצועות ומעסקים והעבירה רכוש בבעלות יהודית לבעלות לא־יהודית בתנאי כפייה. התהליך, שכונה אריזציה, רושש משפחות יהודיות ובודד אותן עוד יותר.","context":"הנישול הכלכלי היה חלק מן ההסלמה השיטתית של רדיפת יהודי גרמניה.","aftermath":"המדיניות צמצמה את יכולת הקיום הכלכלית של יהודים והגבירה את הלחץ להגר.","sourceStatus":"מתועד בהרחבה בצווים נאציים, ברשומות רכוש ובמחקר השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1938-kristallnacht-november-pogrom-118"]={"title":"ליל הבדולח / פוגרום נובמבר","location":"גרמניה ואוסטריה","story":"מנהיגי הנאצים שחררו גל אלימות אנטי־יהודית ארצי: בתי כנסת נשרפו, עסקים ובתים נהרסו, יהודים נרצחו וכ־26,000 גברים יהודים נכלאו במחנות ריכוז.","context":"הפוגרום סימן מעבר בולט מרדיפה משפטית וכלכלית לאלימות המונית מאורגנת בידי המשטר.","aftermath":"האירוע האיץ הגירה, נישול וכליאה והיה שלב מרכזי בדרך לרדיפה הקטלנית בזמן המלחמה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1939-german-invasion-of-poland-and-persecution-of-polish-jews-119"]={"title":"פלישת גרמניה לפולין ורדיפת יהודי פולין","location":"פולין הכבושה","story":"גרמניה פלשה לפולין ב־1 בספטמבר 1939. כוחות גרמניים ורשויות הכיבוש החלו מיד להשפיל יהודים, לכפות עבודת כפייה, לשדוד, לעקור ולהפעיל אלימות. האוכלוסייה היהודית הגדולה של פולין עברה תחת שלטון נאצי.","context":"זהו שלב מרכזי בכרונולוגיית השואה שבו הרדיפה הנאצית התרחבה עם הכיבוש למיליוני יהודים נוספים.","aftermath":"הכיבוש הוביל לריכוז יהודים, גטאות, גירושים ובהמשך לרצח המוני שיטתי.","sourceStatus":"מתועד בהרחבה ברשומות גרמניות, בעדויות ראייה ובארכיוני השואה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1940-nazi-ghettos-isolate-jewish-communities-in-occupied-poland-120"]={"title":"הגטאות הנאציים מבודדים קהילות יהודיות בפולין הכבושה","location":"פולין הכבושה בידי גרמניה","story":"הרשויות הגרמניות אילצו יהודים לעבור לרבעים עירוניים סגורים או מוגבלים שנודעו כגטאות. גטאות כמו לודז' וורשה סבלו מצפיפות קיצונית, רעב, מחלות ועבודת כפייה, ובהמשך שימשו נקודות ריכוז לגירוש למרכזי הרג.","context":"הגטאות היו חלק ממערכת רדיפה שהתקדמה מבידוד וניצול אל גירוש ורצח המוני.","aftermath":"מאות אלפים מתו מתנאי החיים או גורשו בהמשך למרכזי הרג.","sourceStatus":"מתועד בהרחבה ברשומות מנהל גרמניות, תצלומים, יומנים ועדויות ניצולים"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1920-nebi-musa-riots-108"]={"title":"اضطرابات النبي موسى","location":"القدس","story":"شمل العنف خلال موسم النبي موسى هجمات على المجتمع اليهودي في القدس وسط تصاعد التوتر السياسي العربي اليهودي في عهد الانتداب البريطاني.","context":"كانت الحادثة جزءًا من الصراع السياسي والمجتمعي المتنامي في فلسطين خلال الانتداب.","aftermath":"عمقت الاضطرابات انعدام الثقة وأدت إلى تغييرات في التنظيم الأمني اليهودي.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1921-jaffa-riots-109"]={"title":"اضطرابات يافا","location":"يافا والمنطقة المحيطة","story":"أدى العنف العربي اليهودي في يافا والمناطق المجاورة إلى قتلى وجرحى من المجتمعين وعمق توترات عهد الانتداب.","context":"وقع العنف وسط تصاعد التوترات القومية والسياسية والاجتماعية بين العرب واليهود.","aftermath":"فاقمت الأحداث الانقسام والمخاوف الأمنية وأدت إلى ردود من سلطات الانتداب.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1929-hebron-massacre-and-1929-palestine-riots-110"]={"title":"مذبحة الخليل واضطرابات فلسطين سنة 1929","location":"الخليل وفلسطين الانتدابية","story":"خلال أعمال العنف الواسعة سنة 1929 قتل مهاجمون عرب 67 يهوديًا في الخليل. كما تعرض يهود لهجمات في أماكن أخرى، بينما قُتل عرب في اشتباكات وعلى يد القوات البريطانية.","context":"كانت مذبحة الخليل جزءًا من موجة عنف أوسع، ولذلك ينبغي التمييز بين الحادثة المحلية ومجمل ضحايا اضطرابات 1929.","aftermath":"أُخلي المجتمع اليهودي القديم في الخليل بعد المذبحة وعمق العنف الصراع في عهد الانتداب.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1929-safed-massacre-during-the-1929-riots-111"]={"title":"مذبحة صفد خلال اضطرابات 1929","location":"صفد، فلسطين الانتدابية","story":"خلال اضطرابات 1929 هاجم عرب سكانًا يهودًا في صفد وقتلوا يهودًا وأحرقوا ونهبوا منازل يهودية.","context":"هذه حادثة محددة داخل موجة العنف الأوسع لسنة 1929 والممثلة أيضًا في أحداث أخرى في الخط الزمني.","aftermath":"تكبد المجتمع اليهودي في صفد قتلى وإصابات وأضرارًا بالممتلكات وتصاعد التوتر في المنطقة.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-nazi-seizure-of-power-begins-systematic-persecution-of-german-jews-112"]={"title":"استيلاء النازيين على السلطة يبدأ الاضطهاد المنهجي ليهود ألمانيا","location":"ألمانيا","story":"بعد أن أصبح أدولف هتلر مستشارًا في 30 يناير 1933 حوّل النظام النازي الأيديولوجيا المعادية للسامية بسرعة إلى سياسة حكومية. وواجه اليهود الترهيب والاعتداء والاستبعاد من المؤسسات العامة ونظامًا متوسعًا من القوانين التمييزية.","context":"يتتبع هذا المؤشر التصعيد من الأيديولوجيا المعادية للسامية إلى سياسة الدولة والإقصاء القانوني ونزع الملكية الاقتصادية والعنف المتزايد.","aftermath":"عزلت هذه الإجراءات المجتمعات اليهودية وأفقرتها وعرضتها للخطر تدريجيًا وساعدت في إنشاء الإطار المؤسسي للاضطهاد الأشد والقتل الجماعي لاحقًا.","sourceStatus":"موثق على نطاق واسع في السجلات الألمانية والتقارير المعاصرة وأرشيفات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-nationwide-nazi-boycott-of-jewish-businesses-113"]={"title":"مقاطعة نازية وطنية للأعمال اليهودية","location":"ألمانيا","story":"في 1 أبريل 1933 نظم الحزب النازي مقاطعة وطنية للمتاجر المملوكة لليهود وللمهنيين اليهود. ووقف أفراد قوات العاصفة خارج المتاجر والمكاتب لترهيب الزبائن. ورغم أن المقاطعة الرسمية استمرت يومًا واحدًا، فإنها دشنت حملة وطنية لإخراج اليهود من الحياة الاقتصادية الألمانية.","context":"كانت المقاطعة مرحلة مبكرة في تحويل معاداة السامية إلى سياسة مؤسسية للإقصاء الاقتصادي.","aftermath":"توسعت الإجراءات الاقتصادية ضد اليهود في السنوات التالية وأدت إلى نزع ملكية أكثر منهجية.","sourceStatus":"موثق على نطاق واسع؛ نظمت سلطات الحزب النازي المقاطعة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1933-civil-service-law-excludes-jews-from-government-employment-114"]={"title":"قانون الخدمة المدنية يستبعد اليهود من الوظائف الحكومية","location":"ألمانيا","story":"أزال قانون استعادة الخدمة المدنية المهنية الصادر في 7 أبريل كثيرًا من اليهود والمعارضين السياسيين من الوظائف الحكومية. وكان من أوائل الخطوات القانونية الكبرى للإقصاء المنهجي لليهود من الحياة العامة الألمانية.","context":"يوضح التشريع الانتقال السريع من التمييز السياسي إلى قانون دولة ملزم.","aftermath":"امتد الإقصاء لاحقًا إلى مهن ومؤسسات أخرى وساعد في عزل يهود ألمانيا.","sourceStatus":"التشريع وتطبيقه موثقان مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1935-nuremberg-laws-strip-jews-of-rights-and-impose-racial-definitions-115"]={"title":"قوانين نورمبرغ تسلب اليهود حقوقهم وتفرض تعريفات عرقية","location":"نورمبرغ / ألمانيا النازية","story":"حرمت قوانين نورمبرغ يهود ألمانيا من المواطنة الكاملة وحظرت الزواج والعلاقات الجنسية بين اليهود ومن صُنّفوا من الدم الألماني أو القريب منه. وحددت السلطات النازية الهوية اليهودية وفق الأصل العرقي لا الاعتقاد الديني الشخصي.","context":"حولت القوانين التمييز العرقي إلى مبدأ قانوني مركزي للدولة النازية.","aftermath":"عمقت عزلة اليهود ومهدت لمزيد من نزع الملكية والطرد والاضطهاد.","sourceStatus":"تشريعات نازية وممارسة إدارية موثقة على نطاق واسع"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1936-1936-1939-arab-revolt-attacks-on-jewish-civilians-116"]={"title":"الثورة العربية 1936–1939: هجمات على المدنيين اليهود","location":"فلسطين الانتدابية","story":"شملت الثورة العربية ضد الحكم البريطاني والهجرة اليهودية الواسعة هجمات على مدنيين ومجتمعات يهودية، إلى جانب مكافحة التمرد البريطانية وردود مسلحة يهودية.","context":"كانت الحادثة جزءًا من تمرد واسع ضد البريطانيين ومن صراع قومي متصاعد؛ ووقع العنف في سياقات مختلفة ومن عدة أطراف.","aftermath":"غيرت الثورة السياسة البريطانية والتنظيم العسكري اليهودي والعلاقات بين المجتمعات قبيل نهاية الانتداب.","sourceStatus":"ثقة عالية جدًا؛ الحوادث الفردية تحتاج مصادر منفصلة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1937-escalating-exclusion-and-aryanization-of-jewish-economic-life-117"]={"title":"تصاعد إقصاء و«أرينة» الحياة الاقتصادية اليهودية","location":"ألمانيا","story":"من 1937 إلى 1939 أجبرت السياسة النازية اليهود بصورة متزايدة على الخروج من المهن والأعمال ونقلت الممتلكات اليهودية إلى ملكية غير يهودية بشروط قسرية. وأفقرت هذه العملية، المعروفة بالأرينة، الأسر اليهودية وعزلتها أكثر عن المجتمع الألماني.","context":"كان نزع الملكية الاقتصادية جزءًا من التصعيد المنهجي لاضطهاد يهود ألمانيا.","aftermath":"قلصت السياسة قدرة اليهود على البقاء اقتصاديًا وزادت الضغط للهجرة.","sourceStatus":"موثق على نطاق واسع بالمراسيم النازية وسجلات الملكية ودراسات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1938-kristallnacht-november-pogrom-118"]={"title":"ليلة الكريستال / بوغروم نوفمبر","location":"ألمانيا والنمسا","story":"أطلق قادة النازيين عنفًا وطنيًا ضد اليهود: أُحرقت المعابد ودُمرت المتاجر والمنازل وقُتل يهود وسُجن نحو 26 ألف رجل يهودي في معسكرات الاعتقال.","context":"مثل البوغروم انتقالًا بارزًا من الاضطهاد القانوني والاقتصادي إلى عنف جماعي منظم من النظام.","aftermath":"سرّع الحدث الهجرة ونزع الملكية والسجن وكان مرحلة رئيسية نحو الاضطهاد القاتل في زمن الحرب.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1939-german-invasion-of-poland-and-persecution-of-polish-jews-119"]={"title":"الغزو الألماني لبولندا واضطهاد يهود بولندا","location":"بولندا المحتلة","story":"غزت ألمانيا بولندا في 1 سبتمبر 1939. وبدأت القوات الألمانية وسلطات الاحتلال فورًا بإذلال اليهود وفرض العمل القسري والسرقة والتهجير والعنف. وخضع العدد الكبير من يهود بولندا للحكم النازي.","context":"كانت هذه مرحلة مركزية في تسلسل الهولوكوست، إذ وسع الاحتلال الاضطهاد النازي ليشمل ملايين اليهود الآخرين.","aftermath":"أدى الاحتلال إلى تجميع اليهود في الغيتوات والترحيل ثم القتل الجماعي المنهجي.","sourceStatus":"موثق على نطاق واسع في السجلات الألمانية وشهادات العيان وأرشيفات الهولوكوست"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1940-nazi-ghettos-isolate-jewish-communities-in-occupied-poland-120"]={"title":"الغيتوات النازية تعزل المجتمعات اليهودية في بولندا المحتلة","location":"بولندا المحتلة ألمانيًا","story":"أجبرت السلطات الألمانية اليهود على الانتقال إلى أحياء حضرية مغلقة أو مقيدة عُرفت بالغيتوات. وعانت غيتوات مثل لودج ووارسو من اكتظاظ شديد وجوع ومرض وعمل قسري، ثم استُخدمت نقاط تجميع للترحيل إلى مراكز القتل.","context":"كانت الغيتوات جزءًا من نظام اضطهاد تقدم من العزل والاستغلال إلى الترحيل والقتل الجماعي.","aftermath":"مات مئات الآلاف من ظروف الحياة أو رُحلوا لاحقًا إلى مراكز القتل.","sourceStatus":"موثق على نطاق واسع في السجلات الإدارية الألمانية والصور واليوميات وشهادات الناجين"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-farhud-121"]={"title":"הפרהוד","location":"בגדאד, עיראק","story":"ב־1–2 ביוני 1941 פרצה בבגדאד אלימות אנטי־יהודית שכללה הרג ופציעת יהודים, ביזה והרס נרחבים.","context":"הפרהוד התרחש בתוך משבר פוליטי בעיראק בזמן מלחמת העולם השנייה, לאחר קריסת המשטר הפרו־צירי של רשיד עלי.","aftermath":"האירוע ערער עמוקות את תחושת הביטחון של יהודי עיראק ונעשה נקודת ציון בזיכרון הקהילה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-ia-i-pogrom-122"]={"title":"פוגרום יאשי","location":"יאשי, רומניה","story":"רשויות ויחידות צבא רומניות, בסיוע חיילים גרמנים בחלק מן המקרים, רצחו לפחות 8,000 יהודים במהלך פוגרום יוני 1941 וברכבות המוות הקשורות אליו.","context":"האירוע היה חלק מרדיפת ורצח יהודי רומניה בתקופת השואה ובוצע במעורבות מרכזית של הרשויות הרומניות.","aftermath":"אלפי יהודים נרצחו והקהילה נפגעה באופן קטסטרופלי.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-lviv-pogrom-123"]={"title":"פוגרום לבוב","location":"לבוב, אוקראינה הכבושה בידי גרמניה","story":"לאחר הכיבוש הגרמני של לבוב השתתפו כוחות גרמניים, פעילים לאומנים אוקראינים, אנשי מיליציה ואזרחים מקומיים בהשפלה, הכאה ורצח של יהודים.","context":"האירוע התרחש בימים הראשונים של הכיבוש הגרמני ובתוך הסלמה מהירה של אלימות אנטי־יהודית.","aftermath":"הפוגרום היה חלק מתחילת ההשמדה ההמונית של יהודי האזור תחת הכיבוש הנאצי.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-jedwabne-massacre-124"]={"title":"טבח ידוובנה","location":"ידוובנה, פולין הכבושה בידי גרמניה","story":"מאות מתושבי ידוובנה היהודים נרצחו ביולי 1941 בידי שכנים פולנים בנוכחות משטרה גרמנית; שאלות על מידת היוזמה וההכוונה הגרמנית ממשיכות להיחקר.","context":"האחריות הישירה של מבצעים מקומיים מתועדת, לצד נוכחות ושליטה גרמנית באזור; היבטים של היוזמה הגרמנית נותרו נושא למחקר.","aftermath":"הקהילה היהודית המקומית הושמדה כמעט לחלוטין.","sourceStatus":"רמת ודאות גבוהה מאוד; היבטים מסוימים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-ponary-mass-killings-begin-125"]={"title":"תחילת הרציחות ההמוניות בפונאר","location":"ליד וילנה, ליטא","story":"יחידות אס־אס ומשטרה גרמניות, בסיוע משתפי פעולה ליטאים, רצחו בפונאר יהודים מווילנה ומהסביבה. בסופו של דבר נרצחו באתר עשרות אלפי יהודים.","context":"פונאר היה אתר מרכזי של רצח בירי בתקופת השואה במזרח אירופה.","aftermath":"הרציחות השמידו חלק גדול מן האוכלוסייה היהודית של וילנה והאזור.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-che-mno-killing-center-begins-mass-murder-126"]={"title":"מרכז ההרג חלמנו מתחיל ברצח המוני","location":"חלמנו, פולין הכבושה בידי גרמניה","story":"הרצח ההמוני בחלמנו החל בדצמבר 1941 באמצעות משאיות גז. גרמניה הנאצית רצחה שם לפחות 152,000 יהודים.","context":"חלמנו היה מרכז ההרג הנאצי הראשון שבו נעשה שימוש שיטתי בגז לצורך רצח המוני.","aftermath":"המרכז שימש להשמדת קהילות יהודיות, במיוחד מאזור ורטגאו וגטו לודז'.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-holocaust-mass-shootings-and-extermination-127"]={"title":"השואה: ירי המוני והשמדה","location":"אירופה הכבושה בידי גרמניה","story":"גרמניה הנאצית ובעלות בריתה ומשתפי הפעולה עמה רצחו באופן שיטתי כשישה מיליון יהודים אירופים באמצעות ירי, מרכזי הרג, גטאות, הרעבה, עבודת כפייה ושיטות נוספות.","context":"זהו אירוע־על בציר הזמן; אירועים נפרדים מתעדים אתרי הרג, גירושים, פוגרומים ומעשי התנגדות ספציפיים.","aftermath":"השואה החריבה קהילות יהודיות ברחבי אירופה והותירה השלכות דמוגרפיות, פוליטיות ותרבותיות עמוקות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-rumbula-massacre-128"]={"title":"טבח רומבולה","location":"ליד ריגה, לטביה הכבושה בידי גרמניה","story":"אנשי אס־אס ומשטרה גרמנים וכוחות עזר לטביים רצחו בסוף 1941 כ־25,000 יהודים מגטו ריגה וכ־1,000 יהודים מגרמניה ביער רומבולה.","context":"הטבח היה אחד ממבצעי הירי ההמוני הגדולים בשואה לפני התרחבות מרכזי ההרג.","aftermath":"רוב תושבי גטו ריגה שנכללו באקציה נרצחו בתוך ימים ספורים.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-babi-yar-massacre-129"]={"title":"טבח באבי יאר","location":"קייב, אוקראינה הכבושה בידי גרמניה","story":"ב־29–30 בספטמבר 1941 רצחו אנשי איינזצגרופה C ומשתפי פעולה 33,771 גברים, נשים וילדים יהודים בגיא באבי יאר.","context":"הרצח התרחש לאחר כיבוש קייב והיה דוגמה מרכזית לשיטת ההשמדה בירי המוני.","aftermath":"האתר המשיך לשמש את הנאצים לרצח קבוצות נוספות במהלך הכיבוש.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-operation-barbarossa-and-einsatzgruppen-mass-shootings-130"]={"title":"מבצע ברברוסה והירי ההמוני של האיינזצגרופן","location":"השטחים הסובייטיים הכבושים בידי גרמניה","story":"לאחר פלישת גרמניה לברית המועצות ביוני 1941 ביצעו יחידות הרג ניידות, בסיוע כוחות גרמניים נוספים וכוחות עזר מקומיים במקומות שונים, ירי המוני ביהודים ובקבוצות יעד אחרות. קהילות יהודיות שלמות נרצחו סמוך לבתיהן.","context":"הפלישה סימנה הסלמה מכרעת מרדיפה וגטאות לרצח המוני שיטתי בשטחי ברית המועצות הכבושים.","aftermath":"הירי ההמוני רצח מאות אלפי יהודים והיה מרכיב מרכזי בהתפתחות השואה.","sourceStatus":"מתועד בהרחבה בדוחות מבצעיים גרמניים, רשומות מלחמה, קברי אחים ועדויות ניצולים ועדים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-kamianets-podilskyi-massacre-131"]={"title":"טבח קמניץ־פודולסקי","location":"קמניץ־פודולסקי, אוקראינה הסובייטית הכבושה","story":"בסוף אוגוסט 1941 רצחו כוחות אס־אס ומשטרה גרמניים, בסיוע כוחות תחת פיקוד גרמני, עשרות אלפי יהודים ליד קמניץ־פודולסקי. רבים מן הקורבנות גורשו קודם משטח בשליטה הונגרית; גם יהודים אוקראינים מקומיים נרצחו.","context":"הטבח היה אחד ממבצעי הרצח ההמוני הגדולים הראשונים לאחר מבצע ברברוסה.","aftermath":"האירוע הדגים את המעבר המהיר לרצח המוני של אוכלוסיות יהודיות שלמות.","sourceStatus":"מתועד בהרחבה; כ־23,600 יהודים דווחו כנרצחים באקציה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1941-odessa-massacre-under-romanian-occupation-132"]={"title":"טבח אודסה תחת הכיבוש הרומני","location":"אודסה והאזור הסובב, אוקראינה הכבושה","story":"לאחר שכוחות רומניים וגרמניים כבשו את אודסה ביצעו הרשויות הרומניות פעולות תגמול המוניות נגד יהודים בעקבות פיצוץ במטה הצבאי הרומני. יהודים נורו, נתלו, נשרפו במבנים וגורשו לאתרי הרג ולמחנות בטרנסניסטריה שבשליטת רומניה.","context":"האירוע היה חלק מרדיפת ורצח היהודים תחת הממשל הרומני באזור.","aftermath":"הרציחות והגירושים השמידו חלק ניכר מן הקהילה היהודית המקומית.","sourceStatus":"התפקיד הרומני והרצח ההמוני מתועדים בהרחבה; מספרי הנפגעים משתנים לפי התחום הגאוגרפי והכרונולוגי הנכלל"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-farhud-121"]={"title":"الفرهود","location":"بغداد، العراق","story":"في 1–2 يونيو 1941 اندلع عنف معادٍ لليهود في بغداد أدى إلى قتل وجرح يهود ونهب ودمار واسع.","context":"وقع الفرهود وسط أزمة سياسية عراقية خلال الحرب العالمية الثانية بعد انهيار نظام رشيد عالي الموالي للمحور.","aftermath":"زعزع الحدث بشدة شعور يهود العراق بالأمان وأصبح محطة مركزية في ذاكرة المجتمع.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-ia-i-pogrom-122"]={"title":"بوغروم ياش","location":"ياش، رومانيا","story":"قتلت السلطات والوحدات العسكرية الرومانية، بمساعدة جنود ألمان في بعض الحالات، ما لا يقل عن 8,000 يهودي خلال بوغروم يونيو 1941 وقطارات الموت المرتبطة به.","context":"كان الحدث جزءًا من اضطهاد وقتل يهود رومانيا في الهولوكوست ونُفذ بمشاركة مركزية من السلطات الرومانية.","aftermath":"قُتل آلاف اليهود وتعرض المجتمع لكارثة واسعة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-lviv-pogrom-123"]={"title":"بوغروم لفيف","location":"لفيف، أوكرانيا المحتلة ألمانيًا","story":"بعد الاحتلال الألماني للمدينة شاركت قوات ألمانية ونشطاء قوميون أوكرانيون وأفراد ميليشيا ومدنيون محليون في إذلال اليهود وضربهم وقتلهم.","context":"وقع الحدث في الأيام الأولى للاحتلال الألماني وسط تصاعد سريع للعنف المعادي لليهود.","aftermath":"كان البوغروم جزءًا من بداية الإبادة الجماعية ليهود المنطقة تحت الاحتلال النازي.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-jedwabne-massacre-124"]={"title":"مذبحة يدفابنه","location":"يدفابنه، بولندا المحتلة ألمانيًا","story":"قُتل مئات السكان اليهود في يدفابنه في يوليو 1941 على يد جيران بولنديين بحضور الشرطة الألمانية؛ وما زالت جوانب التحريض والتوجيه الألماني موضع بحث تاريخي.","context":"المسؤولية المباشرة للمنفذين المحليين موثقة إلى جانب الوجود والسيطرة الألمانية في المنطقة؛ بعض جوانب المبادرة الألمانية ما تزال موضع بحث.","aftermath":"دُمر المجتمع اليهودي المحلي تقريبًا بالكامل.","sourceStatus":"ثقة عالية جدًا؛ بعض الجوانب موضع نقاش"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-ponary-mass-killings-begin-125"]={"title":"بدء القتل الجماعي في بوناري","location":"قرب فيلنا، ليتوانيا","story":"قتلت وحدات الإس إس والشرطة الألمانية بمساعدة متعاونين ليتوانيين يهودًا من فيلنا والمناطق المحيطة في بوناري. وفي النهاية قُتل في الموقع عشرات الآلاف من اليهود.","context":"كان بوناري موقعًا رئيسيًا للقتل بالرصاص خلال الهولوكوست في شرق أوروبا.","aftermath":"أدت عمليات القتل إلى إبادة جزء كبير من السكان اليهود في فيلنا والمنطقة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-che-mno-killing-center-begins-mass-murder-126"]={"title":"مركز خيلمنو للقتل يبدأ القتل الجماعي","location":"خيلمنو، بولندا المحتلة ألمانيًا","story":"بدأ القتل الجماعي في خيلمنو في ديسمبر 1941 باستخدام شاحنات الغاز. وقتلت ألمانيا النازية هناك ما لا يقل عن 152 ألف يهودي.","context":"كان خيلمنو أول مركز قتل نازي استُخدم فيه الغاز بصورة منهجية للقتل الجماعي.","aftermath":"استُخدم المركز لإبادة مجتمعات يهودية، خاصة من منطقة فارتغاو وغيتو لودج.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-holocaust-mass-shootings-and-extermination-127"]={"title":"الهولوكوست: إطلاق النار الجماعي والإبادة","location":"أوروبا المحتلة ألمانيًا","story":"قتلت ألمانيا النازية وحلفاؤها والمتعاونون معها بصورة منهجية نحو ستة ملايين يهودي أوروبي عبر إطلاق النار ومراكز القتل والغيتوات والتجويع والعمل القسري ووسائل أخرى.","context":"هذا حدث شامل في الخط الزمني؛ وتوثق أحداث منفصلة مواقع قتل وترحيل وبوغرومات وأعمال مقاومة محددة.","aftermath":"دمر الهولوكوست المجتمعات اليهودية في أنحاء أوروبا وترك آثارًا ديموغرافية وسياسية وثقافية عميقة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-rumbula-massacre-128"]={"title":"مذبحة رومبولا","location":"قرب ريغا، لاتفيا المحتلة ألمانيًا","story":"قتل أفراد الإس إس والشرطة الألمان وقوات مساعدة لاتفية نحو 25 ألف يهودي من غيتو ريغا ونحو ألف يهودي ألماني في غابة رومبولا أواخر 1941.","context":"كانت المذبحة من أكبر عمليات القتل الجماعي بالرصاص في الهولوكوست قبل توسع مراكز القتل.","aftermath":"قُتل معظم سكان غيتو ريغا المستهدفين خلال أيام قليلة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-babi-yar-massacre-129"]={"title":"مذبحة بابي يار","location":"كييف، أوكرانيا المحتلة ألمانيًا","story":"في 29–30 سبتمبر 1941 قتل أفراد أينزاتسغروبه C ومتعاونون 33,771 رجلًا وامرأة وطفلًا يهوديًا في وادي بابي يار.","context":"وقع القتل بعد احتلال كييف وكان مثالًا رئيسيًا على الإبادة بإطلاق النار الجماعي.","aftermath":"واصل النازيون استخدام الموقع لقتل جماعات أخرى خلال الاحتلال.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-operation-barbarossa-and-einsatzgruppen-mass-shootings-130"]={"title":"عملية بارباروسا وإطلاق النار الجماعي للأينزاتسغروبن","location":"الأراضي السوفيتية المحتلة ألمانيًا","story":"بعد غزو ألمانيا للاتحاد السوفيتي في يونيو 1941 نفذت وحدات قتل متنقلة، بدعم قوات ألمانية أخرى ومساعدين محليين في مواقع مختلفة، عمليات إطلاق نار جماعي ضد اليهود وجماعات مستهدفة أخرى. وقُتلت مجتمعات يهودية كاملة قرب منازلها.","context":"مثل الغزو تصعيدًا حاسمًا من الاضطهاد والغيتوات إلى القتل الجماعي المنهجي في الأراضي السوفيتية المحتلة.","aftermath":"قتلت عمليات إطلاق النار مئات الآلاف من اليهود وكانت عنصرًا مركزيًا في تطور الهولوكوست.","sourceStatus":"موثق على نطاق واسع بالتقارير العملياتية الألمانية وسجلات الحرب والمقابر الجماعية وشهادات الناجين والشهود"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-kamianets-podilskyi-massacre-131"]={"title":"مذبحة كاميانيتس بوديلسكي","location":"كاميانيتس بوديلسكي، أوكرانيا السوفيتية المحتلة","story":"في أواخر أغسطس 1941 قتلت قوات الإس إس والشرطة الألمانية، بمشاركة قوات تحت القيادة الألمانية، عشرات الآلاف من اليهود قرب كاميانيتس بوديلسكي. وكان كثير من الضحايا قد رُحلوا من أراضٍ خاضعة للسيطرة المجرية، كما قُتل يهود أوكرانيون محليون.","context":"كانت المذبحة من أوائل عمليات القتل الجماعي الكبرى بعد عملية بارباروسا.","aftermath":"أظهر الحدث الانتقال السريع إلى قتل جماعي لمجتمعات يهودية كاملة.","sourceStatus":"موثق على نطاق واسع؛ أُبلغ عن مقتل نحو 23,600 يهودي في العملية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1941-odessa-massacre-under-romanian-occupation-132"]={"title":"مذبحة أوديسا تحت الاحتلال الروماني","location":"أوديسا والمنطقة المحيطة، أوكرانيا المحتلة","story":"بعد استيلاء القوات الرومانية والألمانية على أوديسا نفذت السلطات الرومانية أعمال انتقام جماعية ضد اليهود إثر انفجار في مقر عسكري روماني. وأُطلق النار على اليهود وشُنقوا وأُحرقوا في مبانٍ ورُحلوا إلى مواقع قتل ومعسكرات في ترانسنيستريا الخاضعة لرومانيا.","context":"كان الحدث جزءًا من اضطهاد وقتل اليهود تحت الإدارة الرومانية في المنطقة.","aftermath":"دمرت عمليات القتل والترحيل جزءًا كبيرًا من المجتمع اليهودي المحلي.","sourceStatus":"الدور الروماني والقتل الجماعي موثقان على نطاق واسع؛ تختلف أعداد الضحايا بحسب النطاق الجغرافي والزمني المحتسب"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-belzec-killing-center-133"]={"title":"מרכז ההרג בלז'ץ","location":"בלז'ץ, פולין הכבושה בידי גרמניה","story":"בלז'ץ הפך למרכז הרג במסגרת מבצע ריינהרד. כ־435,000 יהודים נרצחו בו, רובם המכריע בתאי גזים.","context":"בלז'ץ היה אחד משלושת מרכזי ההרג המרכזיים של מבצע ריינהרד להשמדת יהודי הגנרלגוברנמן.","aftermath":"כמעט כל המגורשים שנשלחו לבלז'ץ נרצחו, והמחנה פורק לאחר סיום פעולות ההרג העיקריות.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-sobibor-killing-center-134"]={"title":"מרכז ההרג סוביבור","location":"סוביבור, פולין הכבושה בידי גרמניה","story":"סוביבור הוקם כמרכז הרג במסגרת מבצע ריינהרד. לפחות 167,000 יהודים נרצחו בו.","context":"המחנה נועד בעיקר לרצח המוני של יהודים שגורשו מאזורים שונים באירופה הכבושה.","aftermath":"לאחר מרד האסירים ב־1943 פירקו הגרמנים את המחנה וניסו לטשטש את עקבותיו.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-treblinka-ii-killing-center-135"]={"title":"מרכז ההרג טרבלינקה II","location":"טרבלינקה, פולין הכבושה בידי גרמניה","story":"טרבלינקה II פעל כמרכז הרג במסגרת מבצע ריינהרד. אנשי המשטר הנאצי רצחו בו לפי ההערכות כ־925,000 יהודים.","context":"טרבלינקה היה אחד מאתרי הרצח ההמוני הקטלניים ביותר של השואה.","aftermath":"לאחר מרד אסירים ב־1943 פורק האתר ונעשו ניסיונות להסוות את תפקידו.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-auschwitz-birkenau-mass-murder-of-jews-136"]={"title":"הרצח ההמוני של יהודים באושוויץ־בירקנאו","location":"אושוויץ־בירקנאו, פולין הכבושה בידי גרמניה","story":"אושוויץ־בירקנאו נעשה מתחם הריכוז וההרג הגדול ביותר של גרמניה הנאצית. כמיליון יהודים נרצחו במתחם אושוויץ.","context":"האתר שילב מחנה ריכוז, עבודת כפייה ומערכת רצח המוני, בעיקר באמצעות תאי גזים.","aftermath":"אושוויץ נעשה אחד הסמלים המרכזיים של השואה ושל רצח יהודי אירופה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-great-action-deportation-of-warsaw-jews-to-treblinka-137"]={"title":"האקציה הגדולה: גירוש יהודי ורשה לטרבלינקה","location":"ורשה, פולין הכבושה בידי גרמניה","story":"מיולי עד ספטמבר 1942 גירשו הרשויות הגרמניות כ־265,000 יהודים מגטו ורשה לטרבלינקה ורצחו כ־35,000 יהודים בגטו במהלך המבצע.","context":"הגירוש היה חלק ממבצע ריינהרד ומחיסול הקהילות היהודיות בפולין הכבושה.","aftermath":"רוב אוכלוסיית הגטו גורשה ונרצחה; הנותרים התארגנו בהמשך להתנגדות חמושה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1942-operation-reinhard-138"]={"title":"מבצע ריינהרד","location":"פולין הכבושה בידי גרמניה","story":"מבצע ריינהרד היה התוכנית הנאצית לרצח יהודי הגנרלגוברנמן בפולין הכבושה. מרכזי ההרג העיקריים היו בלז'ץ, סוביבור וטרבלינקה, לצד גירושים וירי המוני.","context":"האירוע הוא מסגרת־על; מרכזי ההרג והגירושים המרכזיים מיוצגים גם כאירועים נפרדים בציר הזמן.","aftermath":"המבצע השמיד את רוב הקהילות היהודיות באזור והיה מרכיב מרכזי בפתרון הסופי.","sourceStatus":"מתועד בהרחבה; סמנים נפרדים מספקים אומדני קורבנות ספציפיים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-warsaw-ghetto-uprising-139"]={"title":"מרד גטו ורשה","location":"ורשה, פולין הכבושה בידי גרמניה","story":"לוחמים יהודים התנגדו למבצע הגירוש הגרמני הסופי שהחל ב־19 באפריל 1943. לפחות 7,000 יהודים מתו בלחימה או במקומות מסתור בזמן שהכוחות הגרמניים החריבו את הגטו.","context":"המרד היה פעולת התנגדות יהודית מזוינת נגד חיסול הגטו וגירוש תושביו.","aftermath":"המרד דוכא והגטו נהרס, אך הוא נעשה סמל מרכזי להתנגדות יהודית בשואה.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-operation-harvest-festival-140"]={"title":"מבצע חג הקציר","location":"מחוז לובלין, פולין הכבושה בידי גרמניה","story":"אנשי אס־אס ומשטרה גרמנים רצחו עשרות אלפי עובדי כפייה יהודים במחוז לובלין במהלך מבצע חג הקציר בנובמבר 1943.","context":"המבצע נועד לחסל את האוכלוסייה היהודית שנותרה במחנות עבודת הכפייה המרכזיים באזור לובלין.","aftermath":"זה היה אחד ממבצעי הירי ההמוני הגדולים ביותר שביצעו הגרמנים נגד יהודים ביום ובפרק זמן קצר.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-bia-ystok-ghetto-uprising-141"]={"title":"מרד גטו ביאליסטוק","location":"ביאליסטוק, פולין הכבושה","story":"כאשר הכוחות הגרמניים החלו בחיסול הסופי של גטו ביאליסטוק באוגוסט 1943, פתחו לוחמי המחתרת היהודית במרד חמוש. ההתנגדות הוכרעה ורוב היהודים שנותרו גורשו למרכזי הרג ולמחנות.","context":"המרד היה ניסיון התנגדות מאורגן מול חיסול הגטו וגירוש תושביו.","aftermath":"רוב הקהילה שנותרה גורשה או נרצחה לאחר דיכוי ההתנגדות.","sourceStatus":"מתועד היטב ברשומות גרמניות, בדיווחי מחתרת ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-sobibor-uprising-and-mass-escape-142"]={"title":"מרד סוביבור והבריחה ההמונית","location":"מרכז ההרג סוביבור, פולין הכבושה","story":"ב־14 באוקטובר 1943 ארגנו אסירים יהודים בסוביבור מרד, הרגו כמה אנשי אס־אס ושומרים וניסו בריחה המונית. מאות פרצו מן המחנה; מספר קטן יותר שרד את המלחמה.","context":"המרד היה אחת מפעולות ההתנגדות הגדולות בתוך מרכז הרג נאצי.","aftermath":"המרד תרם להחלטה הגרמנית לפרק את מרכז ההרג ולטשטש את עקבותיו.","sourceStatus":"מתועד בהרחבה בעדויות ניצולים, ברשומות גרמניות ובחקירות שלאחר המלחמה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1943-treblinka-prisoner-uprising-143"]={"title":"מרד האסירים בטרבלינקה","location":"טרבלינקה II, פולין הכבושה","story":"ב־2 באוגוסט 1943 תפסו אסירים במרכז ההרג טרבלינקה נשק, הציתו חלקים מן המחנה וניסו בריחה המונית. מאות עברו את גדר המחנה, אך רבים ניצודו ונרצחו; מספר קטן יותר שרד את המלחמה.","context":"המרד היה התנגדות מאורגנת של אסירים בתוך אחד ממרכזי ההרג המרכזיים של מבצע ריינהרד.","aftermath":"המרד פגע במחנה והיה בין הגורמים שקדמו לפירוקו בידי הגרמנים.","sourceStatus":"המרד מתועד בהרחבה בעדויות ניצולים, ברשומות גרמניות ובמחקר שלאחר המלחמה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-deportation-of-hungarian-jews-to-auschwitz-birkenau-144"]={"title":"גירוש יהודי הונגריה לאושוויץ־בירקנאו","location":"הונגריה → אושוויץ־בירקנאו","story":"לאחר שגרמניה כבשה את הונגריה במרץ 1944 ריכזו וגירשו הרשויות ההונגריות, בשיתוף אנשי אס־אס גרמנים, יהודים במהירות. בין מאי ליולי גורשו כ־440,000 יהודים, רובם לאושוויץ־בירקנאו, ושם נרצח רובם.","context":"הגירושים היו מן המבצעים המהירים והגדולים ביותר של השלב האחרון בשואה.","aftermath":"בתוך שבועות ספורים הושמד חלק עצום מיהדות הונגריה שמחוץ לבודפשט.","sourceStatus":"מתועד בהרחבה ברשומות גירוש, תיעוד גרמני והונגרי, תצלומים ועדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-auschwitz-sonderkommando-revolt-145"]={"title":"מרד הזונדרקומנדו באושוויץ","location":"אושוויץ־בירקנאו, פולין הכבושה","story":"ב־7 באוקטובר 1944 מרדו אסירי זונדרקומנדו יהודים באושוויץ־בירקנאו. הם תקפו שומרי אס־אס ופגעו בקרמטוריום IV באמצעות חומרי נפץ שהוברחו בידי אסירות יהודיות שעבדו במפעל סמוך.","context":"המרד היה ניסיון התנגדות של אסירים שנכפו לעבוד במתקני הרצח והשרפה.","aftermath":"המרד דוכא והמשתתפים הוצאו להורג, אך הקרמטוריום ניזוק והאירוע נעשה סמל להתנגדות בתוך אושוויץ.","sourceStatus":"מתועד בהרחבה ברשומות המחנה ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1944-liquidation-of-the-d-ghetto-146"]={"title":"חיסול גטו לודז'","location":"לודז', פולין הכבושה","story":"ב־1944 חיסלו הרשויות הגרמניות את גטו לודז', מן הגטאות הגדולים והממושכים בפולין הכבושה. רוב היהודים שנותרו גורשו לאושוויץ־בירקנאו, לאחר שגירושים קודמים שלחו עשרות אלפים לחלמנו.","context":"החיסול היה השלב האחרון בפירוק אחת הקהילות היהודיות הגדולות שנותרו בגטאות.","aftermath":"רוב תושבי הגטו שנותרו גורשו למרכזי הרג ורק מיעוט שרד.","sourceStatus":"החיסול והגירושים מתועדים בהרחבה ברשומות גרמניות, בתיעוד הגטו ובעדויות ניצולים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1945-death-marches-during-the-collapse-of-nazi-germany-147"]={"title":"צעדות המוות בזמן קריסת גרמניה הנאצית","location":"מרכז ומזרח אירופה","story":"כאשר צבאות בעלות הברית התקרבו למחנות הריכוז, פינו אנשי האס־אס אסירים לעומק גרמניה. אסירים, ובהם יהודים רבים, אולצו לצעוד ולהיטלטל בתנאי חורף קשים; שומרים רצחו מי שלא יכלו להמשיך ורבים אחרים מתו מחשיפה, רעב ותשישות.","context":"הפינויים נועדו להעביר אסירים הרחק מהצבאות המתקדמים והפכו לשלב קטלני נוסף בחודשי המלחמה האחרונים.","aftermath":"עשרות אלפי אסירים מתו בצעדות ובפינויים לפני שחרור המחנות וסיום המלחמה.","sourceStatus":"מתועד בהרחבה בפינויים רבים; המספרים הכוללים משתנים משום שהתרחשו צעדות רבות ונפרדות"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-belzec-killing-center-133"]={"title":"مركز القتل بيلجيتس","location":"بيلجيتس، بولندا المحتلة ألمانيًا","story":"أصبح بيلجيتس مركز قتل ضمن عملية راينهارد. وقُتل فيه نحو 435 ألف يهودي، غالبيتهم الساحقة في غرف الغاز.","context":"كان بيلجيتس أحد مراكز القتل الثلاثة الرئيسية لعملية راينهارد الهادفة إلى إبادة يهود الحكومة العامة.","aftermath":"قُتل تقريبًا جميع المرحلين إلى بيلجيتس وفُكك المعسكر بعد انتهاء عمليات القتل الرئيسية.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-sobibor-killing-center-134"]={"title":"مركز القتل سوبيبور","location":"سوبيبور، بولندا المحتلة ألمانيًا","story":"أُنشئ سوبيبور كمركز قتل ضمن عملية راينهارد. وقُتل فيه ما لا يقل عن 167 ألف يهودي.","context":"خُصص المعسكر أساسًا للقتل الجماعي لليهود المرحلين من مناطق مختلفة من أوروبا المحتلة.","aftermath":"بعد انتفاضة السجناء سنة 1943 فكك الألمان المعسكر وحاولوا إخفاء آثاره.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-treblinka-ii-killing-center-135"]={"title":"مركز القتل تريبلينكا الثاني","location":"تريبلينكا، بولندا المحتلة ألمانيًا","story":"عمل تريبلينكا الثاني كمركز قتل ضمن عملية راينهارد. وقتل النازيون فيه ما يقدر بنحو 925 ألف يهودي.","context":"كان تريبلينكا من أكثر مواقع القتل الجماعي فتكًا في الهولوكوست.","aftermath":"بعد انتفاضة السجناء سنة 1943 فُكك الموقع وجرت محاولات لإخفاء دوره.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-auschwitz-birkenau-mass-murder-of-jews-136"]={"title":"القتل الجماعي لليهود في أوشفيتز-بيركيناو","location":"أوشفيتز-بيركيناو، بولندا المحتلة ألمانيًا","story":"أصبح أوشفيتز-بيركيناو أكبر مجمع نازي للاعتقال والقتل. وقُتل نحو مليون يهودي في مجمع أوشفيتز.","context":"جمع الموقع بين معسكر اعتقال والعمل القسري ونظام للقتل الجماعي، خصوصًا بغرف الغاز.","aftermath":"أصبح أوشفيتز أحد أبرز رموز الهولوكوست وقتل يهود أوروبا.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-great-action-deportation-of-warsaw-jews-to-treblinka-137"]={"title":"العملية الكبرى: ترحيل يهود وارسو إلى تريبلينكا","location":"وارسو، بولندا المحتلة ألمانيًا","story":"من يوليو إلى سبتمبر 1942 رحلت السلطات الألمانية نحو 265 ألف يهودي من غيتو وارسو إلى تريبلينكا وقتلت نحو 35 ألف يهودي داخل الغيتو خلال العملية.","context":"كان الترحيل جزءًا من عملية راينهارد ومن تدمير المجتمعات اليهودية في بولندا المحتلة.","aftermath":"رُحل وقُتل معظم سكان الغيتو، ونظم من تبقى لاحقًا مقاومة مسلحة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1942-operation-reinhard-138"]={"title":"عملية راينهارد","location":"بولندا المحتلة ألمانيًا","story":"كانت عملية راينهارد البرنامج النازي لقتل يهود الحكومة العامة في بولندا المحتلة. وكانت مراكز القتل الرئيسية بيلجيتس وسوبيبور وتريبلينكا، إلى جانب الترحيل وإطلاق النار الجماعي.","context":"هذا حدث شامل؛ وتمثل مراكز القتل وعمليات الترحيل الرئيسية أيضًا كأحداث منفصلة في الخط الزمني.","aftermath":"أبادت العملية معظم المجتمعات اليهودية في المنطقة وكانت عنصرًا مركزيًا في الحل النهائي.","sourceStatus":"موثق على نطاق واسع؛ توفر مؤشرات منفصلة تقديرات أكثر تحديدًا للضحايا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-warsaw-ghetto-uprising-139"]={"title":"انتفاضة غيتو وارسو","location":"وارسو، بولندا المحتلة ألمانيًا","story":"قاوم مقاتلون يهود عملية الترحيل الألمانية النهائية التي بدأت في 19 أبريل 1943. ومات ما لا يقل عن 7,000 يهودي في القتال أو المخابئ بينما دمرت القوات الألمانية الغيتو.","context":"كانت الانتفاضة مقاومة يهودية مسلحة لتصفية الغيتو وترحيل سكانه.","aftermath":"قُمعت الانتفاضة ودُمر الغيتو، لكنها أصبحت رمزًا مركزيًا للمقاومة اليهودية في الهولوكوست.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-operation-harvest-festival-140"]={"title":"عملية مهرجان الحصاد","location":"منطقة لوبلين، بولندا المحتلة ألمانيًا","story":"قتل أفراد الإس إس والشرطة الألمانية عشرات الآلاف من عمال السخرة اليهود في منطقة لوبلين خلال عملية مهرجان الحصاد في نوفمبر 1943.","context":"هدفت العملية إلى تصفية السكان اليهود الباقين في معسكرات العمل القسري الرئيسية في منطقة لوبلين.","aftermath":"كانت من أكبر عمليات إطلاق النار الجماعي التي نفذها الألمان ضد اليهود في يوم واحد وفترة قصيرة.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-bia-ystok-ghetto-uprising-141"]={"title":"انتفاضة غيتو بياليستوك","location":"بياليستوك، بولندا المحتلة","story":"عندما بدأت القوات الألمانية التصفية النهائية لغيتو بياليستوك في أغسطس 1943 أطلق مقاتلو المقاومة اليهودية انتفاضة مسلحة. وهُزمت المقاومة ورُحل معظم اليهود الباقين إلى مراكز القتل والمعسكرات.","context":"كانت الانتفاضة محاولة مقاومة منظمة ضد تصفية الغيتو وترحيل سكانه.","aftermath":"رُحل أو قُتل معظم من بقي من المجتمع بعد قمع المقاومة.","sourceStatus":"موثق جيدًا في السجلات الألمانية وتقارير المقاومة وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-sobibor-uprising-and-mass-escape-142"]={"title":"انتفاضة سوبيبور والهروب الجماعي","location":"مركز القتل سوبيبور، بولندا المحتلة","story":"في 14 أكتوبر 1943 نظم سجناء يهود في سوبيبور انتفاضة وقتلوا عدة أفراد من الإس إس والحراس وحاولوا الهرب جماعيًا. وخرج المئات من المعسكر؛ ونجا عدد أقل من الحرب.","context":"كانت الانتفاضة من أكبر أعمال المقاومة داخل مركز قتل نازي.","aftermath":"ساهمت الانتفاضة في قرار الألمان تفكيك مركز القتل وإخفاء آثاره.","sourceStatus":"موثق على نطاق واسع بشهادات الناجين والسجلات الألمانية وتحقيقات ما بعد الحرب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1943-treblinka-prisoner-uprising-143"]={"title":"انتفاضة سجناء تريبلينكا","location":"تريبلينكا الثاني، بولندا المحتلة","story":"في 2 أغسطس 1943 استولى سجناء في مركز قتل تريبلينكا على أسلحة وأشعلوا أجزاء من المعسكر وحاولوا هروبًا جماعيًا. وعبر المئات محيط المعسكر، لكن كثيرين طوردوا وقُتلوا؛ ونجا عدد أقل من الحرب.","context":"كانت الانتفاضة مقاومة منظمة من السجناء داخل أحد مراكز القتل الرئيسية لعملية راينهارد.","aftermath":"ألحقت الانتفاضة أضرارًا بالمعسكر وكانت من التطورات التي سبقت تفكيكه على يد الألمان.","sourceStatus":"موثق على نطاق واسع بشهادات الناجين والسجلات الألمانية وأبحاث ما بعد الحرب"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-deportation-of-hungarian-jews-to-auschwitz-birkenau-144"]={"title":"ترحيل يهود المجر إلى أوشفيتز-بيركيناو","location":"المجر ← أوشفيتز-بيركيناو","story":"بعد احتلال ألمانيا للمجر في مارس 1944 جمعت السلطات المجرية، بالتعاون مع مسؤولي الإس إس الألمان، اليهود ورحلتهم بسرعة. وبين مايو ويوليو رُحل نحو 440 ألف يهودي، معظمهم إلى أوشفيتز-بيركيناو حيث قُتل غالبيتهم.","context":"كانت عمليات الترحيل من أسرع وأكبر عمليات المرحلة الأخيرة من الهولوكوست.","aftermath":"خلال أسابيع دُمر جزء هائل من يهود المجر خارج بودابست.","sourceStatus":"موثق على نطاق واسع بسجلات الترحيل والوثائق الألمانية والمجرية والصور وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-auschwitz-sonderkommando-revolt-145"]={"title":"تمرد السوندركوماندو في أوشفيتز","location":"أوشفيتز-بيركيناو، بولندا المحتلة","story":"في 7 أكتوبر 1944 تمرد سجناء يهود من السوندركوماندو في أوشفيتز-بيركيناو. وهاجموا حراس الإس إس وألحقوا أضرارًا بالمحرقة الرابعة بمتفجرات هربتها سجينات يهوديات يعملن في مصنع قريب.","context":"كان التمرد محاولة مقاومة من سجناء أُجبروا على العمل في منشآت القتل والحرق.","aftermath":"قُمع التمرد وأُعدم المشاركون، لكن المحرقة تضررت وأصبح الحدث رمزًا للمقاومة داخل أوشفيتز.","sourceStatus":"موثق على نطاق واسع في سجلات المعسكر وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1944-liquidation-of-the-d-ghetto-146"]={"title":"تصفية غيتو لودج","location":"لودج، بولندا المحتلة","story":"في 1944 صفّت السلطات الألمانية غيتو لودج، أحد أكبر وأطول الغيتوات بقاءً في بولندا المحتلة. ورُحل معظم اليهود الباقين إلى أوشفيتز-بيركيناو، بعد أن أرسلت ترحيلات سابقة عشرات الآلاف إلى خيلمنو.","context":"كانت التصفية المرحلة الأخيرة في تفكيك أحد أكبر المجتمعات اليهودية المتبقية في الغيتوات.","aftermath":"رُحل معظم السكان الباقين إلى مراكز القتل ولم ينجُ إلا عدد قليل.","sourceStatus":"التصفية والترحيلات موثقة على نطاق واسع في السجلات الألمانية ووثائق الغيتو وشهادات الناجين"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1945-death-marches-during-the-collapse-of-nazi-germany-147"]={"title":"مسيرات الموت أثناء انهيار ألمانيا النازية","location":"وسط وشرق أوروبا","story":"مع اقتراب جيوش الحلفاء من معسكرات الاعتقال أخلى الإس إس السجناء نحو داخل ألمانيا. وأُجبر السجناء، ومنهم أعداد كبيرة من اليهود، على المسير والنقل في ظروف شتوية قاسية؛ وقتل الحراس من لم يستطيعوا المتابعة ومات آخرون من البرد والجوع والإرهاق.","context":"هدفت عمليات الإخلاء إلى نقل السجناء بعيدًا عن الجيوش المتقدمة وأصبحت مرحلة قاتلة إضافية في الأشهر الأخيرة للحرب.","aftermath":"مات عشرات الآلاف من السجناء في المسيرات والإجلاء قبل تحرير المعسكرات ونهاية الحرب.","sourceStatus":"موثق على نطاق واسع عبر عمليات إخلاء عديدة؛ تختلف الأعداد الإجمالية لأن مسيرات منفصلة كثيرة وقعت"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1946-kielce-pogrom-148"]={"title":"פוגרום קיילצה","location":"קיילצה, פולין","story":"המון, שאליו הצטרפו כמה שוטרים וחיילים, רצח ניצולי שואה יהודים ויהודים אחרים בקיילצה; לפחות 42 יהודים נרצחו.","context":"האירוע היה אלימות אנטי־יהודית לאחר השואה והמחיש את הסכנה שנמשכה עבור ניצולים שחזרו או ניסו לבנות מחדש את חייהם.","aftermath":"הפוגרום האיץ את יציאתם של יהודים רבים מפולין לאחר המלחמה והעמיק את תחושת חוסר הביטחון.","sourceStatus":"רמת ודאות גבוהה מאוד"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1946-king-david-hotel-bombing-149"]={"title":"פיצוץ מלון המלך דוד","location":"ירושלים, ארץ ישראל המנדטורית","story":"ב־22 ביולי 1946 פוצץ ארגון האצ״ל את האגף הדרומי של מלון המלך דוד בירושלים, שבו שכנו משרדי הממשל והצבא הבריטיים. 91 בני אדם נהרגו, ובהם ערבים, בריטים, יהודים ואחרים.","context":"הפיגוע היה חלק מן המאבק של ארגוני המחתרת היהודיים נגד שלטון המנדט הבריטי.","aftermath":"הפיצוץ החריף את העימות עם בריטניה והפך לאחד האירועים השנויים במחלוקת של תקופת המנדט.","sourceStatus":"הפיגוע, מבצעיו ומספר ההרוגים מתועדים בהרחבה; קיימת מחלוקת על האזהרות ועל תגובת הבריטים לפני הפיצוץ"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-fajja-bus-attacks-150"]={"title":"התקפות האוטובוסים ליד פג'ה","location":"ליד פתח תקווה, ארץ ישראל המנדטורית","story":"ב־30 בנובמבר 1947, יום לאחר הצבעת האו״ם על החלוקה, תקפו חמושים ערבים אוטובוסים יהודיים. ההתקפות היו בין האירועים הפותחים של שלב מלחמת האזרחים בסכסוך 1947–1949.","context":"האירוע התרחש מיד לאחר החלטת החלוקה ובתוך הסלמה מהירה של אלימות בין הקהילות.","aftermath":"ההתקפות סימנו את המעבר לעימות מזוין רחב יותר בארץ ישראל המנדטורית.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-1947-1949-palestine-war-arab-israeli-war-151"]={"title":"מלחמת 1947–1949 בארץ ישראל / מלחמת ערב–ישראל","location":"ארץ ישראל המנדטורית / ישראל","story":"הלחימה החלה לאחר הצבעת האו״ם על החלוקה; לאחר הכרזת העצמאות של ישראל במאי 1948 נכנסו צבאות ערביים שכנים למלחמה. אזרחים ולוחמים יהודים וערבים ספגו אבדות כבדות ועקירה.","context":"המלחמה כללה תחילה מלחמת אזרחים בין כוחות יהודיים וערביים ובהמשך מלחמה בין־מדינתית.","aftermath":"המלחמה הקימה את מדינת ישראל, שינתה גבולות, יצרה משברי פליטים ועקירה והותירה סכסוכים טריטוריאליים ופוליטיים בלתי פתורים.","sourceStatus":"רמת ודאות גבוהה מאוד; נרטיבים וחלק מן הנתונים שנויים במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1947-un-partition-plan-and-outbreak-of-civil-war-in-mandatory-palestine-152"]={"title":"תוכנית החלוקה של האו״ם ופרוץ מלחמת האזרחים בארץ ישראל המנדטורית","location":"ארץ ישראל המנדטורית","story":"ב־29 בנובמבר 1947 המליצה העצרת הכללית של האו״ם לחלק את הארץ למדינה ערבית ולמדינה יהודית, עם משטר בינלאומי לירושלים. הנהגת הסוכנות היהודית קיבלה את החלוקה כבסיס למדינה; מנהיגים ערבים דחו אותה. הלחימה בין כוחות ערביים פלסטיניים לכוחות יהודיים החריפה כמעט מיד.","context":"החלטה 181 הייתה המלצה בינלאומית לחלוקה והפכה לנקודת מפנה פוליטית ומלחמתית.","aftermath":"האלימות התרחבה במהירות והובילה למלחמת 1948, להקמת ישראל ולעקירה רחבת היקף.","sourceStatus":"החלטה 181 וההסלמה שאחריה מתועדות בהרחבה; פרשנויות לגבי אחריות, כוונות והוגנות התוכנית נותרו שנויות במחלוקת"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-hadassah-medical-convoy-massacre-153"]={"title":"טבח שיירת הדסה","location":"ירושלים","story":"באפריל 1948 ארב כוח ערבי לשיירה שהובילה אנשי רפואה ואספקה לבית החולים הדסה ולאוניברסיטה העברית בהר הצופים; 78 יהודים נהרגו.","context":"האירוע התרחש בתוך הקרבות והמצור סביב ירושלים במהלך מלחמת האזרחים של 1947–1948.","aftermath":"הטבח העמיק את האלימות והפגיעה בשירותים רפואיים ובגישה להר הצופים.","sourceStatus":"רמת ודאות גבוהה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-deir-yassin-massacre-154"]={"title":"טבח דיר יאסין","location":"דיר יאסין, ליד ירושלים","story":"ב־9 באפריל 1948 תקפו לוחמי האצ״ל ולח״י את הכפר הערבי הפלסטיני דיר יאסין. יותר ממאה מתושבי הכפר, ובהם אזרחים, נהרגו. הטבח הפך לסמל מרכזי של הסבל הפלסטיני ותרם לפחד במהלך מלחמת 1948.","context":"האירוע היה חלק ממלחמת האזרחים וחשוב להציגו לצד התקפות על יהודים ואירועי עקירה פלסטיניים באותה תקופה.","aftermath":"החדשות על הטבח תרמו לפחד ולבריחה במקומות אחרים והאירוע נותר מרכזי בזיכרון הפלסטיני.","sourceStatus":"ההתקפה והרג אזרחים מתועדים היטב; המספר המדויק וחלק מפרטי הקרב נדונו במחקר, והערכות מודרניות מציבות בדרך כלל את מספר ההרוגים סביב 100–110"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-kfar-etzion-massacre-155"]={"title":"טבח כפר עציון","location":"כפר עציון, דרומית לירושלים","story":"ב־13 במאי 1948 נפל כפר עציון לידי הלגיון הערבי וכוחות ערביים מקומיים לאחר לחימה ממושכת. מספר גדול של מגינים ותושבים יהודים נהרגו לאחר קריסת ההגנה ורק מעטים שרדו. יתר יישובי גוש עציון נכנעו למחרת.","context":"האירוע התרחש בשלב האחרון של מלחמת האזרחים, ערב סיום המנדט הבריטי.","aftermath":"נפילת הגוש נעשתה סמל מרכזי בזיכרון הישראלי של מלחמת 1948.","sourceStatus":"נפילת כפר עציון וההרג ההמוני מתועדים היטב; המקורות שונים לגבי הנסיבות המדויקות של מות יחידים לאחר הכניעה"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-declaration-of-the-state-of-israel-156"]={"title":"הכרזת מדינת ישראל","location":"תל אביב","story":"ב־14 במאי 1948 הכריז דוד בן־גוריון על הקמת מדינת ישראל עם סיום המנדט הבריטי. ההכרזה הפכה את מלחמת האזרחים המתמשכת לעימות בין־מדינתי כאשר צבאות ערביים שכנים נכנסו לשטח המנדט לשעבר.","context":"האירוע היה נקודת מעבר מרכזית מהיישוב היהודי למדינה ריבונית בתוך מלחמה פעילה.","aftermath":"ישראל קמה כמדינה, והמלחמה התרחבה מיד עם התערבות צבאות ערב.","sourceStatus":"ההכרזה והמעבר הצבאי המיידי מתועדים ישירות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-arab-armies-enter-palestine-and-the-first-arab-israeli-war-expands-157"]={"title":"צבאות ערב נכנסים לארץ והמלחמה הערבית–ישראלית הראשונה מתרחבת","location":"ישראל / שטח ארץ ישראל המנדטורית לשעבר","story":"החל ב־15 במאי נכנסו צבאות מצרים, עבר הירדן, סוריה, עיראק ולבנון למלחמה בעקבות הכרזת העצמאות של ישראל. המלחמה כללה כעת את המדינה הישראלית החדשה, כוחות ערביים פלסטיניים ומספר מדינות ערביות שכנות.","context":"לממשלות ערב השונות היו מטרות צבאיות ופוליטיות שונות, ולכן אין לתאר את ההתערבות כאסטרטגיה אחידה לחלוטין.","aftermath":"העימות התרחב למלחמה בין־מדינתית שהסתיימה בהסכמי שביתת הנשק של 1949.","sourceStatus":"התערבות צבאות ערב השכנים מתועדת בהרחבה; המטרות והחישובים הפוליטיים השתנו בין הממשלות"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-fall-of-the-jewish-quarter-of-jerusalem-s-old-city-158"]={"title":"נפילת הרובע היהודי בעיר העתיקה בירושלים","location":"ירושלים","story":"לאחר מצור ולחימה נכנע הרובע היהודי בעיר העתיקה ללגיון הערבי של עבר הירדן ב־28 במאי 1948. התושבים היהודים פונו מן הרובע והמגינים שנותרו בחיים נשבו. בתי כנסת ואתרים יהודיים נוספים ניזוקו או נהרסו לאחר מכן בתקופת השלטון הירדני.","context":"האירוע היה חלק מן המאבק על ירושלים במלחמת 1948.","aftermath":"העיר העתיקה נותרה בשליטה ירדנית עד 1967 ותושביה היהודים של הרובע לא יכלו לשוב בתקופה זו.","sourceStatus":"הכניעה והפינוי מתועדים היטב; תיאורי ההרס המאוחר משתנים לפי האתר והמקור"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-lydda-and-ramle-fighting-killings-and-palestinian-expulsion-159"]={"title":"לוד ורמלה: לחימה, הרג וגירוש פלסטינים","location":"לוד ורמלה","story":"כוחות ישראליים כבשו את לוד ורמלה ביולי 1948 במסגרת מבצע דני. אזרחים נהרגו במהלך הלחימה בלוד, ולאחר מכן רוב האוכלוסייה הערבית הפלסטינית של שתי הערים גורשה או נאלצה לברוח מזרחה. האירוע מרכזי בוויכוח ההיסטורי על משבר הפליטים הפלסטינים.","context":"האירוע מדגים שגם פעולות צבאיות ישראליות וגירוש פלסטינים הם חלק הכרחי מן התמונה המלאה של מלחמת 1948.","aftermath":"עשרות אלפי פלסטינים נעקרו והערים עברו לשליטה ישראלית.","sourceStatus":"הכיבוש והעקירה ההמונית מתועדים היטב; היסטוריונים חלוקים לגבי היבטים של הפקודות, מספרי ההרוגים והמנגנונים המדויקים של הגירוש"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-palestinian-refugee-and-displacement-crisis-160"]={"title":"משבר הפליטים והעקירה הפלסטיני","location":"פלסטין / מדינות ערב השכנות","story":"במהלך מלחמת 1947–1949 מאות אלפי ערבים פלסטינים ברחו או גורשו מבתיהם בשטח שהפך לישראל. הסיבות השתנו לפי מקום ושלב במלחמה וכללו גירוש ישיר, בריחה מקרבות, פחד מהתקפה והתמוטטות החברה הפלסטינית. ישראל מנעה בדרך כלל מרוב הפליטים לשוב לאחר המלחמה.","context":"העקירה ההמונית אינה שנויה במחלוקת, אך המשקל היחסי של הסיבות והאחריות במקומות מסוימים נותר נושא מרכזי למחלוקת היסטורית ופוליטית.","aftermath":"משבר הפליטים נעשה אחת הסוגיות המרכזיות והמתמשכות בסכסוך הישראלי–פלסטיני.","sourceStatus":"העקירה רחבת ההיקף אינה שנויה במחלוקת; מאזן הסיבות והאחריות ביישובים מסוימים נותר אחד הנושאים השנויים ביותר במחלוקת בתולדות הסכסוך"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1948-assassination-of-un-mediator-folke-bernadotte-161"]={"title":"רצח מתווך האו״ם פולקה ברנדוט","location":"ירושלים","story":"ב־17 בספטמבר 1948 נרצח בירושלים מתווך האו״ם הרוזן פולקה ברנדוט בידי חברי לח״י, ארגון מחתרת יהודי. ברנדוט מונה לתווך במלחמה הערבית–ישראלית והציע הסדרים בנושאי גבולות, ירושלים ופליטים.","context":"האירוע מתעד אלימות פוליטית שביצע ארגון יהודי ואינו מוצג כאירוע שבו יהודים היו הקורבנות.","aftermath":"הרצח עורר גינוי בינלאומי והאיץ צעדים ישראליים נגד לח״י.","sourceStatus":"הרצח ואחריות לח״י מתועדים היטב ברשומות האו״ם ובמקורות היסטוריים"};
window.FALLING_TRANSLATIONS.he.jewish["jewish-1949-1949-armistice-agreements-end-major-fighting-162"]={"title":"הסכמי שביתת הנשק של 1949 מסיימים את הלחימה העיקרית","location":"ישראל ומדינות ערב השכנות","story":"ישראל חתמה ב־1949 על הסכמי שביתת נשק נפרדים עם מצרים, לבנון, ירדן וסוריה. ההסכמים סיימו את הלחימה הבין־מדינתית העיקרית אך לא יצרו הסכמי שלום כוללים. קווי שביתת הנשק נעשו הגבולות המעשיים עד מלחמת 1967.","context":"ההסכמים סיימו את השלב הצבאי העיקרי של מלחמת 1948 בלי לפתור את הסכסוך הרחב.","aftermath":"הגבולות, סוגיית הפליטים ומעמד ירושלים נותרו בלתי פתורים והמשיכו לעצב את הסכסוכים הבאים.","sourceStatus":"ההסכמים וקווי שביתת הנשק מתועדים ישירות ברשומות האו״ם"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1946-kielce-pogrom-148"]={"title":"بوغروم كيلتسه","location":"كيلتسه، بولندا","story":"قتل حشد انضم إليه بعض أفراد الشرطة والجنود ناجين يهودًا من الهولوكوست ويهودًا آخرين في كيلتسه؛ وقُتل ما لا يقل عن 42 يهوديًا.","context":"كان الحدث عنفًا معاديًا لليهود بعد الهولوكوست وأظهر استمرار الخطر على الناجين العائدين أو الساعين لإعادة بناء حياتهم.","aftermath":"سرّع البوغروم خروج كثير من اليهود من بولندا بعد الحرب وعمق الشعور بانعدام الأمن.","sourceStatus":"ثقة عالية جدًا"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1946-king-david-hotel-bombing-149"]={"title":"تفجير فندق الملك داود","location":"القدس، فلسطين الانتدابية","story":"في 22 يوليو 1946 فجر تنظيم الإرغون اليهودي الجناح الجنوبي من فندق الملك داود في القدس، حيث كانت توجد مكاتب إدارية وعسكرية بريطانية. قُتل 91 شخصًا بينهم عرب وبريطانيون ويهود وآخرون.","context":"كان التفجير جزءًا من صراع التنظيمات السرية اليهودية ضد حكم الانتداب البريطاني.","aftermath":"صعّد التفجير المواجهة مع بريطانيا وأصبح من أكثر أحداث عهد الانتداب إثارة للجدل.","sourceStatus":"الهجوم ومنفذوه وعدد القتلى موثقون على نطاق واسع؛ يستمر الخلاف حول التحذيرات والاستجابة البريطانية قبل الانفجار"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-fajja-bus-attacks-150"]={"title":"هجمات حافلات فجة","location":"قرب بتاح تكفا، فلسطين الانتدابية","story":"في 30 نوفمبر 1947، بعد يوم من تصويت الأمم المتحدة على التقسيم، هاجم مسلحون عرب حافلات يهودية، وكانت الهجمات من الوقائع الافتتاحية لمرحلة الحرب الأهلية في صراع 1947–1949.","context":"وقعت الحادثة مباشرة بعد قرار التقسيم وسط تصاعد سريع للعنف بين المجتمعين.","aftermath":"أشارت الهجمات إلى الانتقال نحو صراع مسلح أوسع في فلسطين الانتدابية.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-1947-1949-palestine-war-arab-israeli-war-151"]={"title":"حرب فلسطين 1947–1949 / الحرب العربية الإسرائيلية","location":"فلسطين الانتدابية / إسرائيل","story":"اندلع القتال بعد تصويت الأمم المتحدة على التقسيم؛ وبعد إعلان إسرائيل استقلالها في مايو 1948 دخلت جيوش عربية مجاورة الحرب. وتكبد المدنيون والمقاتلون اليهود والعرب خسائر كبيرة وتهجيرًا.","context":"شملت الحرب أولًا حربًا أهلية بين قوات يهودية وعربية ثم تحولت إلى حرب بين دول.","aftermath":"أنشأت الحرب دولة إسرائيل وغيرت الحدود وخلقت أزمات لجوء وتهجير وتركت نزاعات إقليمية وسياسية دون حل.","sourceStatus":"ثقة عالية جدًا؛ السرديات وبعض الأرقام موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1947-un-partition-plan-and-outbreak-of-civil-war-in-mandatory-palestine-152"]={"title":"خطة الأمم المتحدة للتقسيم واندلاع الحرب الأهلية في فلسطين الانتدابية","location":"فلسطين الانتدابية","story":"في 29 نوفمبر 1947 أوصت الجمعية العامة للأمم المتحدة بتقسيم فلسطين إلى دولتين عربية ويهودية مع نظام دولي للقدس. قبل قادة الوكالة اليهودية التقسيم أساسًا لإقامة دولة، ورفضه القادة العرب. وتصاعد القتال بين القوات العربية الفلسطينية واليهودية فورًا تقريبًا.","context":"كان القرار 181 توصية دولية بالتقسيم وأصبح نقطة تحول سياسية وعسكرية.","aftermath":"اتسع العنف بسرعة وقاد إلى حرب 1948 وقيام إسرائيل وتهجير واسع.","sourceStatus":"قرار 181 والتصعيد اللاحق موثقان على نطاق واسع؛ تبقى تفسيرات المسؤولية والنوايا وعدالة الخطة موضع خلاف"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-hadassah-medical-convoy-massacre-153"]={"title":"مذبحة قافلة هداسا الطبية","location":"القدس","story":"في أبريل 1948 نصب مسلحون عرب كمينًا لقافلة تقل عاملين طبيين وإمدادات إلى مستشفى هداسا والجامعة العبرية على جبل المشارف؛ وقُتل 78 يهوديًا.","context":"وقعت الحادثة ضمن القتال والحصار حول القدس أثناء مرحلة الحرب الأهلية من صراع 1947–1948.","aftermath":"عمقت المذبحة العنف وأثرت في الخدمات الطبية والوصول إلى جبل المشارف.","sourceStatus":"ثقة عالية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-deir-yassin-massacre-154"]={"title":"مذبحة دير ياسين","location":"دير ياسين، قرب القدس","story":"في 9 أبريل 1948 هاجم مقاتلو الإرغون وليحي قرية دير ياسين العربية الفلسطينية. وقُتل أكثر من مئة من سكان القرية، بينهم مدنيون. وأصبحت المذبحة رمزًا رئيسيًا للمعاناة الفلسطينية وأسهمت في الخوف خلال حرب 1948.","context":"كانت الحادثة جزءًا من الحرب الأهلية، ومن الضروري عرضها إلى جانب الهجمات على اليهود ووقائع التهجير الفلسطيني في الفترة نفسها.","aftermath":"ساهمت أخبار المذبحة في الخوف والفرار في أماكن أخرى وظلت مركزية في الذاكرة الفلسطينية.","sourceStatus":"الهجوم وقتل المدنيين موثقان بقوة؛ نوقش العدد الدقيق وبعض تفاصيل المعركة، وتضع الدراسات الحديثة عدد القتلى عادة في حدود 100–110"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-kfar-etzion-massacre-155"]={"title":"مذبحة كفار عتصيون","location":"كفار عتصيون، جنوب القدس","story":"في 13 مايو 1948 سقطت كفار عتصيون أمام الفيلق العربي وقوات عربية محلية بعد قتال طويل. وقُتل عدد كبير من المدافعين والسكان اليهود بعد انهيار الدفاعات ولم ينجُ إلا قليلون. واستسلمت بقية مستوطنات كتلة عتصيون في اليوم التالي.","context":"وقعت الحادثة في المرحلة الأخيرة من الحرب الأهلية عشية انتهاء الانتداب البريطاني.","aftermath":"أصبح سقوط الكتلة رمزًا مهمًا في الذاكرة الإسرائيلية لحرب 1948.","sourceStatus":"سقوط كفار عتصيون والقتل الجماعي موثقان جيدًا؛ تختلف الروايات حول الظروف الدقيقة لبعض الوفيات بعد الاستسلام"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-declaration-of-the-state-of-israel-156"]={"title":"إعلان دولة إسرائيل","location":"تل أبيب","story":"في 14 مايو 1948 أعلن دافيد بن غوريون قيام دولة إسرائيل مع انتهاء الانتداب البريطاني. وحول الإعلان الحرب الأهلية الجارية إلى صراع بين دول عندما دخلت جيوش عربية مجاورة أراضي الانتداب السابق.","context":"كان الحدث نقطة انتقال رئيسية من المجتمع اليهودي المنظم في فلسطين إلى دولة ذات سيادة وسط حرب قائمة.","aftermath":"قامت إسرائيل كدولة واتسعت الحرب فور تدخل الجيوش العربية.","sourceStatus":"الإعلان والتحول العسكري المباشر موثقان بصورة مباشرة"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-arab-armies-enter-palestine-and-the-first-arab-israeli-war-expands-157"]={"title":"الجيوش العربية تدخل فلسطين وتتسع الحرب العربية الإسرائيلية الأولى","location":"إسرائيل / أراضي فلسطين الانتدابية السابقة","story":"ابتداءً من 15 مايو دخلت جيوش مصر وشرق الأردن وسوريا والعراق ولبنان الحرب بعد إعلان استقلال إسرائيل. وأصبح الصراع يشمل الدولة الإسرائيلية الجديدة والقوات العربية الفلسطينية وعدة دول عربية مجاورة.","context":"كانت للحكومات العربية المختلفة أهداف عسكرية وسياسية متباينة، لذلك لا ينبغي تصوير التدخل كاستراتيجية موحدة بالكامل.","aftermath":"اتسع الصراع إلى حرب بين دول انتهت باتفاقيات الهدنة سنة 1949.","sourceStatus":"تدخل الجيوش العربية المجاورة موثق على نطاق واسع؛ اختلفت الأهداف والحسابات السياسية بين الحكومات"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-fall-of-the-jewish-quarter-of-jerusalem-s-old-city-158"]={"title":"سقوط الحي اليهودي في البلدة القديمة بالقدس","location":"القدس","story":"بعد حصار وقتال استسلم الحي اليهودي في البلدة القديمة للفيلق العربي التابع لشرق الأردن في 28 مايو 1948. وأُجلي السكان اليهود وأصبح المدافعون الناجون أسرى حرب. وتضررت أو دُمرت لاحقًا معابد ومواقع يهودية أخرى خلال الحكم الأردني.","context":"كانت الحادثة جزءًا من الصراع على القدس في حرب 1948.","aftermath":"بقيت البلدة القديمة تحت السيطرة الأردنية حتى 1967 ولم يتمكن سكان الحي اليهود من العودة خلال تلك الفترة.","sourceStatus":"الاستسلام والإجلاء موثقان جيدًا؛ تختلف أوصاف الدمار اللاحق بحسب الموقع والمصدر"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-lydda-and-ramle-fighting-killings-and-palestinian-expulsion-159"]={"title":"اللد والرملة: قتال وقتل وطرد فلسطينيين","location":"اللد والرملة","story":"استولت القوات الإسرائيلية على اللد والرملة في يوليو 1948 خلال عملية داني. وقُتل مدنيون أثناء القتال في اللد، ثم طُرد أو أُجبر معظم السكان العرب الفلسطينيين في المدينتين على الفرار شرقًا. وتبقى الحادثة مركزية في النقاش التاريخي حول أزمة اللاجئين الفلسطينيين.","context":"توضح الحادثة أن العمليات العسكرية الإسرائيلية وتهجير الفلسطينيين جزء ضروري من الصورة الكاملة لحرب 1948.","aftermath":"هُجر عشرات الآلاف من الفلسطينيين وانتقلت المدينتان إلى السيطرة الإسرائيلية.","sourceStatus":"الاستيلاء والتهجير الجماعي موثقان بقوة؛ يناقش المؤرخون جوانب الأوامر وأعداد القتلى والآليات الدقيقة للطرد"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-palestinian-refugee-and-displacement-crisis-160"]={"title":"أزمة اللاجئين والتهجير الفلسطيني","location":"فلسطين / الدول العربية المجاورة","story":"خلال حرب 1947–1949 فر أو طُرد مئات الآلاف من العرب الفلسطينيين من منازلهم في الأراضي التي أصبحت إسرائيل. واختلفت الأسباب بحسب المكان ومرحلة الحرب وشملت الطرد المباشر والفرار من القتال والخوف من الهجوم وانهيار المجتمع الفلسطيني. ومنعت إسرائيل عمومًا معظم اللاجئين من العودة بعد الحرب.","context":"التهجير واسع النطاق غير محل نزاع، لكن الوزن النسبي للأسباب والمسؤولية في مواقع محددة ما يزال موضوعًا رئيسيًا للخلاف التاريخي والسياسي.","aftermath":"أصبحت أزمة اللاجئين إحدى القضايا المركزية والدائمة في الصراع الإسرائيلي الفلسطيني.","sourceStatus":"التهجير واسع النطاق غير محل نزاع؛ يظل توازن الأسباب والمسؤولية في مناطق بعينها من أكثر موضوعات تاريخ الصراع إثارة للجدل"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1948-assassination-of-un-mediator-folke-bernadotte-161"]={"title":"اغتيال وسيط الأمم المتحدة فولكه برنادوت","location":"القدس","story":"في 17 سبتمبر 1948 اغتال أعضاء من ليحي، وهو تنظيم مسلح يهودي، وسيط الأمم المتحدة الكونت فولكه برنادوت في القدس. وكان قد عُين للتوسط في الحرب العربية الإسرائيلية واقترح ترتيبات للحدود والقدس واللاجئين.","context":"يوثق الحدث عنفًا سياسيًا نفذه تنظيم يهودي ولا يُعرض كحادثة كان اليهود فيها الضحايا.","aftermath":"أثار الاغتيال إدانة دولية وسرّع إجراءات إسرائيلية ضد ليحي.","sourceStatus":"الاغتيال ومسؤولية ليحي موثقان بقوة في سجلات الأمم المتحدة والمصادر التاريخية"};
window.FALLING_TRANSLATIONS.ar.jewish["jewish-1949-1949-armistice-agreements-end-major-fighting-162"]={"title":"اتفاقيات هدنة 1949 تنهي القتال الرئيسي","location":"إسرائيل والدول العربية المجاورة","story":"وقعت إسرائيل اتفاقيات هدنة منفصلة مع مصر ولبنان والأردن وسوريا سنة 1949. وأنهت الاتفاقيات القتال الرئيسي بين الدول لكنها لم تنشئ معاهدات سلام شاملة. وأصبحت خطوط الهدنة الحدود العملية حتى حرب 1967.","context":"أنهت الاتفاقيات المرحلة العسكرية الرئيسية من حرب 1948 دون حل الصراع الأوسع.","aftermath":"ظلت الحدود وقضية اللاجئين ووضع القدس دون حل واستمرت في تشكيل النزاعات اللاحقة.","sourceStatus":"الاتفاقيات وخطوط الهدنة موثقة مباشرة في سجلات الأمم المتحدة"};